  ui_story_5014_50140101_37_dialog_content = "이건 아무래도 <color=#FFB400>위치 정보 신호</color>인 것 같아.",
  ui_story_5014_50140101_38_dialog_content = "내가 해석할 수 있는 건 좌표 범위 정도지만...",
  ui_story_5014_50140101_39_dialog_content = "좌표는 북방의 산맥 지역인 것 같아.",
