  ui_story_5014_50140101_42_dialog_content = "일루미나로 돌아가서 보고해야 하지 않아? 지체하지 않는 게 좋아.",
  ui_story_5014_50140101_43_dialog_content = "일루미나는 미개발 구역에 자주 사람을 파견해서 탐색을 진행하고 있어.\n어쩌면 누군가의 구조 요청 신호일지도 몰라...",
  ui_story_5014_50140101_44_dialog_content = "비록 표준 구조 요청 신호는 아니지만 말이야.",
