  ui_story_5014_50140101_56_dialog_content = "그건 뭐야?",
  ui_story_5014_50140101_57_dialog_content = "일루미나의 탐지기야. 이상 에너지를 탐지할 수 있어.\n네 콜로서스를 찾을 때도 이걸 사용했었어.",
  ui_story_5014_50140101_58_dialog_content = "원래는 이걸로 신호의 발생 방향을 탐지하려고 했는데...",
