  ui_story_5014_50140201_10_dialog_content = "갑자기 지진이 일어나서 땅이 무너졌어.\n그래서 우린 전부 균열로 떨어져 버린 거야.",
  ui_story_5014_50140201_11_dialog_content = "너무 갑작스러워서, 착지의 충격을 완화하는 정도밖에 할 수 없었어.",
