  ui_story_5014_50140201_14_dialog_content = "이 동굴... 꽤 크네. 어디로 이어지는 거지?",
  ui_story_5014_50140201_15_dialog_content = "왔던 길로 돌아갈 수 있을까?",
  ui_story_5014_50140201_16_dialog_content = "이미 시도해 봤어. 오던 길은 무너져서 완전히 막혀버렸어.",
