  ui_story_5014_50140201_20_dialog_content = "안 돼. 전혀 반응이 없어.",
  ui_story_5014_50140201_21_dialog_content = "나도 통신기로 일루미나 쪽과 콜로서스에 연락해 봤지만 안 되더라고.",
  ui_story_5014_50140201_22_dialog_content = "뭔가 특수한 에너지 필드 같은 게 통신 시스템을 방해하고 있는 것 같아.",
  ui_story_5014_50140201_23_dialog_content = "일루미나 쪽 사람들이 보낸 신호도, 내 탐지기도 모두 영향을 받았어.",
  ui_story_5014_50140201_24_dialog_content = "그러니까 우린 지금... 지하에 갇혀버린 거네.",
