  ui_story_5014_50140201_26_dialog_content = "자책할 거 없어. 이런 일은 아무도 예측할 수 없으니까.",
  ui_story_5014_50140201_27_dialog_content = "그리고 네 그런 열정과 탐구심 덕분에 우리가 만날 수 있었던 거잖아.",
  ui_story_5014_50140201_28_dialog_content = "신호를 보낸 사람도 분명 이런 식으로 지하에 갇힌 거겠지.",
  ui_story_5014_50140201_29_dialog_content = "동굴을 따라 앞으로 가 볼까? 누군가 찾을 수 있을지도 몰라.",
  ui_story_5014_50140201_30_dialog_content = "응, 나도 그러려던 참이었어.",
  ui_story_5014_50140201_31_dialog_content = "한 명이라도 사람이 늘면 그만큼 밖으로 나갈 수 있는 희망도 커질 테니까.",
  ui_story_5014_50140201_32_dialog_content = "그러니까 사람은 많을수록 좋아.",
  ui_story_5014_50140201_33_dialog_content = "게다가 이 일대는 툰드라 지역이야.",
  ui_story_5014_50140201_34_dialog_content = "운이 좋다면 이 동굴이 산골짜기나 평원으로 통해서 밖으로 나갈 수 있을 거야.",
  ui_story_5014_50140201_35_dialog_content = "하지만 카렌이 다쳤으니까... 우리 조금만 더 쉬자.",
  ui_story_5014_50140201_36_dialog_content = "말했잖아, 별거 아니라고. 가자, 서두르는 게 좋아.",
  ui_story_5014_50140201_37_dialog_content = "그럼 내가 부축해 줄게. 여긴 어두우니까 조심해.",
  ui_story_5014_50140201_38_dialog_content = "내가 앞장설게. 감각으로 길을 느끼면 되니까.",
  ui_story_5014_50140201_39_dialog_content = "<color=#e8d9bb>치직, 치지직.</color>",
  ui_story_5014_50140201_40_dialog_content = "바이스! 카렌! 저거 좀 봐!",
  ui_story_5014_50140201_41_dialog_content = "조명? 이미 고장 난 것 같네...",
  ui_story_5014_50140201_42_dialog_content = "이건 일루미나의 탐조등이야! 역시 여기 누가 있었어!",
  ui_story_5014_50140201_43_dialog_content = "계속 가 보자.",
  ui_story_5014_50140201_44_dialog_content = "<color=#e8d9bb>치직, 치지직.</color>",
  ui_story_5014_50140201_45_dialog_content = "휴우... 얼마나 온 거지? 나 이제 못 걷겠어...",
  ui_story_5014_50140201_46_dialog_content = "여기 정말 누가 있을까? 저 고장 난 조명 외에는 다른 아무런 흔적도 없어.",
  ui_story_5014_50140201_47_dialog_content = "나도 모르겠어... 어쨌든 일단 좀 쉬자.",
  ui_story_5014_50140201_48_dialog_content = "잠깐만, 뭔가 기류 같은 게 느껴져... 앞쪽이야!",
  ui_story_5014_50140201_49_dialog_content = "가서 확인해 보자!",
  ui_story_5014_50140201_50_dialog_content = "PlayerName, 이 벽을 따라 위로 가면... 빛이 보여!",
  ui_story_5014_50140201_51_dialog_content = "분명히 출구일 거야. 카렌! 출구를 찾았어!",
  ui_story_5014_50140201_52_dialog_content = "다행이네...",
  ui_story_5014_50140201_53_dialog_content = "카렌, 도와줄게. 조심해... 올라가자.",
  ui_story_5014_50140201_54_dialog_content = "나도 도와줄게.",
  ui_story_5014_50140201_55_dialog_content = "<color=#e8d9bb>치직, 치지직.</color>",
  ui_story_5014_50140201_56_dialog_content = "위에 무슨 맨홀뚜껑 같은 게 있는 것 같은데?",
  ui_story_5014_50140201_57_dialog_content = "맨홀뚜껑? 그럼 분명히 사람이 만든 거잖아...\n우리가 찾는 사람이 위에 있을지도 몰라!",
  ui_story_5014_50140201_58_dialog_content = "PlayerName, 내가 어떻게든 열어볼게...",
  ui_story_5014_50140201_59_dialog_content = "<color=#e8d9bb>콰직── 드르륵──</color>",
  ui_story_5014_50140201_60_dialog_content = "<color=#e8d9bb>휘이잉──</color>",
  ui_story_5014_50140201_61_dialog_content = "여긴...",
  ui_story_5014_50140201_62_dialog_content = "대체 어디지?!",
  ui_story_5014_50140201_63_dialog_content = "바이스... 이거... 꿈이야?",
  ui_story_5014_50140201_64_dialog_content = "지, 진정해. 카렌...",
  ui_story_5014_50140201_65_dialog_content = "여긴... 정말 따뜻하네... 하늘도 파랗고...",
  ui_story_5014_50140201_66_dialog_content = "게다가 산들바람도 불고 있어...",
  ui_story_5014_50140201_67_dialog_content = "설마...",
  ui_story_5014_50140201_68_dialog_content = "PlayerName, 저 높은 건물들도 좀 봐...",
  ui_story_5014_50140201_69_dialog_content = "응... 이건 꿈이 아니야...",
  ui_story_5014_50140201_70_dialog_content = "북방에 이런 곳이 있다는 말은... 들어본 적 없어.",
  ui_story_5014_50140201_71_dialog_content = "한번 살펴보자!",
  ui_story_5014_50140201_72_dialog_content = "<color=#e8d9bb>끼릭, 끼릭, 끼릭.</color>",
  ui_story_5014_50140201_73_dialog_content = "잠깐만, 바이스, 저쪽에서 이상한 소리가 나.",
  ui_story_5014_50140201_74_dialog_content = "뭔가 이상한 게 다가왔어. 조심해.",
  ui_story_5014_50140201_75_dialog_content = "<color=#e8d9bb>끼릭, 끼릭, 끼릭.</color>",
  ui_story_5014_50140201_76_dialog_content = "이게 뭐지?",
  ui_story_5014_50140201_77_dialog_content = "삑── 삐익──",
  ui_story_5014_50140201_78_dialog_content = "무슨 이상한 장치인 것 같은데.",
  ui_story_5014_50140201_79_dialog_content = "계속 「삑삑」 소리를 내고 있어.",
  ui_story_5014_50140201_80_dialog_content = "멀리 떨어지는 게 좋겠어.",
  ui_story_5014_50140201_81_dialog_content = "이건 로봇이야.",
  ui_story_5014_50140201_82_dialog_content = "일루미나의 로봇과는 전혀 다르긴 해도...",
  ui_story_5014_50140201_83_dialog_content = "콜로서스의 파이어플라이 같은 느낌인데? 뭔가 친근하게 느껴져.",
  ui_story_5014_50140201_84_dialog_content = "검사에 협조해 주십시오.",
  ui_story_5014_50140201_85_dialog_content = "말을 하잖아? 심지어 광선을 발사했어!",
  ui_story_5014_50140201_86_dialog_content = "괜찮아, 방금 「검사」하겠다고 했을 뿐이니까.",
  ui_story_5014_50140201_87_dialog_content = "그럼 저 동작이랑 광선은 우릴 스캔하는 거라고 생각해.",
  ui_story_5014_50140201_88_dialog_content = "어떻게 스캔하는 거지? 자세히 보고 싶어...",
  ui_story_5014_50140201_89_dialog_content = "경고, 경고, <color=#FFB400>복장 규정</color>을 위반하는 수상한 인원 발견.",
  ui_story_5014_50140201_90_dialog_content = "제압 및 체포를 실시한다.",
  ui_story_5014_50140201_91_dialog_content = "바이스, PlayerName, 그 기계한테서 떨어져!",
  ui_story_5014_50140202_1_dialog_content = "<color=#e8d9bb>콰쾅──!</color>",
  ui_story_5014_50140202_2_dialog_content = "이런, 망가져 버렸네.",
  ui_story_5014_50140202_3_dialog_content = "왜 갑자기 공격하려던 거지? 「복장 규정」은 또 뭔데?",
  ui_story_5014_50140202_4_dialog_content = "아무래도 매우 위험한 기계인 것 같아.",
  ui_story_5014_50140202_5_dialog_content = "저게 무엇이든 우린 조심해야 해.",
  ui_story_5014_50140202_6_dialog_content = "경고, 수상한 인원이 공무 집행을 방해하고 공공 기물을 파괴했다. 지원을 요청한다.",
  ui_story_5014_50140202_7_dialog_content = "이런, 지원을 불렀잖아. 큰일이야.",
  ui_story_5014_50140202_8_dialog_content = "아직 상황도 제대로 파악하지 못했으니까, 싸움은 피하는 게 좋아...",
  ui_story_5014_50140202_9_dialog_content = "아니면 일단 어디 숨는 게 어떨까?",
  ui_story_5014_50140202_10_dialog_content = "......",
  ui_story_5014_50140202_11_dialog_content = "거기 누구야?! 당장 나와!",
  ui_story_5014_50140202_12_dialog_content = "경계할 거 없어요. 우린 동료니까요.",
  ui_story_5014_50140202_13_dialog_content = "로봇이 오기 전에 안전한 곳으로 도망가요.",
  ui_story_5014_50140202_14_dialog_content = "제가 천천히 설명할 테니까요...",
  ui_story_5014_50140202_15_dialog_content = "당신은...?",
  ui_story_5014_50140202_16_dialog_content = "그로누 연구원장 아래에서 일하고 있는 일루미나의 연구원, 시오반이에요.",
  ui_story_5014_50140202_17_dialog_content = "그 활을 보고 당신인 줄 알았어요. 일루미나제 무기잖아요.",
  ui_story_5014_50140202_18_dialog_content = "바이스 중위.",
  ui_story_5014_50140202_19_dialog_content = "다른 두 분은... 당신 동료인 아이테르와 「백야성의 공주」겠죠.",
  ui_story_5014_50140202_20_dialog_content = "<size=45>시, 시오반 선생님이셨어요?!</size>",
  ui_story_5014_50140202_21_dialog_content = "크흠, 맞아요. 그렇게 놀랄 건 없잖아요.",
  ui_story_5014_50140202_22_dialog_content = "죄, 죄송해요... 마스크를 쓰고 계셔서 못 알아봤어요.",
  ui_story_5014_50140202_23_dialog_content = "뭔가... 전에 뵀을 때랑 인상이 다른 것 같은데요...",
  ui_story_5014_50140202_24_dialog_content = "옷만 다를 뿐인걸요.",
  ui_story_5014_50140202_25_dialog_content = "여기 아직 몇 벌 더 있을 거예요. 찾아볼 테니까... 여기서 잠시만 기다려 주세요.",
  ui_story_5014_50140202_26_dialog_content = "왜 네 선생님이 여기 있는 건데?",
  ui_story_5014_50140202_27_dialog_content = "시오반 선생님은 고대 유적 전문 연구자야. 아마 조사를 위해 오신 게 아닐까 싶어.",
  ui_story_5014_50140202_28_dialog_content = "고대 유적 전문 연구자면... 역사를 가르치는 건가?",
  ui_story_5014_50140202_29_dialog_content = "음, 아니야. 시오반 선생님은 과학 연구과 선생님이야. 백야성의 역사 수업과는 달라.",
  ui_story_5014_50140202_30_dialog_content = "내 탐험 관련 지식도 전부 시오반 선생님에게 배운 거야.",
  ui_story_5014_50140202_31_dialog_content = "선생님한테 그림이나 스케치를 잘 못한다고 혼나기도 했고...",
  ui_story_5014_50140202_32_dialog_content = "그랬구나. 어쩐지 태도가 깍듯하다 했어. 좀 무서운 모양이지?",
  ui_story_5014_50140202_33_dialog_content = "난 선생님을 진심으로 존경하는 거야.\n선생님이 날 고대 과학 탐구의 길로 인도해 주셨으니까.",
  ui_story_5014_50140202_34_dialog_content = "고마운 마음뿐이지, 어떻게 무서워할 리가 있겠어.",
  ui_story_5014_50140202_35_dialog_content = "선생님한테 혼나고 나서 내 기계 제도 실력도 부쩍 늘어서...",
  ui_story_5014_50140202_36_dialog_content = "제가 혼낸 적이 있었나요?",
  ui_story_5014_50140202_37_dialog_content = "앗, 선생님... 오, 오셨어요? 별일 아니니까 기억 안 나시는 것도 당연해요.",
  ui_story_5014_50140202_38_dialog_content = "그리 긴장할 거 없어요. 편하게 대해 주세요.",
  ui_story_5014_50140202_39_dialog_content = "아, 네... 죄송해요. 선생님이 절 기억해주실 줄은 몰랐거든요...\n그걸 알고 나니까 갑자기 긴장이 돼서...",
  ui_story_5014_50140202_40_dialog_content = "당신이 쓴 콜로서스에 관한 보고서는 모두 읽어 봤어요.\n아주 인상 깊었어요.",
  ui_story_5014_50140202_41_dialog_content = "전 당신이 고대 과학 연구의 길을 걷게 되어 정말 기쁘게 생각하고 있어요.",
  ui_story_5014_50140202_42_dialog_content = "감사해요. 저도 고대의 과학에 대해 항상 관심이 많았거든요.",
  ui_story_5014_50140202_43_dialog_content = "감사할 필요는 없어요. 당신이 그만큼 우수하니까 하는 말이에요.",
  ui_story_5014_50140202_44_dialog_content = "그건 그렇고, 여긴 어떻게 들어온 거죠?",
  ui_story_5014_50140202_45_dialog_content = "우린 콜로서스에서 이상한 신호를 받았어.",
  ui_story_5014_50140202_46_dialog_content = "바이스가 좌표 범위를 분석했는데, 마침 우리랑 가까웠거든.",
  ui_story_5014_50140202_47_dialog_content = "그래서 수색하러 왔는데, 갑자기 지진이 일어났고...\n결국 균열 사이로 떨어져 어떤 동굴에 빠져버렸죠.",
  ui_story_5014_50140202_48_dialog_content = "그리고 여기까지 걸어왔던 거예요.",
  ui_story_5014_50140202_49_dialog_content = "역시 예상대로네요. 제 구조 요청 신호는 밖으로 전해지지 않았군요.",
  ui_story_5014_50140202_50_dialog_content = "그럼 우리가 받은 건...",
  ui_story_5014_50140202_51_dialog_content = "제가 보낸 게 아니에요.",
  ui_story_5014_50140202_52_dialog_content = "전 원래 북방의 산맥 지역에서 정기 순회 조사를 진행하고 있었어요.\n그때 저도 위치 정보 신호를 받았죠.",
  ui_story_5014_50140202_53_dialog_content = "그러다가 수색 도중에 우리도 우연히 이곳에 오게 됐어요.",
  ui_story_5014_50140202_54_dialog_content = "구호 신호를 보내려고 했지만 방법이 없었어요. 통신기가 망가졌거든요.",
  ui_story_5014_50140202_55_dialog_content = "「우리」? 그럼 동료들도 여기 있나요?",
  ui_story_5014_50140202_56_dialog_content = "아, 전 항상 혼자 행동해요. 그 사람들은 제 동료가 아니고...",
  ui_story_5014_50140202_57_dialog_content = "백야성에서 온... 친구들이에요.",
  ui_story_5014_50140202_58_dialog_content = "백야성?",
  ui_story_5014_50140202_59_dialog_content = "우린 여기서 벌써 20일 넘게 갇혀 있었어요.\n하지만 아직 밖으로 나가는 방법은 찾지 못했죠.",
  ui_story_5014_50140202_60_dialog_content = "20일이나?! 그럼 여긴 대체 어디야?",
  ui_story_5014_50140202_61_dialog_content = "이곳은 북방의 산속에 숨겨져 있던 고대의 도시예요.",
  ui_story_5014_50140202_62_dialog_content = "로봇만이 아니라 암귀도 있죠.",
  ui_story_5014_50140202_63_dialog_content = "암귀는 우리가 이 도시를 탐색하는 것을 방해하고 있어요.\n특히... 출구를 찾으려고 할 때는 더 심해요.",
  ui_story_5014_50140202_64_dialog_content = "우리도 이곳에 막 들어왔을 때 로봇의 공격을 받았어.",
  ui_story_5014_50140202_65_dialog_content = "그건 별일 아니에요.",
  ui_story_5014_50140202_66_dialog_content = "마침 옷을 몇 벌 찾았으니, 여러분도 갈아입으세요.",
  ui_story_5014_50140202_67_dialog_content = "옷을 갈아입으라고?",
  ui_story_5014_50140202_68_dialog_content = "네. 로봇의 검사를 통과하는 방법이에요.",
  ui_story_5014_50140202_69_dialog_content = "그런 거였군요... 알겠어요.",
  ui_story_5014_50140202_70_option_content = "난 모르겠는데... 설명 좀 해줄래?",
  ui_story_5014_50140202_71_dialog_content = "저 로봇들은 이곳의 규칙을 지키기 위해 존재해요.",
  ui_story_5014_50140202_72_dialog_content = "자난성에서 옷을 벗고 돌아다니면 치안관한테 붙잡히는 거랑 같은 거야.",
  ui_story_5014_50140202_73_dialog_content = "저 로봇들도 같은 일을 하고 있는 거야.",
  ui_story_5014_50140202_74_dialog_content = "그런 비유를 해도 돼?!",
  ui_story_5014_50140202_75_dialog_content = "만약 여러분의 「복장이 불량」하다면,\n저들에게 수상한 사람으로 판정되어 공격받을 거예요.",
  ui_story_5014_50140202_76_option_content = "「규정에 맞는 옷」을 입어야 한다는 거지?",
  ui_story_5014_50140202_77_dialog_content = "아까 로봇들은 공격하기 전에 「복장 규정 위반」이라는 말을 했어.",
  ui_story_5014_50140202_78_dialog_content = "그렇다면... 저들이 지정한 옷을 입어야 된다는 뜻이겠지.",
  ui_story_5014_50140202_79_dialog_content = "맞아요, 예리하시네요.",
  ui_story_5014_50140202_80_dialog_content = "제가 입고 있는 옷과 지금 드리는 게 바로 이 고대 도시의 복장이에요.",
  ui_story_5014_50140202_81_dialog_content = "이 도시의 공장에서 만들어진 옷이죠.",
  ui_story_5014_50140202_82_dialog_content = "근데 이건...",
  ui_story_5014_50140202_83_dialog_content = "뭐가 근데야. 그냥 잠깐 갈아입는 것뿐인데. 어려울 거 없잖아?",
  ui_story_5014_50140202_84_dialog_content = "어쩔 수 없는 일이니까, 아무도 비웃거나 하진 않을 거야.",
  ui_story_5014_50140202_85_dialog_content = "하지만 난...",
  ui_story_5014_50140202_86_dialog_content = "우린 시오반 선생님 말을 들어야 해. 이건 다 우리의 안전을 위해서라고.",
  ui_story_5014_50140202_87_dialog_content = "그래도 너희가...",
  ui_story_5014_50140202_88_dialog_content = "PlayerName, 넌 옆방에 가서 갈아입으면 돼.",
  ui_story_5014_50140202_89_dialog_content = "우물쭈물하지 말고 얼른 갈아입고 와.",
  ui_story_5014_50140202_90_dialog_content = "넌 전투 능력이 없으니까 로봇한테 공격당하면 큰일이라고.",
  ui_story_5014_50140202_91_dialog_content = "휴... 알았어, 알았다고. 갈아입으면 되잖아...",
  ui_story_5014_50140202_92_dialog_content = "다 갈아입었나요?",
  ui_story_5014_50140202_93_dialog_content = "네, 됐어요!",
  ui_story_5014_50140202_94_dialog_content = "이 옷은 하늘거리고 방어력도 부족하지만 움직이긴 편하네.",
  ui_story_5014_50140202_95_dialog_content = "이게 바로 고대의 복장이었구나.",
  ui_story_5014_50140202_96_dialog_content = "우리가 평소에 입던 옷과 조금 비슷한 것 같아.",
  ui_story_5014_50140202_97_dialog_content = "반대야. 우리 옷이 이거랑 비슷한 거지.",
  ui_story_5014_50140202_98_dialog_content = "PlayerName, 옷은 다 갈아입었나요?",
  ui_story_5014_50140202_99_dialog_content = "...진짜 이거밖에 없어? 이런 건 입기 싫다고...",
  ui_story_5014_50140202_100_dialog_content = "다른 옷은 없어요. 여기서 찾은 건 여성용뿐이라서요.",
  ui_story_5014_50140202_101_dialog_content = "얼른 나와. 진짜로 안 웃을게.",
  ui_story_5014_50140202_102_dialog_content = "알겠어...",
  ui_story_5014_50140202_103_dialog_content = "......",
  ui_story_5014_50140202_104_dialog_content = "......",
  ui_story_5014_50140202_105_dialog_content = "보고만 있지 말고 무슨 말이라도 좀 해!",
  ui_story_5014_50140202_106_dialog_content = "크흠, 너 다리 가늘구나... 꽤나 하얗기도 하고.",
  ui_story_5014_50140202_107_dialog_content = "이제 와서? 바다에서도 반바지 입었잖아!",
  ui_story_5014_50140202_108_dialog_content = "제대로 입는 법을 알고 있었다니 뜻밖이네.\n치마 같은 건 입어본 적 없는 줄 알았는데.",
  ui_story_5014_50140202_109_dialog_content = "당연히 입어본 적 없지!",
  ui_story_5014_50140202_110_dialog_content = "사이즈가 좀 작아. 가슴이 답답해서 숨을 못 쉬겠어...",
  ui_story_5014_50140202_111_dialog_content = "뒤쪽의 지퍼를 풀면 좀 편해질 거야.",
  ui_story_5014_50140202_112_dialog_content = "시오반 씨, 이 도시의 공장은 설마 여성복만 만드는 거야?",
  ui_story_5014_50140202_113_dialog_content = "아마 그렇진 않을 거예요. 단지 찾지 못했을 뿐이죠.",
  ui_story_5014_50140202_114_dialog_content = "휴... 알겠어.",
  ui_story_5014_50140202_115_dialog_content = "이제 로봇에게 공격당할 일도 없으니까 얼른 도시를 살펴보자.",
  ui_story_5014_50140202_116_dialog_content = "다른 옷을... 찾을 수 있었으면 좋겠네.",
  ui_story_5014_50140202_117_dialog_content = "크흠, 지금 우리한테 가장 중요한 건... 밖으로 나가는 방법을 찾는 거야.",
  ui_story_5014_50140202_118_dialog_content = "응, 바이스 말이 맞아.",
  ui_story_5014_50140202_119_dialog_content = "(너무해... 내 말은 시원하게 무시하다니... 이 옷... 반드시 갈아입고 말겠어!)",
  ui_story_5014_50140202_120_dialog_content = "그럼 출발할까?",
  ui_story_5014_50140202_121_dialog_content = "크르르...",
  ui_story_5014_50140202_122_dialog_content = "암귀 같으면서... 아닌 것 같기도 하고... 음, 아마 암귀겠지.",
  ui_story_5014_50140202_123_dialog_content = "왜 망설이는 거야?",
  ui_story_5014_50140202_124_dialog_content = "거리가 좀 멀기도 하고, 평소 느낀 암귀랑 좀 다른 것 같아.",
  ui_story_5014_50140202_125_dialog_content = "어떻게 다르죠?",
  ui_story_5014_50140202_126_dialog_content = "명확하게 말하긴 힘들지만, 아무튼 뭔가 이상한 느낌이야.",
  ui_story_5014_50140202_127_dialog_content = "이쪽으로 오고 있어.",
  ui_story_5014_50140202_128_dialog_content = "다른 곳으로 이동하죠. 불필요한 전투는 최대한 피해야 해요.",
  ui_story_5014_50140301_1_dialog_content = "삑, 삐익.",
  ui_story_5014_50140301_2_dialog_content = "또 로봇인가... 녀석들...",
  ui_story_5014_50140301_3_dialog_content = "걱정할 필요 없어요.",
  ui_story_5014_50140301_4_dialog_content = "보세요. 이젠 공격하지 않을 거예요.",
  ui_story_5014_50140301_5_dialog_content = "당신 말대로네. 아무래도 내가 너무 경계했던 모양이야...",
  ui_story_5014_50140301_6_dialog_content = "시오반 선생님, 여기가 정말 고대 도시인가요?",
  ui_story_5014_50140301_7_dialog_content = "맞아요.",
  ui_story_5014_50140301_8_dialog_content = "여긴 건물도 이렇게 많고, 게다가 엄청 높아요. 방도 잔뜩 있고...",
  ui_story_5014_50140301_9_dialog_content = "그렇다면 많은 고대인들이 옛날에 여기서 살았던 거겠죠?",
  ui_story_5014_50140301_10_dialog_content = "그럴 거예요.",
  ui_story_5014_50140301_11_dialog_content = "고대인들이 여기 살았다는 걸 어떻게 알아?",
  ui_story_5014_50140301_12_dialog_content = "스카이워커는 나한테 고대의 일은 아무도 모른다고 했거든.",
  ui_story_5014_50140301_13_dialog_content = "그건 말이지. 자난성도 고대의 유적을 개조해서 만들어진 도시거든.",
  ui_story_5014_50140301_14_dialog_content = "그리고 구체적으론 알 수 없어도 어느 정도 판단은 할 수 있으니까.",
  ui_story_5014_50140301_15_dialog_content = "자난성? 여긴 자난성이랑 전혀 다르게 생겼는데?",
  ui_story_5014_50140301_16_dialog_content = "맞아. 확실히 건축 양식은 달라. 나도 그건 의문이야.",
  ui_story_5014_50140301_17_dialog_content = "내 생각엔 아마 건축 연대가 다르거나, 기능이 다른 이유일 것 같아.",
  ui_story_5014_50140301_18_dialog_content = "「연대가 다르다」는 건 알겠는데, 「기능이 다르다」는 건 무슨 뜻이야?",
  ui_story_5014_50140301_19_dialog_content = "아, 그건... 나도 자세히는 모르겠어.",
  ui_story_5014_50140301_20_dialog_content = "자난성의 유적은 고대인들이 전쟁을 피하려고 만들었다는 것밖에...",
  ui_story_5014_50140301_21_dialog_content = "시오반 선생님은 어떻게 생각하세요?",
  ui_story_5014_50140301_22_dialog_content = "...불필요한 이야기가 많은 것 같군요.",
  ui_story_5014_50140301_23_dialog_content = "자난성이 고대인의 전쟁 피난처였다는 건 알고 있어.",
  ui_story_5014_50140301_24_dialog_content = "대륙 곳곳엔 고대의 유적이 많이 있고, 일루미나는 계속해서 발굴에 힘을 쏟고 있지.",
  ui_story_5014_50140301_25_dialog_content = "비록 일루미나처럼 고대의 과학 기술에 집착하진 않지만,\n백야성도 그 정도는 알고 있다고.",
  ui_story_5014_50140301_26_dialog_content = "저기, 시오반 선생님, 카렌은 우리와 생사를 함께해 온 소중한 동료예요.",
  ui_story_5014_50140301_27_dialog_content = "기밀 정보가 아닌 이상, 얘기해도 괜찮다고 생각해요.",
  ui_story_5014_50140301_28_dialog_content = "그렇군요... 뭐, 아까의 모습으로 봤을 때,\n확실히 카렌 양은 다른 거만한 귀족들과는 좀 다른 것 같더군요.",
  ui_story_5014_50140301_29_dialog_content = "당신들의 정보를 캘 생각은 없어.",
  ui_story_5014_50140301_30_dialog_content = "다만 우리가 함께 이곳에 갇힌 이상, 적당한 정보 공유는 필요하다고 생각해.",
  ui_story_5014_50140301_31_dialog_content = "탈출 방법이나 식량 문제라든지 말이야.",
  ui_story_5014_50140301_32_dialog_content = "이곳의 일부 시설은 지금도 정상적으로 가동되고 있어요.\n저 로봇이나 음식을 제조하는 공장도 포함해서요.",
  ui_story_5014_50140301_33_dialog_content = "선생님, 전 아직도 아까 그 문제가 궁금한데요.\n여기 건축 양식은 왜 자난성과 다른 거죠?",
  ui_story_5014_50140301_34_dialog_content = "전 이곳이 평범한 「민간 도시」이기 때문이라고 생각해요.",
  ui_story_5014_50140301_35_dialog_content = "「민간 도시」...?",
  ui_story_5014_50140301_36_dialog_content = "이곳에는 고대의 언어로 쓰인 책과 많은 생활 시설들이 남아 있어요.",
  ui_story_5014_50140301_37_dialog_content = "도시 곳곳을 순찰하고 있는 로봇도 조사해 보았습니다만,\n저들은 전투 능력이 약했어요.",
  ui_story_5014_50140301_38_dialog_content = "그건 즉, 이곳이 사람들의 「생활」을 목적으로 만들어졌다는 거겠죠.",
  ui_story_5014_50140301_39_dialog_content = "하지만 안타깝게도 이곳을 한참 조사했지만, 고대인의 흔적은 보이지 않았어요.",
  ui_story_5014_50140301_40_dialog_content = "암귀가 이곳의 고대인들을 멸망시킨 거겠지.",
  ui_story_5014_50140301_41_dialog_content = "꼭 그렇다고만은 할 수 없어요. 이상한 점이 있거든요...",
  ui_story_5014_50140301_42_dialog_content = "이곳의 암귀와 로봇은 서로 공격하지 않아요.",
  ui_story_5014_50140301_43_dialog_content = "대신 우리가 암귀의 공격을 당할 때만 로봇이 암귀를 공격하죠.",
  ui_story_5014_50140301_44_dialog_content = "「우리」... 참, 같이 있었다던 백야성 사람들은 어디 있지?",
  ui_story_5014_50140301_45_dialog_content = "그 사람들은... 계속 제 근처에 있어요.",
  ui_story_5014_50140301_46_dialog_content = "회장, 암귀가 따라붙었어.",
  ui_story_5014_50140301_47_dialog_content = "수는 대충 벌집에서 튀어나온 벌 정도로 많아.",
  ui_story_5014_50140301_48_dialog_content = "몇 번이나 말해야 알아듣겠어? 그런 이상한 묘사는 하지 말라고.\n그리고 회장이라고 부르지도 마.",
  ui_story_5014_50140301_49_dialog_content = "저기 제일 큰 암귀를 공격할 테니까 엄호해 줘.",
  ui_story_5014_50140301_50_dialog_content = "알았어, 회장.",
  ui_story_5014_50140301_51_dialog_content = "저쪽에서 오로리안이 암귀와 싸우는 게 느껴져!",
  ui_story_5014_50140301_52_dialog_content = "역시 무척 강한 감응 능력을 지니고 있군요.",
  ui_story_5014_50140301_53_dialog_content = "아마 백야성에서 온 두 친구가 암귀와 마주친 거겠죠.",
  ui_story_5014_50140301_54_dialog_content = "마주쳐버린 이상... 도와주러 갈 수밖에 없겠네요.",
  ui_story_5014_50140301_55_dialog_content = "내키지 않는 모양이지? 시오반 씨.",
  ui_story_5014_50140301_56_dialog_content = "어머, 이렇게 빨리 우릴 발견하고 여기까지 도망쳐 올 줄은 몰랐네요...",
  ui_story_5014_50140301_57_dialog_content = "플로리나 양.",
  ui_story_5014_50140302_1_dialog_content = "카렌 님, 이단심문조의 플로리나입니다.\n만나 뵙게 되어 영광이에요.",
  ui_story_5014_50140302_2_dialog_content = "그런데 무슨 일로 이곳에...",
  ui_story_5014_50140302_3_dialog_content = "지진에 휘말려서 떨어져 버렸어.",
  ui_story_5014_50140302_4_dialog_content = "너희는 어떻게 왔지? 다른 동료 한 명은?",
  ui_story_5014_50140302_5_dialog_content = "에리카는... 주변 상황을 확인하러 갔어요.",
  ui_story_5014_50140302_6_dialog_content = "독단적으로 행동하는 버릇이 있긴 하지만, 곧 돌아올 거예요.",
  ui_story_5014_50140302_7_dialog_content = "저흰 툰드라 지대에서... 좀 귀찮은 일을 당해서요.\n그래서 이 이상한 곳에 갇혀 버렸네요.",
  ui_story_5014_50140302_8_dialog_content = "절 미행하다가 같이 동굴에 빠져버린 거겠죠.",
  ui_story_5014_50140302_9_dialog_content = "카렌 님, 장소를 좀 옮겨서 말씀드리는 게 좋겠는데요...",
  ui_story_5014_50140302_10_dialog_content = "이 고대 도시는 보존 상태가 좋고, 상황은 이미 저희 예상을 뛰어넘었어요.",
  ui_story_5014_50140302_11_dialog_content = "좋아.",
  ui_story_5014_50140302_12_dialog_content = "둘이서만 얘기하러 가버렸네. 우리가 들으면 곤란한 얘기라도 있나?",
  ui_story_5014_50140302_13_dialog_content = "바이스, 이리 오세요. 할 얘기가 있어요.",
  ui_story_5014_50140302_14_dialog_content = "저 플로리나라는 여자는 백야성 교회 이단심문조 사람이면서...",
  ui_story_5014_50140302_15_dialog_content = "백야성 최고의 탐험가이기도 해요.",
  ui_story_5014_50140302_16_dialog_content = "전문적으로 고대 유적의 조사를 맡고 있죠.",
  ui_story_5014_50140302_17_dialog_content = "다만 우리와 다르게, 저들의 직무는 유적의 소멸이에요...",
  ui_story_5014_50140302_18_dialog_content = "...다들 귓속말이 무슨 소용이야? 나한텐 다 들린다고.",
  ui_story_5014_50140302_19_dialog_content = "......",
  ui_story_5014_50140302_20_dialog_content = "귀도 좋으신 모양이네요.",
  ui_story_5014_50140302_21_dialog_content = "저쪽의 두 사람 얘기도 들을 수 있어.",
  ui_story_5014_50140302_22_dialog_content = "아무튼 시오반 씨가 위험한 과학자고, 여기도 위험한 곳이라는 얘기네.",
  ui_story_5014_50140302_23_dialog_content = "지금 우린 모두 여기 갇힌 신세잖아.\n서로 할 말은 확실히 하는 게 좋지 않을까?",
  ui_story_5014_50140302_24_dialog_content = "이렇게 서로 경계해서야 여기서 나갈 방법을 찾을 수 있겠어?",
  ui_story_5014_50140302_25_dialog_content = "거기 두 사람은 어떻게 생각해?",
  ui_story_5014_50140302_26_dialog_content = "당신이 카렌 님과 자주 함께하고 있다는 그...",
  ui_story_5014_50140302_27_dialog_content = "...스커트, 정말 안 어울리네.",
  ui_story_5014_50140302_28_dialog_content = "어쩔 수 없이 입고 있는 거라고!",
  ui_story_5014_50140302_29_dialog_content = "쉬이익──!",
  ui_story_5014_50140302_30_dialog_content = "으앗, 이 뱀은 왜 갑자기...",
  ui_story_5014_50140302_31_dialog_content = "조용히 해. 우리 아르바가 놀랐잖아.",
  ui_story_5014_50140302_32_dialog_content = "왜 뱀을 데리고 다니는 거야?",
  ui_story_5014_50140302_33_dialog_content = "이야기가 샜잖아. 중요한 얘기 중이니까 진지하게 해.",
  ui_story_5014_50140302_34_dialog_content = "안 진지한 건 너잖아.",
  ui_story_5014_50140302_35_dialog_content = "당신 그 옷차림... 때문에 잠깐 주의력이 흔들렸을 뿐이야.",
  ui_story_5014_50140302_36_dialog_content = "어쨌든, 아무리 당신이 카렌 님과 함께 다녔다고 해도...",
  ui_story_5014_50140302_37_dialog_content = "우리 사정을 잘 모른다면 쓸데없는 참견은 하지 않는 게 좋아.",
  ui_story_5014_50140302_38_dialog_content = "결국 이단심문조 일 아냐? 난 헤이디랑도 아는 사이라고.",
  ui_story_5014_50140302_39_dialog_content = "...헤이디는 내 선배야.",
  ui_story_5014_50140302_40_dialog_content = "헤이디한테 내 말 못 들었어?",
  ui_story_5014_50140302_41_dialog_content = "확실히 얘기한 적이 있긴 한데... 당신, 선배랑 친해?",
  ui_story_5014_50140302_42_dialog_content = "친하다고는 할 수 없겠지만,\n만약 헤이디가 여기 있었다면 내 말을 들어줬을 거야.",
  ui_story_5014_50140302_43_dialog_content = "PlayerName 말이 맞아.",
  ui_story_5014_50140302_44_dialog_content = "플로리나, 방금 내가 말했듯이...",
  ui_story_5014_50140302_45_dialog_content = "출구를 찾는 건 우리의 공동 목적이고, 협력의 전제 조건은 정보 공유야.",
  ui_story_5014_50140302_46_dialog_content = "응, 나도 그렇게 생각해.",
  ui_story_5014_50140302_47_dialog_content = "알겠어요, 카렌 님... 그렇게 할게요.",
  ui_story_5014_50140302_48_dialog_content = "......",
  ui_story_5014_50140302_49_dialog_content = "왜 그런 눈으로 날 보는 건데?",
  ui_story_5014_50140302_50_dialog_content = "아무래도 이제 차분히 이야기를 나눌 수 있을 것 같네요.\n모두 바이스와 동료분들 덕분이에요.",
  ui_story_5014_50140302_51_dialog_content = "그러게, 카렌 님과 동료분들 덕분이지.",
  ui_story_5014_50140401_1_dialog_content = "우린 툰드라 지역 근처에서 조사 임무를 수행하고 있었어.",
  ui_story_5014_50140401_2_dialog_content = "그러다 의문의 신호를 받았는데, 그게 뭔지는 몰랐어.",
  ui_story_5014_50140401_3_dialog_content = "그래도 신호의 근원지가 가깝다는 건 알 수 있었어.",
  ui_story_5014_50140401_4_dialog_content = "그런데 근원지를 조사하고 있을 때 갑자기 지진이 일어났고,\n나랑 에리카는 지하에 떨어져 버린 거야.",
  ui_story_5014_50140401_5_dialog_content = "절 미행한 게 아니고요?",
  ui_story_5014_50140401_6_dialog_content = "우린 그저 일반적인 조사 임무를 수행하고 있었을 뿐이야.",
  ui_story_5014_50140401_7_dialog_content = "시오반 씨, 당신이 뭘 하고 있었는지 우린 전혀 몰라.",
  ui_story_5014_50140401_8_dialog_content = "그렇게 우릴 경계하는 걸 보면, 뭔가 남한테 말할 수 없는 연구라도 하던 거겠지?",
  ui_story_5014_50140401_9_dialog_content = "전혀 근거 없는 의심을 하는 것 같은데...",
  ui_story_5014_50140401_10_dialog_content = "경계하고 있는 건 당신들이 수상하고 위험하기 때문일 뿐이에요.",
  ui_story_5014_50140401_11_dialog_content = "그건 또 왜 그런 건데?",
  ui_story_5014_50140401_12_dialog_content = "우리 탐험대는 첫 번째 교육부터 배우는 말이 있어...",
  ui_story_5014_50140401_13_dialog_content = "「세상을 내려다보는 백야성은 자신들의 지배를 유지하기 위해\n모든 고대의 과학 기술을 말살하려 한다.」",
  ui_story_5014_50140401_14_dialog_content = "그래서 탐험대에게 가장 위험한 적은 고대 과학의 말살을\n임무로 삼는 백야성 이단심문조야.",
  ui_story_5014_50140401_15_dialog_content = "서로 그런 사연이 있었구나.",
  ui_story_5014_50140401_16_dialog_content = "이단심문조 사람은 전에도 몇 번 만난 적 있었어요.",
  ui_story_5014_50140401_17_dialog_content = "그리고 매번 똑같았어요... 싸우게 되거나, 아니면 싸울 뻔했죠.",
  ui_story_5014_50140401_18_dialog_content = "당신은 목적을 말할 생각이 없으니까, 우리도 더는 캐묻지 않았어.",
  ui_story_5014_50140401_19_dialog_content = "그 뒤로 당신이 뭘 하든 우린 방해한 적 없어.",
  ui_story_5014_50140401_20_dialog_content = "전 위험한 연구 같은 건 하지 않아요.",
  ui_story_5014_50140401_21_dialog_content = "수신된 신호는 일루미나의 코드로 암호화된 위치 정보였어요.\n전 그걸 따라서 여기까지 왔을 뿐이에요.",
  ui_story_5014_50140401_22_dialog_content = "어쩌면 <color=#FFB400>일루미나의 동포</color>가 보낸 구호 요청 신호일지도 모르니까요.",
  ui_story_5014_50140401_23_dialog_content = "저희도 마찬가지예요. 그 신호를 따라왔거든요.",
  ui_story_5014_50140401_24_dialog_content = "바이스, 통신기를 잠깐 좀 주시겠어요?\n신호를 찾을 수 있는지 시험해 보고 싶네요.",
  ui_story_5014_50140401_25_dialog_content = "알겠어요... 근데 여기에 온 뒤로 제 통신기도 반응이 없는걸요.",
  ui_story_5014_50140401_26_dialog_content = "다들 그 알 수 없는 신호의 근원지에 이끌려 여기 갇혔어...",
  ui_story_5014_50140401_27_dialog_content = "여긴 사람을 잡아먹는 마굴 그 자체야.\n이상한 신호로 사람들을 유인하고 있어.",
  ui_story_5014_50140401_28_dialog_content = "누, 누구야? 언제 내 뒤에?!",
  ui_story_5014_50140401_29_dialog_content = "진정해, 내 동료 에리카야.",
  ui_story_5014_50140401_30_dialog_content = "얘는 가끔 이상한 말을 하거든... 아주 「가끔」이지만.",
  ui_story_5014_50140401_31_dialog_content = "회장, 왜 그걸 강조하는데?",
  ui_story_5014_50140401_32_dialog_content = "네가 수상한 사람으로 오해받아서 기껏 풀어진 분위기를 망칠까 그러지.",
  ui_story_5014_50140401_33_dialog_content = "카렌 님, 혹시 무슨 신비한 힘을 사용하셨나요?",
  ui_story_5014_50140401_34_dialog_content = "회장이 일루미나의 과학자와 타협하다니...\n이건 카렌 님의 신비한 힘 때문인 게 분명해요.",
  ui_story_5014_50140401_35_dialog_content = "신비한 힘?",
  ui_story_5014_50140401_36_dialog_content = "카, 카렌 님... 얘 말은 신경 쓰지 마세요.",
  ui_story_5014_50140401_37_dialog_content = "에리카, 뭔가 새로운 단서는 찾았어?",
  ui_story_5014_50140401_38_dialog_content = "회장, 새로운... 예쁜 옷을 찾았어.",
  ui_story_5014_50140401_39_dialog_content = "남자 옷이야?",
  ui_story_5014_50140401_40_dialog_content = "아쉽지만 여자 옷이야... 스커트 차림의 아이테르.",
  ui_story_5014_50140401_41_dialog_content = "나라고 좋아서 입은 게 아니라고! 그렇게 부르지 마!",
  ui_story_5014_50140401_42_dialog_content = "그래, 그럼 함장이라고 부를게. 콜로서스를 조종하는 아이테르.",
  ui_story_5014_50140401_43_dialog_content = "그건 또 무슨 이상한 호칭이야?",
  ui_story_5014_50140401_44_dialog_content = "자, 자. 됐으니까 얘 말은 신경 쓰지 마.",
  ui_story_5014_50140401_45_dialog_content = "일단 각자 가지고 있는 단서를 공유하는 게 어때?",
  ui_story_5014_50140401_46_dialog_content = "그럼 저부터 간단히 말씀드릴게요.",
  ui_story_5014_50140401_47_dialog_content = "전 이곳을 안정적인 에너지원을 지닌 자동화된 도시로 추정하고 있어요.",
  ui_story_5014_50140401_48_dialog_content = "아마 인공지능이 관리하고 있는 거겠죠.",
  ui_story_5014_50140401_49_dialog_content = "인공지능? 설마 스카이워커 같은 건가...",
  ui_story_5014_50140401_50_dialog_content = "맞아요. 하지만 지금은 일부만 제 기능을 하고 있어요.",
  ui_story_5014_50140401_51_dialog_content = "이렇게 완전하게 보존된 고대 유적은 처음 봤어.",
  ui_story_5014_50140401_52_dialog_content = "헤이디 선배가 고서를 토대로 복원한 도시 구조도보다 더 완벽해.",
  ui_story_5014_50140401_53_dialog_content = "여긴 자동으로 사악한 음료를 토해내는 기계가 있어.",
  ui_story_5014_50140401_54_dialog_content = "그 음료는 신경을 자극해서, 한 입만 마셔도 트림만 하는 괴물이 돼버려.",
  ui_story_5014_50140401_55_dialog_content = "설마 그걸 마셨어?",
  ui_story_5014_50140401_56_dialog_content = "그리고 여기저기 새 로봇이 날아다니고 있어.\n녀석들은 음식으로 사람들을 특정한 장소로 유인해.",
  ui_story_5014_50140401_57_dialog_content = "가장 무서운 건... 그 음식들이... 전부 통조림이라는 거야.",
  ui_story_5014_50140401_58_dialog_content = "통조림이 뭐가 이상한데? 일루미나에도 있는데... 뭐가 무서워?",
  ui_story_5014_50140401_59_dialog_content = "무려 케이크 맛 통조림까지 있다고... 게다가 꽤 맛있어.",
  ui_story_5014_50140401_60_dialog_content = "내가 그 통조림들 먹으면 안 된다고 했잖아!",
  ui_story_5014_50140401_61_dialog_content = "그리고 곡물을 삼키고 통조림을 뱉어내는 사악한 공장도 있어.",
  ui_story_5014_50140401_62_dialog_content = "무슨 말인지 전혀 이해가 안 되는데?",
  ui_story_5014_50140401_63_dialog_content = "전 그나마 조금은 이해할 수 있겠네요. 그러니까 당신들은...",
  ui_story_5014_50140401_64_dialog_content = "자판기와 통조림 배송 드론, 그리고 통조림 공장을 발견했다는 거네요.",
  ui_story_5014_50140401_65_dialog_content = "그걸 어떻게 이해한 건지 전혀 이해가 안 되는데?",
  ui_story_5014_50140401_66_dialog_content = "이세계에 대해 쓰인 책에서 읽은 게 여긴 전부 있었어.",
  ui_story_5014_50140401_67_dialog_content = "정말... 무서우면서도 신기한 곳이야.",
  ui_story_5014_50140401_68_dialog_content = "설마 여기가 마음에 든 건 아니지?",
  ui_story_5014_50140401_69_dialog_content = "저 미친 로봇들을 벌써 잊어버렸어?",
  ui_story_5014_50140401_70_dialog_content = "맞아... 미쳤어...",
  ui_story_5014_50140401_71_dialog_content = "왜 갑자기 벌벌 떨어?",
  ui_story_5014_50140401_72_dialog_content = "그 로봇들은... 지치지도 않고, 계속해서 일, 일, 일만 해.",
  ui_story_5014_50140401_73_dialog_content = "게다가... 굉장히 용감해서, 싸움에서도 전혀 죽음을 두려워하지 않아...",
  ui_story_5014_50140401_74_dialog_content = "언제든지 꼬리에 꼬리를 물고... 계속해서 몰려와.",
  ui_story_5014_50140401_75_dialog_content = "꼭... 저 사악한 암귀처럼 말이야.",
  ui_story_5014_50140401_76_dialog_content = "자, 자, 무서워하지 말고 진정해...",
  ui_story_5014_50140401_77_dialog_content = "음식을 자동으로 생산하고, 심지어 자동으로 배달한다...\n이게 뭘 의미하는지 아시겠어요?",
  ui_story_5014_50140401_78_dialog_content = "일루미나의 모든 도시와 모든 사람이 더는 음식 걱정을 할 필요가 없게 될 거에요.",
  ui_story_5014_50140401_79_dialog_content = "특히 전선을 지키는 사람들에겐 더 큰 의미가 있겠죠.",
  ui_story_5014_50140401_80_dialog_content = "맞아요. 그렇게 절감한 인력과 물자는 농작물의 생산량 향상에 투입할 수 있어요.",
  ui_story_5014_50140401_81_dialog_content = "그렇게 된다면... 온 대륙의 오로리안까지 보장할 수 있을지도...",
  ui_story_5014_50140401_82_dialog_content = "잠깐만, 저건 지금 인공지능으로 제어되는 로봇이라고.\n그게 뭘 의미하는지 알아?",
  ui_story_5014_50140401_83_dialog_content = "인력과 물자를 절감할 수 있다는 거지.",
  ui_story_5014_50140401_84_dialog_content = "저 로봇들이 인간의 통제에서 벗어날 수도 있다는 거야.",
  ui_story_5014_50140401_85_dialog_content = "너희 일루미나 사람들은 항상 자기가 기계를 제어해서,\n그걸로 암귀를 물리칠 수 있다고 생각하지?",
  ui_story_5014_50140401_86_dialog_content = "하지만 만약 로봇이 오로리안을 공격한다면?",
  ui_story_5014_50140401_87_dialog_content = "로봇이 암귀의 조종을 받게 된다면?",
  ui_story_5014_50140401_88_dialog_content = "무슨 소리야? 암귀가 기계를 조종할 수 있을 리가 없잖아.",
  ui_story_5014_50140401_89_dialog_content = "우린 지혜를 가진 암귀도 봤고, 암귀로 변한 오로리안도 봤어.",
  ui_story_5014_50140401_90_dialog_content = "그럼 우리 일루미나는 백야성에만 의지해서 암귀와 싸우라는 거야?",
  ui_story_5014_50140401_91_dialog_content = "백야성이 식량을 나눠주기만 기다리라고?",
  ui_story_5014_50140401_92_dialog_content = "자, 의미 없는 싸움은 그만둬요.",
  ui_story_5014_50140401_93_dialog_content = "지금 더 큰 문제를 발견했으니까요...",
  ui_story_5014_50140401_94_dialog_content = "바이스, 당신 통신기에 표시된 날짜는 정확한 건가요?",
  ui_story_5014_50140401_95_dialog_content = "맞아요. 왜 그러시죠?",
  ui_story_5014_50140401_96_dialog_content = "이 날짜는 제가 이곳에 들어온 날로부터... 50일 이상 지났어요.",
  ui_story_5014_50140401_97_dialog_content = "50일? 그럴 리 없어. 분명히 날짜를 제대로 셌는데...",
  ui_story_5014_50140401_98_dialog_content = "맞아요. 저도 세고 있었어요.",
  ui_story_5014_50140401_99_dialog_content = "비록 장비는 사용할 수 없게 됐지만,\n제가 정신을 차린 뒤로 27번의 밤낮이 지난 건 확실히 기억하고 있어요.",
  ui_story_5014_50140401_100_dialog_content = "장비를 쓸 수 없다고요? 설마 고대인의 차단 기술일까요?",
  ui_story_5014_50140401_101_dialog_content = "특수한 에너지 장벽으로 장비에 문제를 일으키고,\n우리의 시간 감각에도 영향을 준다는 건가요...?",
  ui_story_5014_50140401_102_dialog_content = "유적의 장벽이라면 몇 번이나 경험한 적 있지만, 그렇지는 않았어요.",
  ui_story_5014_50140401_103_dialog_content = "말도 안 돼. 시공간을 왜곡한다니... 그건 신의 힘이잖아...",
  ui_story_5014_50140401_104_dialog_content = "하지만 아공간을 만들어내는 암귀도 있어.\n놈들의 다크매터는 기기나 사람의 감각에도 영향을 줘.",
  ui_story_5014_50140401_105_dialog_content = "역시 이곳과 암귀는... 모두 사악한 힘을 가지고 있어.",
  ui_story_5014_50140401_106_dialog_content = "그 「인공지능」이라는 것도 분명히 무척 사악할 거야...",
  ui_story_5014_50140401_107_dialog_content = "녀석은 어둠 속에서 이 세상의 모든 것을 훔쳐보면서...",
  ui_story_5014_50140401_108_dialog_content = "우리의 정신을 갉아먹고... 우릴 미치게 만들 계획이겠지...",
  ui_story_5014_50140401_109_dialog_content = "에리카, 왜 또 시작이야?",
  ui_story_5014_50140401_110_dialog_content = "회장, 저길 봐... 녀석의 졸개들이 왔어...",
  ui_story_5014_50140401_111_dialog_content = "삑── 삐익──",
  ui_story_5014_50140401_112_dialog_content = "<color=#e8d9bb>구역 탐지 시작...</color>",
  ui_story_5014_50140401_113_dialog_content = "<color=#e8d9bb>외부 침입자가 공공 휴식 구역 파괴 중.</color>",
  ui_story_5014_50140401_114_dialog_content = "<color=#e8d9bb>식량 공급 구역 파괴 중</color>",
  ui_story_5014_50140401_115_dialog_content = "설마 또 새로운 외부인이 침입한 건가?",
  ui_story_5014_50140401_116_dialog_content = "언니, 또 지진이 나서 그런 것 같아.",
  ui_story_5014_50140401_117_dialog_content = "집사, 저 통로를 어떻게든 좀 수리해 줄 수 없어?",
  ui_story_5014_50140401_118_dialog_content = "<color=#e8d9bb>현재, 네 번째... 수리를, 진행하고 있습니다.</color>",
  ui_story_5014_50140401_119_dialog_content = "다음번 지진에 또 망가질 거야.",
  ui_story_5014_50140401_120_dialog_content = "<color=#e8d9bb>걱정하지... 마십시오. 일부 시스템 모듈을... 업그레이드하는, 중입니다.</color>",
  ui_story_5014_50140401_121_dialog_content = "<color=#e8d9bb>곧... 해결될, 것입니다.</color>",
  ui_story_5014_50140401_122_dialog_content = "그럼 이제 우린 어떡해...? 계속 여기 숨어 있어야 돼?",
  ui_story_5014_50140401_123_dialog_content = "저 외부인들은 강해. 암귀를 쓰러트릴 수 있어.",
  ui_story_5014_50140401_124_dialog_content = "<color=#e8d9bb>걱정하지... 마십시오. 생산 모듈 개조에, 성공했습니다.</color>",
  ui_story_5014_50140401_125_dialog_content = "<color=#e8d9bb>현재... 업그레이드, 중입니다.</color>",
  ui_story_5014_50140401_126_dialog_content = "<color=#e8d9bb>두 분께서는... 지하, 요새에... 대기하며, 외출을 삼가시길, 바랍니다.</color>",
  ui_story_5014_50140401_127_dialog_content = "<color=#e8d9bb>곧... 해결될, 것입니다.</color>",
  ui_story_5014_50140401_128_dialog_content = "하지만 네 로봇들은 저 외부인들의 상대가 못 돼.",
  ui_story_5014_50140401_129_dialog_content = "아니면 내가 직접 나서는 게...",
  ui_story_5014_50140401_130_dialog_content = "성급하게 굴지 마, 그레텔.",
  ui_story_5014_50140401_131_dialog_content = "집사, 감시 시스템 복구는 끝났어?",
  ui_story_5014_50140401_132_dialog_content = "<color=#e8d9bb>복구에... 실패했습니다.</color>",
  ui_story_5014_50140401_133_dialog_content = "「수호천사 3호」를 보내자.",
  ui_story_5014_50140401_134_dialog_content = "그걸로 저 외부인들을 감시할 수 있어.",
  ui_story_5014_50140401_135_dialog_content = "안 돼. 그랬다간 외부인들이 부숴버릴 거야!",
  ui_story_5014_50140401_136_dialog_content = "그건 아빠가... 아빠가 우리한테 주신 소중한 선물이잖아...",
  ui_story_5014_50140401_137_dialog_content = "하지만 이대로 둘 순 없어. 어떻게든 해야만 해.",
  ui_story_5014_50140401_138_dialog_content = "아주 적은 정보만이라도 얻을 수 있다면 그걸로 충분해.",
  ui_story_5014_50140401_139_dialog_content = "「수호천사 3호」한테 조심해서 움직이라고 할게.\n저 사람들한테 들키지만 않으면 돼.",
  ui_story_5014_50140401_140_dialog_content = "휴, 알았어.",
  ui_story_5014_50140401_141_dialog_content = "「수호천사 3호」, 이리 와.",
  ui_story_5014_50140401_142_dialog_content = "삐뽀──!",
  ui_story_5014_50140401_143_dialog_content = "그 녀석들을 감시해서, 뭘 하려는 건지 확인해 봐.",
  ui_story_5014_50140401_144_dialog_content = "녀석들한테 들키지 않게 거리를 잘 유지하고.",
  ui_story_5014_50140501_1_dialog_content = "<color=#e8d9bb>쿠르르릉──!</color>",
  ui_story_5014_50140501_2_dialog_content = "또 지진이에요! 여러분, 어서 숨으세요!",
  ui_story_5014_50140501_3_dialog_content = "<color=#e8d9bb>콰르르...</color>",
  ui_story_5014_50140501_4_dialog_content = "건물이 무너지진 않아서 다행이네요. 아니었으면 큰일 날 뻔했어요.",
  ui_story_5014_50140501_5_dialog_content = "<color=#e8d9bb>삑, 삐빅.</color>",
  ui_story_5014_50140501_6_dialog_content = "시오반 선생님, 통신기가 갑자기 다시 작동하고 있어요!",
  ui_story_5014_50140501_7_dialog_content = "네. 제 것도 작동하네요.",
  ui_story_5014_50140501_8_dialog_content = "저번 지진 때도...",
  ui_story_5014_50140501_9_dialog_content = "같은 현상이었죠.",
  ui_story_5014_50140501_10_dialog_content = "신호를 수신할 수 있는 건, 근원지에 충분히 가까워졌거나...",
  ui_story_5014_50140501_11_dialog_content = "아니면 신호를 방해하는 요소가 사라졌다는 거겠죠.",
  ui_story_5014_50140501_12_dialog_content = "가요. 신호가 사라지기 전에 근원지를 찾아보기로 해요.",
  ui_story_5014_50140501_13_dialog_content = "어디로 갈 건데?",
  ui_story_5014_50140501_14_dialog_content = "대체 어디서 신호를 보내고 있는 건지 확인할 거야.",
  ui_story_5014_50140501_15_dialog_content = "아직도 포기 안 한 거야?",
  ui_story_5014_50140501_16_dialog_content = "벌써 세 번째 지진이야. 이러다간 우리 모두...",
  ui_story_5014_50140501_17_dialog_content = "맞아, 여긴 너무 위험해. 탈출할 방법부터 찾는 게 좋겠어.",
  ui_story_5014_50140501_18_dialog_content = "다른 일은 그다음에 해도 늦지 않아.",
  ui_story_5014_50140501_19_dialog_content = "이건 일루미나의 신호야. 그러니까 일루미나 탐험대가 여기 왔었다는 뜻이야.",
  ui_story_5014_50140501_20_dialog_content = "네, 이 신호는 우리의 동료가 남긴 거예요.",
  ui_story_5014_50140501_21_dialog_content = "분명히 이곳에 어떤 정보를 남겼을 거라고 생각해요.",
  ui_story_5014_50140501_22_dialog_content = "시오반 선생님, 혹시 이 탐험대에 대해 알고 계신가요?",
  ui_story_5014_50140501_23_dialog_content = "지금까지 이 장소에 대한 자료는 본 적이 없어요. 기밀 자료인가요?",
  ui_story_5014_50140501_24_dialog_content = "기밀 자료에도 관련 기록은 없었어요.",
  ui_story_5014_50140501_25_dialog_content = "이곳에 왔던 사람은 아마 일루미나로 돌아오지 않았던 모양이에요...",
  ui_story_5014_50140501_26_dialog_content = "왜 이곳에 왔다는 자료를 안 남긴 건데?",
  ui_story_5014_50140501_27_dialog_content = "적어도 관련 기록 정도는 있어야 하지 않아?",
  ui_story_5014_50140501_28_dialog_content = "어떤 부대가 어디로 갔는지 같은 기록 말이야.",
  ui_story_5014_50140501_29_dialog_content = "고대 유적 탐색은 항상 갑작스러운 위험에 처할 가능성이 있어요.",
  ui_story_5014_50140501_30_dialog_content = "실종과 희생은 탐험대에게 있어선 일상다반사 같은 일이죠.",
  ui_story_5014_50140501_31_dialog_content = "하지만 이곳에 신호를 남겼다는 건...",
  ui_story_5014_50140501_32_dialog_content = "동료가 생명의 위험을 무릅쓰면서 남긴 정보라는 뜻이에요.\n그러니까 반드시 찾아야만 해요.",
  ui_story_5014_50140501_33_dialog_content = "...플로리나, 우리도 도와주자.",
  ui_story_5014_50140501_34_dialog_content = "네, 이단심문조의 도구를 사용하면...",
  ui_story_5014_50140501_35_dialog_content = "그 신호 발생지의 구체적인 위치를 찾는 데 도움이 될 거예요.",
  ui_story_5014_50140501_36_dialog_content = "에리카, 가서 준비해 줘.",
  ui_story_5014_50140501_37_dialog_content = "알았어, 회장.",
  ui_story_5014_50140501_38_dialog_content = "빛의 신의 지시를 들을 준비는... 이미 끝났어.",
  ui_story_5014_50140501_39_dialog_content = "이단심문조는 어떤 도구를 사용할까? 궁금한걸...",
  ui_story_5014_50140501_40_dialog_content = "가서 봐도 돼?",
  ui_story_5014_50140501_41_dialog_content = "그건 아마 곤란할 것 같네.",
  ui_story_5014_50140501_42_dialog_content = "기밀 정보인 거야?",
  ui_story_5014_50140501_43_dialog_content = "그렇다고 할 수 있겠지.",
  ui_story_5014_50140501_44_dialog_content = "휴, 알았어.",
  ui_story_5014_50140501_45_dialog_content = "그 기묘한 신호... 아직 안 사라졌어. 찾았어. 따라와.",
  ui_story_5014_50140501_46_dialog_content = "여기야?",
  ui_story_5014_50140501_47_dialog_content = "맞아, 바로 여기 아래야.",
  ui_story_5014_50140501_48_dialog_content = "이 틈으로 내려가야 되나?",
  ui_story_5014_50140501_49_dialog_content = "이 균열은 지진으로 생긴 거야. 너무 위험해.",
  ui_story_5014_50140501_50_dialog_content = "위험하긴 해도, 시도해 볼 가치는 있어요.",
  ui_story_5014_50140501_51_dialog_content = "전 이 지하에 분명히 뭔가 더 있다고 생각하고 있었어요.\n하지만 지금까지 계속 입구를 못 찾고 있었죠.",
  ui_story_5014_50140501_52_dialog_content = "우린 운이 좋네요. 아래를 보세요.",
  ui_story_5014_50140501_53_dialog_content = "아래 통로가 있는 것 같아요...",
  ui_story_5014_50140501_54_dialog_content = "전 먼저 내려갈게요. 여러분은 조금 더 생각해 봐도 좋아요.",
  ui_story_5014_50140501_55_dialog_content = "저도 같이 가요, 시오반 선생님.",
  ui_story_5014_50140501_56_dialog_content = "잠깐만, 바이스!",
  ui_story_5014_50140501_57_dialog_content = "PlayerName, 난 시오반 선생님이랑 같이 가 보고 싶어.",
  ui_story_5014_50140501_58_dialog_content = "아니, 가지 말라는 게 아니라...",
  ui_story_5014_50140501_59_dialog_content = "캬아악──!",
  ui_story_5014_50140501_60_dialog_content = "암귀가 느껴져서 그래!",
  ui_story_5014_50140502_1_dialog_content = "「바이스, 9시 방향에서 암귀 한 마리가 우릴 노리고 있어!」",
  ui_story_5014_50140502_2_dialog_content = "「알겠어! 속사 감지!」",
  ui_story_5014_50140502_3_dialog_content = "언니, 녀석들이 또 암귀랑 싸우기 시작했어.",
  ui_story_5014_50140502_4_dialog_content = "아무래도 외부인들이 또 이길 것 같네.",
  ui_story_5014_50140502_5_dialog_content = "녀석들이 쳐들어올까?",
  ui_story_5014_50140502_6_dialog_content = "아까 보니까 이쪽으로 오려고 하던 것 같아...",
  ui_story_5014_50140502_7_dialog_content = "무서워하지 않아도 돼. 내가 지켜줄게.",
  ui_story_5014_50140502_8_dialog_content = "녀석들이 들이닥치면 넌 숨어. 내가 상대할 테니까.",
  ui_story_5014_50140502_9_dialog_content = "집사가 새 로봇을 보낸 뒤에 나오면 돼.",
  ui_story_5014_50140502_10_dialog_content = "집사... 새 로봇은 아직이야?",
  ui_story_5014_50140502_11_dialog_content = "<color=#e8d9bb>현재 최종, 테스트를... 진행, 중입니다.</color>",
  ui_story_5014_50140502_12_dialog_content = "이런 상황에서 무슨 테스트야? 얼른 보내 줘!",
  ui_story_5014_50140502_13_dialog_content = "<color=#e8d9bb>전투 로봇의, 최종 테스트를... 취소하시겠습니까?</color>",
  ui_story_5014_50140502_14_dialog_content = "아니, 취소하면 안 돼. 이건 우리 안전이 걸린 문제야.",
  ui_story_5014_50140502_15_dialog_content = "그레텔, 내가 계속 말했잖아... 집사한테 그런 말 하면 안 돼.",
  ui_story_5014_50140502_16_dialog_content = "미안, 언니... 조금 초조해서 그랬어.",
  ui_story_5014_50140502_17_dialog_content = "「기묘한 신호가 점점 강해지고 있어요...」",
  ui_story_5014_50140502_18_dialog_content = "「발생지는 이 앞이에요.」",
  ui_story_5014_50140502_19_dialog_content = "이런, 저들이 오고 있어.",
  ui_story_5014_50140502_20_dialog_content = "그레텔, 어서 숨어.",
  ui_story_5014_50140502_21_dialog_content = "전방에 오로리안이 있어! 희미하긴 해도 느껴져!",
  ui_story_5014_50140502_22_dialog_content = "잘했어요, PlayerName. 이대로 계속 감응해 주세요.",
  ui_story_5014_50140502_23_dialog_content = "알겠어, 시오반 씨!",
  ui_story_5014_50140502_24_dialog_content = "그 오로리안은 지금 저 앞에 숨...",
  ui_story_5014_50140502_25_dialog_content = "......",
  ui_story_5014_50140502_26_dialog_content = "모두 조심해! 사악한 로봇을 조종하는 자가 나타났어!",
  ui_story_5014_50140502_27_dialog_content = "경고, 경고, 이 앞으로는 갈 수 없습니다.",
  ui_story_5014_50140502_28_dialog_content = "넌 누구지? 어떻게 이렇게 많은 로봇을 소환할 수 있지?",
  ui_story_5014_50140502_29_dialog_content = "설마 고대인의 후예인가?",
  ui_story_5014_50140502_30_dialog_content = "소환술로 로봇을 소환할 수 있는 거야?",
  ui_story_5014_50140502_31_dialog_content = "「조종하는 자」, 「고대인」, 「소환술」... 그게 다 무슨 소리야?",
  ui_story_5014_50140502_32_dialog_content = "이세계의 주민이... 우리 말을 할 수 있어?",
  ui_story_5014_50140502_33_dialog_content = "잠깐만, 우리 말을 할 수 있다면 고대인 같은 게 아니잖아.",
  ui_story_5014_50140502_34_dialog_content = "저기, 넌...",
  ui_story_5014_50140502_35_dialog_content = "멈춰. 다가오지 마.",
  ui_story_5014_50140502_36_dialog_content = "경비 로봇, 전투 준비.",
  ui_story_5014_50140502_37_dialog_content = "알겠습니다.",
  ui_story_5014_50140502_38_dialog_content = "루미나틱스를 다루는 것 같아... 분명히 어디서 본 느낌인데...",
  ui_story_5014_50140502_39_dialog_content = "정확히 말하자면 우리 일루미나의 과학 마법인 「기계 조종」 능력이네요.",
  ui_story_5014_50140502_40_dialog_content = "일루미나?",
  ui_story_5014_50140502_41_dialog_content = "맞아요. 우선 진정하세요.\n저흰 나쁜 뜻은 없어요. 그저...",
  ui_story_5014_50140502_42_dialog_content = "저희 동료를 찾으러 왔을 뿐이에요.",
  ui_story_5014_50140601_1_dialog_content = "신호 발생지는 저 뒤에 있는 건물 안이야.",
  ui_story_5014_50140601_2_dialog_content = "당신들...",
  ui_story_5014_50140601_3_dialog_content = "안녕, 난 바이스라고 해. 일루미나에서 온 오로리안이야.",
  ui_story_5014_50140601_4_dialog_content = "우린 구조 요청 신호를 받고 이곳에 왔어.",
  ui_story_5014_50140601_5_dialog_content = "저기, 혹시...",
  ui_story_5014_50140601_6_dialog_content = "일루미나 연방... 얘기야?",
  ui_story_5014_50140601_7_dialog_content = "네, 맞아요. 저흰 일루미나 연방 사람이에요!",
  ui_story_5014_50140601_8_dialog_content = "당신 이름이 뭐죠? 당신도 일루미나 연방 출신인가요?",
  ui_story_5014_50140601_9_dialog_content = "난... 발렌시아야. 연방 사람은 아냐...",
  ui_story_5014_50140601_10_dialog_content = "발렌시아 양, 저희가 안에 잠깐 들어갈 수 있을까요?",
  ui_story_5014_50140601_11_dialog_content = "이건 일루미나의 통신기예요. 그 안에 분명히 이런 게 있을 거예요.",
  ui_story_5014_50140601_12_dialog_content = "(아빠의 유품이랑 똑같잖아?!)",
  ui_story_5014_50140601_13_dialog_content = "일루미나에 대해서는 알고 있어. 하지만 아빠가...",
  ui_story_5014_50140601_14_dialog_content = "언니, 상대하지 마!",
  ui_story_5014_50140601_15_dialog_content = "집사가 그랬어. 이 외부인들은 위험하다고!",
  ui_story_5014_50140601_16_dialog_content = "그레텔, 왜 밖에 나왔어?!",
  ui_story_5014_50140601_17_dialog_content = "저 사람들 말하는 거 들었어... 분명히 언니를 속이려고 하는 거야.",
  ui_story_5014_50140601_18_dialog_content = "하지만 아빠가 그랬잖아. 일루미나 사람을 만나면...",
  ui_story_5014_50140601_19_dialog_content = "녀석들은 침입자고, 모르는 사람들이야. 그리고 여길 계속 파괴하고 있어!",
  ui_story_5014_50140601_20_dialog_content = "언니, 설마 잊은 거야? 저 녀석들이 로봇을 잔뜩 부숴버렸다고.",
  ui_story_5014_50140601_21_dialog_content = "잠깐만요. 저흰 로봇을 부수지 않았어요...",
  ui_story_5014_50140601_22_dialog_content = "시끄러워!",
  ui_story_5014_50140601_23_dialog_content = "아빠가 그랬어. 위험한 사람들이랑은 얘기하지 말라고!",
  ui_story_5014_50140601_24_dialog_content = "너희가 이 로봇들을 조종하는 거야?",
  ui_story_5014_50140601_25_dialog_content = "우린 이 로봇들의 위협을 받아서 어쩔 수 없이 파괴했을 뿐이야.",
  ui_story_5014_50140601_26_dialog_content = "두 사람은 계속 여기서 살았나요? 부모님은 어디 계시죠?",
  ui_story_5014_50140601_27_dialog_content = "조용히 하라고! 여긴 우리 집이야! 어서 나가!",
  ui_story_5014_50140601_28_dialog_content = "우리도 나가고 싶은데 못 나가는 거라고...",
  ui_story_5014_50140601_29_dialog_content = "시오반 씨, 그래서 저 사람들은 「일루미나의 동료」가 맞아?",
  ui_story_5014_50140601_30_dialog_content = "지금 확인할 생각이니까 방해하지 마세요.",
  ui_story_5014_50140601_31_dialog_content = "당신들 아버지 이름이 어떻게 되죠?",
  ui_story_5014_50140601_32_dialog_content = "이 이름들 중에 있나요? 글리, 유스벤, 숀, 시모스, 이...",
  ui_story_5014_50140601_33_dialog_content = "잠깐... 시모스, 그게 우리 아빠 이름이야.",
  ui_story_5014_50140601_34_dialog_content = "시모스? 정말 시모스 씨의 딸이라고요?!",
  ui_story_5014_50140601_35_dialog_content = "시모스 씨는 10여 년 전에 실종됐던 제 선배예요...",
  ui_story_5014_50140601_36_dialog_content = "지금까지 돌아가신 줄로만 알았어요.",
  ui_story_5014_50140601_37_dialog_content = "설마... 아직 살아계셨을 줄이야... 게다가 아이까지...",
  ui_story_5014_50140601_38_dialog_content = "어서 시모스 씨한테 안내해 주세요!",
  ui_story_5014_50140601_39_dialog_content = "드릴 말씀이 많이 있으니까요.",
  ui_story_5014_50140601_40_dialog_content = "그건 안 돼... 아빠는 이제 안 계시니까.",
  ui_story_5014_50140601_41_dialog_content = "언니! 그 사람한테 말하지 마!",
  ui_story_5014_50140601_42_dialog_content = "집사가 그랬잖아. 외부인과 어울리지 말라고!",
  ui_story_5014_50140601_43_dialog_content = "녀석들은 전부 물건을 훔치러 왔을 뿐이야!",
  ui_story_5014_50140601_44_dialog_content = "물건을...",
  ui_story_5014_50140601_45_dialog_content = "미안한데 잠깐 좀 끼어들어도 괜찮을까?",
  ui_story_5014_50140601_46_dialog_content = "암귀가 이쪽으로 오는 걸 느꼈어. 우리 일단...",
  ui_story_5014_50140601_47_dialog_content = "언니, 봐! 녀석들이 우리 옷도 훔쳤어!",
  ui_story_5014_50140601_48_dialog_content = "저 녀석이 언니 옷을 억지로 입어서 옷이 터져버렸다고!",
  ui_story_5014_50140601_49_dialog_content = "아, 아니야, 이건 오해야! 난...",
  ui_story_5014_50140601_50_dialog_content = "캬아악──!",
  ui_story_5014_50140601_51_dialog_content = "다들 조심해! 암귀가 온다!",
  ui_story_5014_50140601_52_dialog_content = "어쩔 수 없네요. 이따가 다시 얘기해요...\n여러분, 우선 싸울 준비를 하죠.",
  ui_story_5014_50140601_53_dialog_content = "발렌시아 양, 당신들은 어서 안전한 곳으로 가서 숨으세요.",
  ui_story_5014_50140601_54_dialog_content = "암귀들은 저희한테 맡겨주세요.",
  ui_story_5014_50140601_55_dialog_content = "아...알았어.",
  ui_story_5014_50140602_1_dialog_content = "그레텔, 저 사람들은... 믿어도 될 것 같아.",
  ui_story_5014_50140602_2_dialog_content = "어쩌면 아빠가 말했던 「일루미나의 동료」일지도 몰라.",
  ui_story_5014_50140602_3_dialog_content = "적어도 얘기는 해봐야 한다고 생각해.",
  ui_story_5014_50140602_4_dialog_content = "「바깥의 사람들은 서로 자원을 빼았는다」,\n「자기 이익을 위해 수단을 가리지 않는다」...",
  ui_story_5014_50140602_5_dialog_content = "그리고 「이익을 위해서라면 거짓말도 한다」고...",
  ui_story_5014_50140602_6_dialog_content = "집사가 알려줬잖아, 우린 집사가 하는 말을 믿어야 해.",
  ui_story_5014_50140602_7_dialog_content = "저 사람들은 암귀는 아니지만, 좋은 사람도 아니야.",
  ui_story_5014_50140602_8_dialog_content = "하지만... 지금도 암귀와 싸우고 있고, 게다가 우리한테 안전한 곳으로 피하라고 했어.",
  ui_story_5014_50140602_9_dialog_content = "우릴 지켜주고 있는 거잖아.",
  ui_story_5014_50140602_10_dialog_content = "저런 사람들은 원래부터 암귀랑 싸우는 게 좋을 뿐이야.\n「지켜주는」 거랑은 상관없어!",
  ui_story_5014_50140602_11_dialog_content = "그래도...",
  ui_story_5014_50140602_12_dialog_content = "끼에엑!",
  ui_story_5014_50140602_13_dialog_content = "다 해치웠네.",
  ui_story_5014_50140602_14_dialog_content = "그럼... 이제 저 자매랑 좀 더 얘기를 해봐야겠죠?",
  ui_story_5014_50140602_15_dialog_content = "아까 그 분위기로 봐서는 어렵겠던데.",
  ui_story_5014_50140602_16_dialog_content = "미안, 고의는 아니었는데... 내가 대화를 방해한 것 같네.",
  ui_story_5014_50140602_17_dialog_content = "아니요, 당신 탓이 아니에요.",
  ui_story_5014_50140602_18_dialog_content = "그럼 어떻게 할지 좀 생각해 볼게요...",
  ui_story_5014_50140602_19_dialog_content = "선생님, 아까 말씀하셨던 시모스라는 사람... 설마 그 전설의...",
  ui_story_5014_50140602_20_dialog_content = "맞아요, 지난 30년간 일루미나에서 가장 뛰어난 유적 전문가였던 그분 말이에요.",
  ui_story_5014_50140602_21_dialog_content = "혼자서 과학 조사단 한 팀의 능력에 필적한다는 그 시모스? 세상에...",
  ui_story_5014_50140602_22_dialog_content = "교과서에선 이미 오래전에 실종됐었다고 했어요.",
  ui_story_5014_50140602_23_dialog_content = "맞아요. 10여 년 전 시모스 씨가 보낸 마지막 메시지도\n이 툰드라 지역 근처에서 보낸 거였어요.",
  ui_story_5014_50140602_24_dialog_content = "분명히... 그분이 맞을 거예요... 그렇겠죠... 그럼, 전...",
  ui_story_5014_50140602_25_dialog_content = "그럼 우리가 받은 신호도 시모스 씨가 남기신 거겠죠?",
  ui_story_5014_50140602_26_dialog_content = "네. 역시 저 자매와 다시 이야기를 해 봐야겠어요.",
  ui_story_5014_50140602_27_dialog_content = "왠지 나도 뭔가 좀 말을 해야 할 것 같아...",
  ui_story_5014_50140602_28_dialog_content = "무슨 말을 하려고요?",
  ui_story_5014_50140602_29_dialog_content = "난 이 옷을 얼른 갈아입고 싶어... 하지만 로봇한테 잡히고 싶지도 않아.",
  ui_story_5014_50140602_30_dialog_content = "저 애들이 로봇을 조종하는 거라면...",
  ui_story_5014_50140602_31_dialog_content = "크흠, 그 문제도 저한테 맡기세요.",
  ui_story_5014_50140602_32_dialog_content = "발렌시아 양, 그레텔 양... 암귀는 저희가 쓰러트렸어요.",
  ui_story_5014_50140602_33_dialog_content = "이제 좀 차분하게 이야기를 나눠보기로 해요.",
  ui_story_5014_50140602_34_dialog_content = "언니... 언니... 그건 왜 가지고 왔어?",
  ui_story_5014_50140602_35_dialog_content = "그레텔, 조용히 있어. 물어보고 싶은 게 있으니까.",
  ui_story_5014_50140602_36_dialog_content = "시오반 씨, 이게 뭔지 알아?",
  ui_story_5014_50140602_37_dialog_content = "왠지 탐험 훈장 같은데?\n일루미나가 큰 공헌을 세운 탐험가한테 주는 거야.",
  ui_story_5014_50140602_38_dialog_content = "맞아요. 구형 탐험 훈장이에요. 게다가 최고 등급의 훈장이죠.",
  ui_story_5014_50140602_39_dialog_content = "자세히 보진 못했지만, 아마 거기 「시모스」라고 새겨져 있을 거예요.",
  ui_story_5014_50140602_40_dialog_content = "응, 맞아. 이건 아빠 유품이야.",
  ui_story_5014_50140602_41_dialog_content = "당신 아버지가 뭔가 메시지를 남기진 않았나요?",
  ui_story_5014_50140602_42_dialog_content = "시모스 씨는 계속 일루미나의 통신기로 바깥에 메시지를 보내셨어요.",
  ui_story_5014_50140602_43_dialog_content = "분명히 뭔가 우리에게 전하고 싶은 말이 있었을 거예요.",
  ui_story_5014_50140602_44_dialog_content = "아빠는...",
  ui_story_5014_50140602_45_dialog_content = "언니, 더는 말하면 안 돼!",
  ui_story_5014_50140602_46_dialog_content = "설마 전부 다 얘기할 거야?",
  ui_story_5014_50140602_47_dialog_content = "결국 집사를 해치게 만들 거라고!",
  ui_story_5014_50140602_48_dialog_content = "그레텔, 나도 무슨 말을 해야 할지 정도는 알아!",
  ui_story_5014_50140602_49_dialog_content = "삑── 삐익──",
  ui_story_5014_50140602_50_dialog_content = "<color=#e8d9bb>이곳은... 안전하지 않습니다...</color>",
  ui_story_5014_50140602_51_dialog_content = "집사, 너야? 무슨 일이야?",
  ui_story_5014_50140602_52_dialog_content = "<color=#e8d9bb>암귀가... 오고... 있습니다.</color>",
  ui_story_5014_50140602_53_dialog_content = "<color=#e8d9bb>절 따라... 안전한 곳으로... 이동하십시오...</color>",
  ui_story_5014_50140602_54_dialog_content = "언니, 어서 가자.",
  ui_story_5014_50140602_55_dialog_content = "근데 근처에서 암귀가 느껴지진 않는데?",
  ui_story_5014_50140602_56_dialog_content = "꼭 가야 할까?",
  ui_story_5014_50140602_57_dialog_content = "아는 척하지 마!",
  ui_story_5014_50140602_58_dialog_content = "집사 말은 틀림없어!",
  ui_story_5014_50140602_59_dialog_content = "언니, 가자!",
  ui_story_5014_50140701_1_dialog_content = "발렌시아, 좀 더 얘기해 줘.",
  ui_story_5014_50140701_2_dialog_content = "너희 어머니도 일루미나 연구원이었어?",
  ui_story_5014_50140701_3_dialog_content = "아니... 엄마는 백야성 사람이었어.",
  ui_story_5014_50140701_4_dialog_content = "무슨 「귀족」이었다던가, 잘은 모르겠어.",
  ui_story_5014_50140701_5_dialog_content = "어머니가 백야성의 귀족이었다고?",
  ui_story_5014_50140701_6_dialog_content = "우리가 아는 사람일지도 몰라. 이름을 좀 알려줄 수 있을까?",
  ui_story_5014_50140701_7_dialog_content = "아빠는 엄마를 「클라우드」라고 불렀어.",
  ui_story_5014_50140701_8_dialog_content = "「클라우드」... 가명인 모양이네.",
  ui_story_5014_50140701_9_dialog_content = "어머니가 백야성에 대해 말한 적 있어?",
  ui_story_5014_50140701_10_dialog_content = "엄마는 바깥세상의 일을 떠올리기 싫어해서 거의 말을 안 했어.",
  ui_story_5014_50140701_11_dialog_content = "그럼 어머니가 어떻게 여기 오게 된 건지는 알아?",
  ui_story_5014_50140701_12_dialog_content = "아빠는 두 사람이 우연히 여기 오게 됐다고 했어.\n그 뒤로는 밖으로 나가는 길도 못 찾았고.",
  ui_story_5014_50140701_13_dialog_content = "그땐 너무 어려서 기억이 잘 안 나.",
  ui_story_5014_50140701_14_dialog_content = "흥... 칫... 흥!",
  ui_story_5014_50140701_15_dialog_content = "발렌시아, 동생이 화가 많이 난 것 같은데, 왜 그래?",
  ui_story_5014_50140701_16_dialog_content = "흥, 참견하지 마!",
  ui_story_5014_50140701_17_dialog_content = "아얏! 왜 날 차는데?!",
  ui_story_5014_50140701_18_dialog_content = "그레텔, 왜 아직도 화가 나 있어?",
  ui_story_5014_50140701_19_dialog_content = "언니야말로 왜 아무 말이나 다 해?",
  ui_story_5014_50140701_20_dialog_content = "말했잖아. 이 사람들은 믿을 수 있을 것 같다고.",
  ui_story_5014_50140701_21_dialog_content = "이젠 집사 말도 안 듣겠다는 거야?!",
  ui_story_5014_50140701_22_dialog_content = "너야말로 언니한테 그게 무슨 말투야?",
  ui_story_5014_50140701_23_dialog_content = "<color=#e8d9bb>분쟁의... 좋은 해결 방법은... 소통입니다.</color>",
  ui_story_5014_50140701_24_dialog_content = "흥! 상관 안 해. 분명히 언니가 잘못한 거야.",
  ui_story_5014_50140701_25_dialog_content = "집사, 언니는 됐으니까 우리끼리 가자!",
  ui_story_5014_50140701_26_dialog_content = "미안해, 너희 사이를 망칠 생각은 아니었어...",
  ui_story_5014_50140701_27_dialog_content = "하지만 우리가 일루미나에서 온 동료라는 건 이미 증명했잖아.",
  ui_story_5014_50140701_28_dialog_content = "그런데도 왜 동생은 우릴 적대시하는 거야?",
  ui_story_5014_50140701_29_dialog_content = "사실... 그레텔이 태어나고 얼마 뒤에,\n아빠랑 엄마는 암귀의 습격으로 돌아가셨어.",
  ui_story_5014_50140701_30_dialog_content = "난 엄마랑 아빠한테 바깥세상에 대해 배웠지만, 그레텔은 그런 경험이 없어.",
  ui_story_5014_50140701_31_dialog_content = "오직 나랑 집사 둘이서만 돌봐왔던 거야.",
  ui_story_5014_50140701_32_dialog_content = "그랬구나... 그럼 우리가 갑자기 나타나서 동생이 불안했겠네...",
  ui_story_5014_50140701_33_dialog_content = "응, 맞아.",
  ui_story_5014_50140701_34_dialog_content = "그레텔한테 엄마랑 아빠에 대해 많이 얘기해 주고 싶었는데...\n정작 나도 아는 게 별로 없어서...",
  ui_story_5014_50140701_35_dialog_content = "시모스 씨가 남긴 자료와 원고는 일루미나에 많이 보관되어 있어요.",
  ui_story_5014_50140701_36_dialog_content = "궁금한 게 있으면 제가 전부 얘기해 줄게요.",
  ui_story_5014_50140701_37_dialog_content = "다행이네...",
  ui_story_5014_50140701_38_dialog_content = "당신 아버지는 고대 유적과 고대 과학 기술 연구에 뛰어난 과학자 겸 탐험가셨어요.",
  ui_story_5014_50140701_39_dialog_content = "그건 알고 있죠?",
  ui_story_5014_50140701_40_dialog_content = "알아. 아빠는 계속 이곳을 연구했어.",
  ui_story_5014_50140701_41_dialog_content = "아빠는 이곳이 「고대의 도시」라고 했고,\n저 기계들은 「대단한 고대의 기술」이라고 했어.",
  ui_story_5014_50140701_42_dialog_content = "그리고 집사랑 같이 여러 로봇과 시스템 모듈을 수리했어.",
  ui_story_5014_50140701_43_dialog_content = "전에 쓰신 논문 중에는 고대의 기계를 복원하는 기술에 대한 내용도 있었어요.",
  ui_story_5014_50140701_44_dialog_content = "저 자판기, 통조림 운반 드론, 그리고 통조림 공장...",
  ui_story_5014_50140701_45_dialog_content = "전부 당신 아버지가 복구하신 거죠?",
  ui_story_5014_50140701_46_dialog_content = "일부는 그렇지만, 그렇지 않은 것도 있어.",
  ui_story_5014_50140701_47_dialog_content = "아빠 말로는 원래부터 손상되지 않았던 것들도 있다고 했어.",
  ui_story_5014_50140701_48_dialog_content = "원래부터 손상되지 않았던 건 뭐죠?",
  ui_story_5014_50140701_49_dialog_content = "저 공장들. 아빠는 공장 쪽엔 그다지 수리할 게 없었다고 했어.",
  ui_story_5014_50140701_50_dialog_content = "공장은 집사의 지휘에 따라 움직이거나 멈춰.",
  ui_story_5014_50140701_51_dialog_content = "저긴 자동으로 옷이나 음식을 생산할 수 있고,\n제품을 「슈퍼」에 진열하기도 해.",
  ui_story_5014_50140701_52_dialog_content = "「슈퍼」가 뭐지?",
  ui_story_5014_50140701_53_dialog_content = "「슈퍼마켓」 말이야.\n안에는 뭐든지 있고, 먹고 싶은 걸 마음대로 고를 수 있어.",
  ui_story_5014_50140701_54_dialog_content = "역시 이곳의 물건은 모두 자동이었구나. 정말 상상을 뛰어넘잖아...",
  ui_story_5014_50140701_55_dialog_content = "그게 바로 고대의 자동화 기술이에요... 정말 대단하네요.",
  ui_story_5014_50140701_56_dialog_content = "그럼 너흰 평소에 어떻게 지냈어?",
  ui_story_5014_50140701_57_dialog_content = "그냥... 평범하게 살았어.",
  ui_story_5014_50140701_58_dialog_content = "음, 조금 더 구체적으로 물어볼게.\n옷이 더러워지면 어떡해?",
  ui_story_5014_50140701_59_dialog_content = "「세탁기」에 집어넣기만 하면 기계가 대신 씻어줘.",
  ui_story_5014_50140701_60_dialog_content = "목욕하고 싶을 때는?",
  ui_story_5014_50140701_61_dialog_content = "집사한테 말하면 로봇이 뜨거운 물을 준비해 줘.",
  ui_story_5014_50140701_62_dialog_content = "방 청소하고 싶을 때는?",
  ui_story_5014_50140701_63_dialog_content = "집사한테 말하면 로봇이 청소해 줘.",
  ui_story_5014_50140701_64_dialog_content = "책을 읽고 싶을 때는?",
  ui_story_5014_50140701_65_dialog_content = "집사한테 말하면 로봇이 읽어줘.",
  ui_story_5014_50140701_66_dialog_content = "그, 그럼 임무를 맡거나 보고서를 쓸 때는?",
  ui_story_5014_50140701_67_dialog_content = "임무? 보고서? 그런 건 로봇이 하는 일 아냐?",
  ui_story_5014_50140701_68_dialog_content = "세상에, 정말 행복한 생활이잖아!",
  ui_story_5014_50140701_69_dialog_content = "그런 생활이라니, 정말 끔찍해.\n아무것도 안 해도 된다니, 마치 사육되고 있는 것 같잖아...",
  ui_story_5014_50140701_70_dialog_content = "나도 좀 끼어들어도 될까? 나도 묻고 싶은 게 있어.",
  ui_story_5014_50140701_71_dialog_content = "뭔데?",
  ui_story_5014_50140701_72_dialog_content = "여긴 남자 옷 만드는 공장은 없어?",
  ui_story_5014_50140701_73_dialog_content = "음, 그 공장은 망가진 것 같아. 아마... 데이터가 파손됐을걸.",
  ui_story_5014_50140701_74_dialog_content = "뭐?! 그럼 너희 아버지는... 무슨 옷을 입었어?",
  ui_story_5014_50140701_75_dialog_content = "아빠가 입는 건 일루미나의 옷이라고 했었어.",
  ui_story_5014_50140701_76_dialog_content = "근데 그럼 여기 로봇이 공격하잖아...",
  ui_story_5014_50140701_77_dialog_content = "아빠는 권한 레벨이 높았거든.\n집사한테 말하면 로봇이 공격하지 않아.",
  ui_story_5014_50140701_78_dialog_content = "그럼 너희 집사랑 이야기할 수 있게 해 줘!",
  ui_story_5014_50140701_79_dialog_content = "어라? 집사는? 그 집사라는 로봇, 어디 갔지?",
  ui_story_5014_50140701_80_dialog_content = "마침 저도 그 집사에게 할 얘기가 있던 참이에요.",
  ui_story_5014_50140701_81_dialog_content = "지금 아마 공장 구역에 있을 거야.",
  ui_story_5014_50140701_82_dialog_content = "바로 여기야...",
  ui_story_5014_50140701_83_dialog_content = "<color=#e8d9bb>환영, 합니다. 저는 이곳의, 집사입니다.</color>",
  ui_story_5014_50140701_84_dialog_content = "여기 로봇들은 새 거 같은데... 방금 생산된 거야?",
  ui_story_5014_50140701_85_dialog_content = "<color=#e8d9bb>이것은... 방금 개조된, 동료입니다.</color>",
  ui_story_5014_50140701_86_dialog_content = "집사, 당신은 왜 우리의 말을 할 줄 아는 거죠?",
  ui_story_5014_50140701_87_dialog_content = "<color=#e8d9bb>시모스에게... 배웠, 습니다.</color>",
  ui_story_5014_50140701_88_dialog_content = "...스스로 배운 건가요?",
  ui_story_5014_50140701_89_dialog_content = "당신은 누구의 조종을 받고 있죠?",
  ui_story_5014_50140701_90_dialog_content = "<color=#e8d9bb>당신, 은... 시모스와, 비슷하군요.</color>",
  ui_story_5014_50140701_91_dialog_content = "<color=#e8d9bb>당신들의... 용어로, 말하면.</color>",
  ui_story_5014_50140701_92_dialog_content = "<color=#e8d9bb>저는... 학습 능력을 가진, 인공지능입니다.</color>",
  ui_story_5014_50140701_93_dialog_content = "......",
  ui_story_5014_50140701_94_dialog_content = "<color=#e8d9bb>이 도시는, 제 관리하에, 있습니다... 여러분, 제 지시에, 따라 주십시오.</color>",
  ui_story_5014_50140701_95_dialog_content = "<color=#e8d9bb>그렇지, 않을 경우... 처벌이, 가해질 것입니다.</color>",
  ui_story_5014_50140701_96_dialog_content = "그럼 우릴 여기서 내보내 줄 순 없어?",
  ui_story_5014_50140701_97_dialog_content = "그럼 나도 더는 내 옷차림에 신경 쓰지 않아도 되잖아.",
  ui_story_5014_50140701_98_dialog_content = "<color=#e8d9bb>도시의, 안전이... 최우선, 입니다.</color>",
  ui_story_5014_50140701_99_dialog_content = "<color=#e8d9bb>더 많은, 외부인이... 침입하지, 않도록.</color>",
  ui_story_5014_50140701_100_dialog_content = "<color=#e8d9bb>당신들은, 이곳을... 떠날 수 없습니다.</color>",
  ui_story_5014_50140701_101_dialog_content = "<color=#e8d9bb>다시 한번, 말합니다... 여러분, 제 지시에, 따라 주십시오.</color>",
  ui_story_5014_50140701_102_dialog_content = "알겠어요. 당신의 지시에 따르겠어요.\n다만 먼저 확인하고 싶은 게 있어요...",
  ui_story_5014_50140701_103_dialog_content = "마굴의 속삭임이 사람을 미치게 만들 거야... 비켜줘.",
  ui_story_5014_50140701_104_dialog_content = "<color=#e8d9bb>챙──!</color>",
  ui_story_5014_50140701_105_dialog_content = "...방해하지 마.",
  ui_story_5014_50140701_106_dialog_content = "에리카, 뭘 하려는 거야?!",
  ui_story_5014_50140701_107_dialog_content = "학습 능력을 갖춘 인공지능, 로봇을 개조할 수 있는 로봇...",
  ui_story_5014_50140701_108_dialog_content = "확실히 이단심문조의 숙적, 저들이 말살해야 할 대상이죠.",
  ui_story_5014_50140701_109_dialog_content = "알고 있으면 비켜. 설마 그 로봇을 일루미나로 가져갈 생각이야?",
  ui_story_5014_50140701_110_dialog_content = "「네」라고 대답한다면, 저도 함께 말살할 건가요?",
  ui_story_5014_50140701_111_dialog_content = "역시... 너흰 위험해.",
  ui_story_5014_50140701_112_dialog_content = "언니, 어서 이리 와! 녀석들이랑 같이 있으면 안 돼!",
  ui_story_5014_50140701_113_dialog_content = "잠깐만, 내 말 좀 들어 봐!",
  ui_story_5014_50140701_114_dialog_content = "미안해... 그레텔, 저 사람들이 정말로 집사를 해치려 할 줄은 몰랐어.",
  ui_story_5014_50140701_115_dialog_content = "흥, 언니는 속기 쉬우니까 그래.",
  ui_story_5014_50140701_116_dialog_content = "하지만... 그것도 전부 저 도둑놈들, 사기꾼들 때문이야!",
  ui_story_5014_50140701_117_dialog_content = "집사, 전투 로봇을 가동해.",
  ui_story_5014_50140701_118_dialog_content = "녀석들을 잡아!",
  ui_story_5014_50140702_1_dialog_content = "이런, 암귀들이 몰려왔어.",
  ui_story_5014_50140702_2_dialog_content = "로봇도 끝없이 몰려오고 있어... 어서 도망쳐야 해.",
  ui_story_5014_50140702_3_dialog_content = "발렌시아, 그레텔, 너희도 같이 도망가자!",
  ui_story_5014_50140702_4_dialog_content = "여긴 위험해!",
  ui_story_5014_50140702_5_dialog_content = "이런 상황에서도 아직 설득할 생각이 있는 거야?!",
  ui_story_5014_50140702_6_dialog_content = "자기 걱정이나 하지 그래...",
  ui_story_5014_50140702_7_dialog_content = "전투 로봇! 녀석들을 포위해!",
  ui_story_5014_50140702_8_dialog_content = "삑── 삐익──",
  ui_story_5014_50140702_9_dialog_content = "발렌시아, 정말 우릴 해칠 생각이야?",
  ui_story_5014_50140702_10_dialog_content = "......",
  ui_story_5014_50140702_11_dialog_content = "집사... 여긴 너한테 맡길게.",
  ui_story_5014_50140702_12_dialog_content = "어서 가자, 그레텔... 안전한 곳으로.",
  ui_story_5014_50140702_13_dialog_content = "그래, 언니.",
  ui_story_5014_50140702_14_dialog_content = "발렌시아!",
  ui_story_5014_50140702_15_dialog_content = "소용없어... 우린 이제 저들의 적이라고.",
  ui_story_5014_50140702_16_dialog_content = "이게 다 너희 때문이잖아!",
  ui_story_5014_50140702_17_dialog_content = "너희가 갑자기 남의 「집사」를 공격했으니까!",
  ui_story_5014_50140702_18_dialog_content = "「집사」? 설마 저걸 사람 취급할 생각이야?",
  ui_story_5014_50140702_19_dialog_content = "사람은 아니어도, 저 애들에겐 가족이라고...",
  ui_story_5014_50140702_20_dialog_content = "저건 인공지능이야!",
  ui_story_5014_50140702_21_dialog_content = "인공지능이 뭐 어쨌다고... 그래도 가족이잖아?",
  ui_story_5014_50140702_22_dialog_content = "여기 스카이워커가 있었으면 너흰 스카이워커도 공격할 작정이야?!",
  ui_story_5014_50140702_23_dialog_content = "스카이워커... 그렇네, 넌 콜로서스 조종사였지.",
  ui_story_5014_50140702_24_dialog_content = "맞아. 난 지하에서 17년을 살았고,\n그동안 내 곁엔 스카이워커밖에 없었어.",
  ui_story_5014_50140702_25_dialog_content = "저 애들도 마찬가지야. 곁에 있어 준 건 「집사」뿐이었겠지.",
  ui_story_5014_50140702_26_dialog_content = "그런 존재를 공격한 건 작정하고 도발한 거나 마찬가지라고.",
  ui_story_5014_50140702_27_dialog_content = "......",
  ui_story_5014_50140702_28_dialog_content = "미안해. 우리가 너무 충동적이었어.",
  ui_story_5014_50140702_29_dialog_content = "회장... 내가 잘못한 거야? 내가 한 일이잖아... 그럼 내가...",
  ui_story_5014_50140702_30_dialog_content = "아니, 넌 우리의 신앙을 지켰을 뿐이야.",
  ui_story_5014_50140702_31_dialog_content = "설마 너흰 개인의 신앙을 위해서 무슨 일이든...",
  ui_story_5014_50140702_32_dialog_content = "이건 개인의 신앙에만 국한된 문제가 아니야!",
  ui_story_5014_50140702_33_dialog_content = "자, 다들 그만해. 우선 공장을 벗어나야 해.",
  ui_story_5014_50140702_34_dialog_content = "<color=#e8d9bb>안타깝지만... 이건 그레텔의 명령입니다.</color>",
  ui_story_5014_50140702_35_dialog_content = "<color=#e8d9bb>당신들은 이미, 포위되었습니다.</color>",
  ui_story_5014_50140702_36_dialog_content = "넌... 집사야? 아까 그 로봇이랑 다르잖아...",
  ui_story_5014_50140702_37_dialog_content = "마음대로 다른 로봇으로 몸을 옮길 수 있는 건가?",
  ui_story_5014_50140702_38_dialog_content = "이곳의 로봇은 모두 저 집사의 제어를 받고 있어요.",
  ui_story_5014_50140702_39_dialog_content = "그럼 이제 어떡하지?",
  ui_story_5014_50140702_40_dialog_content = "당신과 에리카는 모두를 이끌고 도망치세요.",
  ui_story_5014_50140702_41_dialog_content = "힘을 합치면 포위를 돌파할 수 있을 거예요.\n제가 후방을 맡겠어요.",
  ui_story_5014_50140702_42_dialog_content = "안 돼. 적이 너무 많아. 후방을 맡는 건 위험해.",
  ui_story_5014_50140702_43_dialog_content = "내가 남겠어!",
  ui_story_5014_50140702_44_dialog_content = "당신은 백야성에서 가장 뛰어난 탐험가죠.\n가장 이성적인 방법은 제가 뒤를 맡고 당신이 포위를 돌파하는 거예요.",
  ui_story_5014_50140702_45_dialog_content = "그렇게 하면 모두의 생존율도 가장 높을 거예요.",
  ui_story_5014_50140702_46_dialog_content = "왜 내가 뒤를 맡고, 일루미나의 탐험가인 당신이 도망을 치는 게 아닌데?",
  ui_story_5014_50140702_47_dialog_content = "여기서 계급이 가장 높은 건 저예요.\n어떻게 백야성 사람에게 엄호를 부탁할 수 있겠어요?",
  ui_story_5014_50140702_48_dialog_content = "<color=#e8d9bb>일루미나와 백야성... 전에도, 이런 말싸움을, 들었습니다.</color>",
  ui_story_5014_50140702_49_dialog_content = "<color=#e8d9bb>시모스와 클라우드가... 있을 때였죠.</color>",
  ui_story_5014_50140702_50_dialog_content = "하고 싶은 말이 뭐야?",
  ui_story_5014_50140702_51_dialog_content = "<color=#e8d9bb>여러분, 오로리안은... 흥미롭군요.</color>",
  ui_story_5014_50140702_52_dialog_content = "당신도 흥미롭네요... 말투가 점점 저희와 비슷해지고 있어요.",
  ui_story_5014_50140702_53_dialog_content = "<color=#e8d9bb>저는... 학습, 능력을 가진... 인공지능입니다.</color>",
  ui_story_5014_50140702_54_dialog_content = "시모스 씨한테 전투 지휘까진 배우지 않았길 빌어야겠네요...",
  ui_story_5014_50140702_55_dialog_content = "PlayerName, 저와 플로리나가 뒤를 맡을 테니 어서 포위를 뚫으세요!",
  ui_story_5014_50140702_56_dialog_content = "에리카, 정신 바짝 차리고 카렌 님을 도와드려!",
  ui_story_5014_50140702_57_dialog_content = "알겠어... 회장.",
  ui_story_5014_50140702_58_dialog_content = "그럼 내가 지휘할게. 포위를 뚫자.",
  ui_story_5014_50140801_1_dialog_content = "어떡하지... 이러다 로봇들한테 따라잡히겠어.",
  ui_story_5014_50140801_2_dialog_content = "좀 더 빨리 달려야 해. 겨우 돌파한 마당에...",
  ui_story_5014_50140801_3_dialog_content = "<color=#e8d9bb>쿠르르릉──!</color>",
  ui_story_5014_50140801_4_dialog_content = "또 지진이야! 다들 조심해! 돌이 떨어질 거야!",
  ui_story_5014_50140801_5_dialog_content = "저쪽에 넓은 공터가 있어. 내가 안내할게.",
  ui_story_5014_50140801_6_dialog_content = "<size=30><color=#e8d9bb>우르르르...</color></size>",
  ui_story_5014_50140801_7_dialog_content = "<color=#e8d9bb>지...진... 주의...</color>",
  ui_story_5014_50140801_8_dialog_content = "<color=#e8d9bb>삑── 삐익──</color>",
  ui_story_5014_50140801_9_dialog_content = "사악한 로봇이... 망가졌어.",
  ui_story_5014_50140801_10_dialog_content = "이곳의 시설은 지진의 영향을 받는다고 시오반 선생님이 그랬어.",
  ui_story_5014_50140801_11_dialog_content = "집사가 일시적으로 로봇을 제어할 수 없게 된 것 같아...",
  ui_story_5014_50140801_12_dialog_content = "<color=#e8d9bb>지직, 지지직──</color>",
  ui_story_5014_50140801_13_dialog_content = "통신기가 또 반응했어.",
  ui_story_5014_50140801_14_dialog_content = "또 그 신호야?",
  ui_story_5014_50140801_15_dialog_content = "그거랑은 달라. 하지만 암호화된 신호라서 분석해야 내용을 알 수 있어.",
  ui_story_5014_50140801_16_dialog_content = "뭐가 다른데? 전의 것도 「암호화 신호」였잖아.",
  ui_story_5014_50140801_17_dialog_content = "일루미나 탐험대의 통신기는 암호화된 데이터를 주고받을 수 있어...",
  ui_story_5014_50140801_18_dialog_content = "전에 받은 건 단순한 위치 정보였는데, 이번 건 음성 데이터야.",
  ui_story_5014_50140801_19_dialog_content = "분명히 지진이 어떤 시스템을 발동시켰고,\n시모스 씨의 장치가 음성 데이터를 만든 거야.",
  ui_story_5014_50140801_20_dialog_content = "뭘 전하려는 거지?",
  ui_story_5014_50140801_21_dialog_content = "이 암호화 방식은 나도 잘 몰라.\n탐험대 통용 키로 일부만 해독하는 게 한계야.",
  ui_story_5014_50140801_22_dialog_content = "아무튼 시간이 좀 필요해!",
  ui_story_5014_50140801_23_dialog_content = "<size=30><color=#e8d9bb>우르르르...</color></size>",
  ui_story_5014_50140801_24_dialog_content = "바이스, 뭔가 해독했어?",
  ui_story_5014_50140801_25_dialog_content = "전부 단편적인 정보야. 게다가 전부 다른 시기에 만들어진 것 같아.",
  ui_story_5014_50140801_26_dialog_content = "하나씩 읽어볼게...",
  ui_story_5014_50140801_27_dialog_content = "먼저 첫 번째 단락에선 「고대의 대전쟁」에 대해 언급하고 있어.",
  ui_story_5014_50140801_28_dialog_content = "여기서 옛날에 전쟁이 있었어? 전혀 들어본 적 없는데...",
  ui_story_5014_50140801_29_dialog_content = "너무 오래된 일이라서 그래.\n어떤 역사 자료나 기록에도 「고대의 대전쟁」은 적혀 있지 않아.",
  ui_story_5014_50140801_30_dialog_content = "그래도 많은 학자들은 「고대의 대전쟁」이 실제로 일어났었다고 믿고 있어.",
  ui_story_5014_50140801_31_dialog_content = "시모스 씨는 이 도시가 고대인이 남긴 대형 피난소라고 했어.",
  ui_story_5014_50140801_32_dialog_content = "이걸 만든 목적은 전쟁 그 자체를 피하기 위해서일 수도 있고,\n전후에 벌어질 재난을 대비하기 위해서일 수도 있어.",
  ui_story_5014_50140801_33_dialog_content = "「하지만 그 고대인들은 이미 완전히 사라져 버렸고,\n이곳에는 집사라고 불리는 인공지능만이 존재한다.」",
  ui_story_5014_50140801_34_dialog_content = "「그것은 이 도시의 모든 시설을 관리하고 있지만,\n고대에 관한 내 질문에는 전혀 답을 하지 않는다.」",
  ui_story_5014_50140801_35_dialog_content = "「이곳의 시간과 공간은 매우 기묘하다. 하지만 그 원인은 불분명하다.」",
  ui_story_5014_50140801_36_dialog_content = "이 뒷부분은 아직 해독하지 못했어. 좀 더 복잡한 암호화가 되어있는 것 같아.",
  ui_story_5014_50140801_37_dialog_content = "왜 굳이 그렇게 복잡하게 만든 거지?",
  ui_story_5014_50140801_38_dialog_content = "암호화는 보통 정보 보안을 위해서야. 분명히 매우 중요한 정보인 거겠지.",
  ui_story_5014_50140801_39_dialog_content = "지금은 일단 기록해 두었다가 일루미나로 가지고 가거나,\n아니면 시오반 선생님한테 해독을 부탁해야겠어.",
  ui_story_5014_50140801_40_dialog_content = "그래. 그럼 그 사람이 남긴 다른 정보는 없어?",
  ui_story_5014_50140801_41_dialog_content = "두 번째 단락인데, 여기 오기 전에... 백야성의 한 소녀를 만났다고 해.",
  ui_story_5014_50140801_42_dialog_content = "「툰드라 지역을 조사하던 중 백야성에서 온 소녀와 우연히 마주쳤다.」",
  ui_story_5014_50140801_43_dialog_content = "「우린 암귀의 습격을 받았고, 의도치 않게 이 도시에 오게 되었다.」",
  ui_story_5014_50140801_44_dialog_content = "그 소녀가 그 사람의 부인이겠지?",
  ui_story_5014_50140801_45_dialog_content = "응, 두 사람은 여기 갇힌 걸 알고, 힘을 합쳐 이곳을 탐색하기로 했어...",
  ui_story_5014_50140801_46_dialog_content = "「이곳에는 무기를 제조하는 공장은 없다.\n집사는 우릴 지켜줄 방법이 없다.」",
  ui_story_5014_50140801_47_dialog_content = "「다행히 우린 시스템의 바이오케미컬 모듈을 복구할 수 있었다.」",
  ui_story_5014_50140801_48_dialog_content = "「집사는 그것을 애비라고 불렀고,\n애비의 도움으로 우리는 일시적으로 암귀의 위협을 막아낼 수 있었다.」",
  ui_story_5014_50140801_49_dialog_content = "「바이오케미컬 모듈」은 뭐지? 「애비」가 모듈의 이름인가?",
  ui_story_5014_50140801_50_dialog_content = "「바이오 모듈」이라고 해석할 수도 있긴 해.\n근데 나도 그게 뭔지는 잘 모르겠어.",
  ui_story_5014_50140801_51_dialog_content = "다음 단락에는 이곳에서 몇 년 동안 생활한 뒤의 일들이 기록돼 있어.",
  ui_story_5014_50140801_52_dialog_content = "「암귀의 수가 계속해서 늘어나고 있다. 하지만 놈들이 어디서 침입한 것인지는 알 수 없다.」",
  ui_story_5014_50140801_53_dialog_content = "「집사는 이 물음에 대답하려 하지 않는다.」",
  ui_story_5014_50140801_54_dialog_content = "「암귀에 맞설 방법을 찾아야만 한다. 출구를 찾을 수 있다면 가장 좋을 것이다.」",
  ui_story_5014_50140801_55_dialog_content = "「집사는 항상 나를 감시하고 있다. 어떻게든 녀석의 눈을 피해야 한다.」",
  ui_story_5014_50140801_56_dialog_content = "「동포여, 부디 이 메시지를 받을 수 있기를...」",
  ui_story_5014_50140801_57_dialog_content = "그리고 이다음이 마지막이야...",
  ui_story_5014_50140801_58_dialog_content = "「당신이 이 메시지를 받을 때면 나는 이미 이 세상에 없을지도 모른다.」",
  ui_story_5014_50140801_59_dialog_content = "「하지만 가족들을 지킬 방법을 찾았다. 나는 집사와 계약을 했다...」",
  ui_story_5014_50140801_60_dialog_content = "「내 아내와 딸은 분명히 이곳에서 편안하게 살아갈 수 있을 것이다.」",
  ui_story_5014_50140801_61_dialog_content = "「만약 가능하다면, 가족들을 부탁하고 싶다...\n가족들을 데리고 이곳을 떠나주길 바란다.」",
  ui_story_5014_50140801_62_dialog_content = "「내 방에 정보를 몇 개 남겨놓을 것이다. 좌표는...」",
  ui_story_5014_50140801_63_dialog_content = "좌표는?",
  ui_story_5014_50140801_64_dialog_content = "음... 미안... 자세한 위치는 해독을 못 했어.",
  ui_story_5014_50140801_65_dialog_content = "그 뒤에 더 남긴 말은 없어?",
  ui_story_5014_50140801_66_dialog_content = "마지막으로 남긴 말이 있어.\n「일루미나의 동포들, 전우들... 부탁한다.」",
  ui_story_5014_50140801_67_dialog_content = "「여명의 빛을 위하여.」",
  ui_story_5014_50140801_68_dialog_content = "거기서 끝인 거야?",
  ui_story_5014_50140801_69_dialog_content = "응, 데이터에는 이것들뿐이야.\n하지만 제일 중요한 부분을 해독할 수가 없었어.",
  ui_story_5014_50140801_70_dialog_content = "<size=30><color=#e8d9bb>우르르르...</color></size>",
  ui_story_5014_50140801_71_dialog_content = "여진이 계속 이어지고 있어. 시오반 선생님 쪽은 괜찮을까...",
  ui_story_5014_50140801_72_dialog_content = "......",
  ui_story_5014_50140801_73_dialog_content = "걱정할 거 없어. 지진이 집사가 로봇을 제어하는 걸 방해한다고 하잖아.",
  ui_story_5014_50140801_74_dialog_content = "곧 로봇들을 처리하고 우리 쪽으로 올 거야.",
  ui_story_5014_50140801_75_dialog_content = "네, 고마워요... 카렌 님.",
  ui_story_5014_50140801_76_dialog_content = "<color=#e8d9bb>무의미한... 저항은... 그만두십시오...</color>",
  ui_story_5014_50140801_77_dialog_content = "<color=#e8d9bb>지, 지금, 당장... 항복하십시오.</color>",
  ui_story_5014_50140801_78_dialog_content = "플로리나, 지금이에요!",
  ui_story_5014_50140801_79_dialog_content = "알고 있다고. 당신 지휘는 필요 없어.",
  ui_story_5014_50140801_80_dialog_content = "심판을 받아라, 천둥뱀의 분노!",
  ui_story_5014_50140801_81_dialog_content = "<color=#e8d9bb>콰지지직──! 퍼엉!</color>",
  ui_story_5014_50140801_82_dialog_content = "<color=#e8d9bb>이것이, 바로... 당신들의, 루미나틱스입니까?</color>",
  ui_story_5014_50140801_83_dialog_content = "<color=#e8d9bb>정말... 흥미롭군요... 참고할, 가치가 있습니다.</color>",
  ui_story_5014_50140801_84_dialog_content = "귀찮네, 또 다른 로봇으로 몸을 옮겼어.",
  ui_story_5014_50140801_85_dialog_content = "녀석이 로봇을 계속 지휘하는 한, 이 싸움은 끝나지 않을 거예요.",
  ui_story_5014_50140801_86_dialog_content = "기회를 봐서 돌파하는 게 어때?",
  ui_story_5014_50140801_87_dialog_content = "쉽지 않을 거예요. 다른 일행들을 한 번 놓친 이상,\n우릴 순순히 놓치진 않을 테니까요.",
  ui_story_5014_50140801_88_dialog_content = "집사, 당신은 제가 시모스 씨의 메시지를 해독하는 걸 막으려는 건가요?",
  ui_story_5014_50140801_89_dialog_content = "<color=#e8d9bb>도시의, 안전이... 최우선, 입니다.</color>",
  ui_story_5014_50140801_90_dialog_content = "알고 있어요. 모두 정보의 보안을 위해서겠죠.",
  ui_story_5014_50140801_91_dialog_content = "이대로 계속 싸우면 우리 쪽이 불리해.",
  ui_story_5014_50140801_92_dialog_content = "로봇들의 전투 능력이 서서히 강해지고 있는 거 느꼈어?",
  ui_story_5014_50140801_93_dialog_content = "네, 저들은 우리의 전투 방식을 계속해서 학습하고 있어요.",
  ui_story_5014_50140801_94_dialog_content = "그게 무섭다는 생각 안 들어?",
  ui_story_5014_50140801_95_dialog_content = "저런 인공지능이 계속 발전한다면,\n언젠가는 오로리안을 괴멸시킬 힘을 얻을 날이 올 거야.",
  ui_story_5014_50140801_96_dialog_content = "인공지능을 파괴하도록 설득하고 싶은 건 알아요.\n하지만 지금은... 우선 도망치는 데 전념하죠.",
  ui_story_5014_50140801_97_dialog_content = "<color=#e8d9bb>나가게 두지... 않을 겁니다.</color>",
  ui_story_5014_50140801_98_dialog_content = "<color=#e8d9bb>여러분은... 이곳에서 나갈 수 없습니다.</color>",
  ui_story_5014_50140801_99_dialog_content = "<size=30><color=#e8d9bb>우르르르...</color></size>",
  ui_story_5014_50140801_100_dialog_content = "또 여진이에요. 같이 공격하세요!",
  ui_story_5014_50140801_101_dialog_content = "말했잖아, 알고 있다고!",
  ui_story_5014_50140801_102_dialog_content = "<color=#e8d9bb>여러분은... 지지직...</color>",
  ui_story_5014_50140801_103_dialog_content = "포위를 뚫었어요! 가죠!",
  ui_story_5014_50140801_104_dialog_content = "아무래도 시간 끌기 전략은 로봇과의 싸움에도 활용할 수 있는 것 같네.",
  ui_story_5014_50140801_105_dialog_content = "하지만 다음번에는 안 통할 거예요.",
  ui_story_5014_50140801_106_dialog_content = "이제 어떻게 할 거야?",
  ui_story_5014_50140801_107_dialog_content = "시모스 씨의 음성 데이터를 받았어요. 지금 통신기를 쓸 수 있는 것 같아요.",
  ui_story_5014_50140801_108_dialog_content = "안전한 곳을 찾아서 바이스 쪽과 합류하죠.",
  ui_story_5014_50140801_109_dialog_content = "좋아, 그럼 아르바한테 로봇이 없는 곳을 찾아달라고 할게.",
  ui_story_5014_50140801_110_dialog_content = "그래요. 전 이 틈에 발렌시아에게도 메시지를 보내야겠어요.",
  ui_story_5014_50140801_111_dialog_content = "어째서?",
  ui_story_5014_50140801_112_dialog_content = "두 사람은 제 전우의 딸들이에요.",
  ui_story_5014_50140801_113_dialog_content = "시모스 씨는 딸들을 부탁한다는 메시지를 남겼어요.",
  ui_story_5014_50140801_114_dialog_content = "저들을 두고 갈 순 없어요...",
  ui_story_5014_50140801_115_dialog_content = "<color=#e8d9bb>지직... 지지직...</color>",
  ui_story_5014_50140801_116_dialog_content = "집사, 녀석들을 놓친 거야?!",
  ui_story_5014_50140801_117_dialog_content = "<color=#e8d9bb>신호에... 문제가 생겼습니다...</color>",
  ui_story_5014_50140801_118_dialog_content = "<color=#e8d9bb>여러분의 안전... 확보를... 위해...</color>",
  ui_story_5014_50140801_119_dialog_content = "<color=#e8d9bb>이곳에... 숨어... 있으셔야... 합니다.</color>",
  ui_story_5014_50140801_120_dialog_content = "어쩔 수 없네... 집사가 회복되길 기다리자.",
  ui_story_5014_50140801_121_dialog_content = "<color=#e8d9bb>지직, 지직.</color>",
  ui_story_5014_50140801_122_dialog_content = "언니! 아빠 유품에서 소리가 나!",
  ui_story_5014_50140801_123_dialog_content = "내가 볼게!",
  ui_story_5014_50140801_124_dialog_content = "<color=#e8d9bb>지직... 지지직...</color>",
  ui_story_5014_50140801_125_dialog_content = "발렌시아... 그레텔... 이 메시지──... 분명히... 받았──... 거예요.",
  ui_story_5014_50140801_126_dialog_content = "두 사람──... 다시──... 전할 말이──...",
  ui_story_5014_50140801_127_dialog_content = "우린... 두 사람의 아버지──...의 전우──... 두 사람──... 지킬 거예요.",
  ui_story_5014_50140801_128_dialog_content = "함께... 일루미나──... 집으로──... 돌아가요.",
  ui_story_5014_50140801_129_dialog_content = "시오반 씨가 보낸 메시지야...",
  ui_story_5014_50140801_130_dialog_content = "그 여자가 보낸 거라고?!",
  ui_story_5014_50140801_131_dialog_content = "여기가 우리 집이잖아. 우린 어디에도 갈 필요 없어!",
  ui_story_5014_50140901_1_dialog_content = "시오반 선생님이 합류하자고 하신 곳은 아마 이쪽일 거야...",
  ui_story_5014_50140901_2_dialog_content = "알았어, 내가 적이 없는 길을 찾을게. 따라와.",
  ui_story_5014_50140901_3_dialog_content = "삑── 삐익──",
  ui_story_5014_50140901_4_dialog_content = "앞쪽 길에는 로봇이 순찰하고 있어. 돌아가자.",
  ui_story_5014_50140901_5_dialog_content = "이쪽이야...",
  ui_story_5014_50140901_6_dialog_content = "삑── 삐익──",
  ui_story_5014_50140901_7_dialog_content = "이 로봇들, 왜 또 발작하는 거야?",
  ui_story_5014_50140901_8_dialog_content = "루비 언니, 조심...",
  ui_story_5014_50140901_9_dialog_content = "<color=#e8d9bb>펑, 퍼엉!</color>",
  ui_story_5014_50140901_10_dialog_content = "뭘 무서워하고 그래? 다 날려버리면 되지.",
  ui_story_5014_50140901_11_dialog_content = "안 돼, 루비 언니. 그러다간 적의 공격성이 더 강해질 거야...",
  ui_story_5014_50140901_12_dialog_content = "바이스, 카렌, 앞쪽에서 오로리안이 로봇과 싸우고 있어!",
  ui_story_5014_50140901_13_dialog_content = "회장이야?!",
  ui_story_5014_50140901_14_dialog_content = "갑자기 내 앞에 튀어나오지 좀 마... 깜짝 놀랐잖아!",
  ui_story_5014_50140901_15_dialog_content = "회장의 신호가 수신이 안 돼. 넌 받았어?",
  ui_story_5014_50140901_16_dialog_content = "(「수신」...이면 감응 얘기겠지? 아무래도 플로리나를 엄청 걱정하는 것 같네.)",
  ui_story_5014_50140901_17_dialog_content = "플로리나가 아니었어. 근데 저 두 오로리안도 지금 로봇한테 포위된 것 같아.",
  ui_story_5014_50140901_18_dialog_content = "여기 또 갇힌 사람이 있단 말이야? 어서 구하러 가자.",
  ui_story_5014_50140901_19_dialog_content = "하지만 회장이...",
  ui_story_5014_50140901_20_dialog_content = "플로리나 쪽은 괜찮아. 시오반 씨가 메시지를 보냈으니까.",
  ui_story_5014_50140901_21_dialog_content = "바이스, 시오반 씨한테 다시 연락해 줘.",
  ui_story_5014_50140901_22_dialog_content = "이쪽의 포위된 오로리안부터 구하고 합류하겠다고 전해줘.",
  ui_story_5014_50140901_23_dialog_content = "알겠어.",
  ui_story_5014_50140901_24_dialog_content = "삐익── 파괴 행위를 멈추십시오. 지금 즉시...",
  ui_story_5014_50140901_25_dialog_content = "시끄러워! 저리 비켜!",
  ui_story_5014_50140901_26_dialog_content = "끄윽... 캬악!",
  ui_story_5014_50140901_27_dialog_content = "이런, 암귀까지 몰려온 것 같아!",
  ui_story_5014_50140901_28_dialog_content = "몰려온 건 암귀만이 아냐. 저 사람들도 있어.",
  ui_story_5014_50140901_29_dialog_content = "저 사람... 설마...",
  ui_story_5014_50140901_30_dialog_content = "그 유명한 카렌 공주님이잖아?!",
  ui_story_5014_50140901_31_dialog_content = "카렌, 저 사람들 알아?",
  ui_story_5014_50140901_32_dialog_content = "...몰라. 일단 적들부터 쓰러트리자.",
  ui_story_5014_50140902_1_dialog_content = "나이스 배팅!",
  ui_story_5014_50140902_2_dialog_content = "잠깐만, 내 쪽으로 치지 마!",
  ui_story_5014_50140902_3_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5014_50140902_4_dialog_content = "PlayerName!",
  ui_story_5014_50140902_5_dialog_content = "이런... 저질렀다. 기절 시켜 버렸네.",
  ui_story_5014_50140902_6_dialog_content = "상처라도 입혔다면 내가 가만두지 않았어.",
  ui_story_5014_50140902_7_dialog_content = "미안, 미안... 암귀가 가까이 가길래 쳤을 뿐이야.",
  ui_story_5014_50140902_8_dialog_content = "다치게 만들진 않았어.",
  ui_story_5014_50140902_9_dialog_content = "그쪽 공격에 말려들었잖아!",
  ui_story_5014_50140902_10_dialog_content = "진짜 미안해... 루비 언니는 자주 힘이 과해서...",
  ui_story_5014_50140902_11_dialog_content = "내가 의료 지식을 좀 알고 있으니까, 상태를 좀 봐줄게...",
  ui_story_5014_50140902_12_dialog_content = "PlayerName, 괜찮아?",
  ui_story_5014_50140902_13_dialog_content = "괜찮은 것 같아. 이제 곧 일어날 거야...",
  ui_story_5014_50140902_14_dialog_content = "으으... 머리야...",
  ui_story_5014_50140902_15_dialog_content = "일어났나요?",
  ui_story_5014_50140902_16_dialog_content = "어라... 다들 언제 왔어?",
  ui_story_5014_50140902_17_dialog_content = "...괜찮은 거야?",
  ui_story_5014_50140902_18_dialog_content = "나도 시오반 씨도 무사해. 걱정할 거 없어.",
  ui_story_5014_50140902_19_dialog_content = "방금 막 왔어요. 무슨 일이 있었는지 들었어요.",
  ui_story_5014_50140902_20_dialog_content = "몸 상태를 진찰해 봤는데, 큰 문제는 없는 것 같네요.",
  ui_story_5014_50140902_21_dialog_content = "하이~ 좀 어때?",
  ui_story_5014_50140902_22_dialog_content = "미안, 아깐 내가 힘 조절을 못 했어. 놀랐지?",
  ui_story_5014_50140902_23_dialog_content = "놀라서 쓰러진 게 아니라 에너지 폭발에 휘말린 거라고...",
  ui_story_5014_50140902_24_dialog_content = "그래, 그래, 내가 나빴어.",
  ui_story_5014_50140902_25_dialog_content = "그러니까 기회를 줘. 다시 한번 인사하자.",
  ui_story_5014_50140902_26_dialog_content = "명성이 자자한 일루미나의 탐험가 시오반 씨랑...",
  ui_story_5014_50140902_27_dialog_content = "백야성 제일의 모험가 플로리나.",
  ui_story_5014_50140902_28_dialog_content = "어떻게 다 아는 건데...",
  ui_story_5014_50140902_29_dialog_content = "왜냐면 다들 이 바닥에선 유명하거든.",
  ui_story_5014_50140902_30_dialog_content = "근데 넌 누구야?",
  ui_story_5014_50140902_31_dialog_content = "모험가 업계엔 여장이 취미인 사람은 없었던 것 같은데...",
  ui_story_5014_50140902_32_dialog_content = "스톱, 그만해. 이건 어쩔 수 없이 입고 있는 거라고!",
  ui_story_5014_50140902_33_dialog_content = "(겨우 잊고 있었는데 왜 자꾸 하나씩 말을 꺼내는 거야...)",
  ui_story_5014_50140902_34_dialog_content = "내 이름은 PlayerName, 아이테르야.\n모험가라면 들어본 적 있을 것 같은데...",
  ui_story_5014_50140902_35_dialog_content = "아, 사메야마 오빠가 자주 이야기했던 게 바로...",
  ui_story_5014_50140902_36_dialog_content = "잠깐만, 루비 언니. 지금 이런 얘기나 하고 있을 때가 아냐!",
  ui_story_5014_50140902_37_dialog_content = "본론부터 얘기하자.",
  ui_story_5014_50140902_38_dialog_content = "너흰 대체 누구지? 여긴 왜 온 거야?",
  ui_story_5014_50140902_39_dialog_content = "난 루비, 이쪽은 루즈.",
  ui_story_5014_50140902_40_dialog_content = "우린 레디젤 렌치의 대모험가야. 반가워, 카렌 공주님.",
  ui_story_5014_50140902_41_dialog_content = "공주님은 여기 보물 찾으러 온 거야? 아니면 사람 잡으러?",
  ui_story_5014_50140902_42_dialog_content = "둘 다 아냐.",
  ui_story_5014_50140902_43_dialog_content = "너흰 여기 어떻게 들어온 거지? 출구의 위치도 알고 있어?",
  ui_story_5014_50140902_44_dialog_content = "우린 아까 저 위에서 떨어졌어. 그래서 아직 상황도 잘 몰라~",
  ui_story_5014_50140902_45_dialog_content = "역시 내가 설명하는 게 좋겠어!",
  ui_story_5014_50140902_46_dialog_content = "우린 의문의 신호를 발견하고 발생지를 추적하다 커다란 지하 동굴을 발견했어.",
  ui_story_5014_50140902_47_dialog_content = "그 동굴엔 아래로 이어지는 통로가 하나 있었어...",
  ui_story_5014_50140902_48_dialog_content = "그런데 거기서 갑자기 지진이 일어나서,\n「콰당」하고 아래로 떨어져 버렸지 뭐야.",
  ui_story_5014_50140902_49_dialog_content = "그러게 내가 통로에서 떨어지라고 말을 했는데 언니가 안 들었잖아.",
  ui_story_5014_50140902_50_dialog_content = "미안, 미안~",
  ui_story_5014_50140902_51_dialog_content = "그래서? 그 통로는 어디 있지?",
  ui_story_5014_50140902_52_dialog_content = "우린 다른 지하 동굴로 미끄러져 떨어져 버렸어.",
  ui_story_5014_50140902_53_dialog_content = "왔던 길로는 돌아갈 수 없어서 그대로 동굴을 따라갔고...",
  ui_story_5014_50140902_54_dialog_content = "우물 같은 구멍을 따라 여기로 들어오게 된 거야.",
  ui_story_5014_50140902_55_dialog_content = "헤에~ 이런 곳에 이렇게 커다란 지하도시가 있고,\n보물도 잔뜩 있을 줄은 몰랐다니까.",
  ui_story_5014_50140902_56_dialog_content = "역시 우린 운이 좋아~",
  ui_story_5014_50140902_57_dialog_content = "루비 언니, 정신 차려. 우린 전부 여기 갇혔어!",
  ui_story_5014_50140902_58_dialog_content = "왜? 우리가 못 나갈지 어떻게 알아?",
  ui_story_5014_50140902_59_dialog_content = "다들 우리한테 「출구가 어디냐」고 묻잖아.\n그러니까 다들 여기 갇혀 있는 게 확실하지!",
  ui_story_5014_50140902_60_dialog_content = "아, 그럼 정말 큰일이네.",
  ui_story_5014_50140902_61_dialog_content = "어이, 왜 다들 멍하니 있어?",
  ui_story_5014_50140902_62_dialog_content = "여...여기가 지하도시라는 생각은 전혀 못 했는데...",
  ui_story_5014_50140902_63_dialog_content = "그럼 저 하늘이 가짜란 말이야?!",
  ui_story_5014_50140902_64_dialog_content = "가짜야. 진짜처럼 잘 만들긴 했지만.",
  ui_story_5014_50140902_65_dialog_content = "올라가서 두드려 보고 싶다니까. 대체 무슨 재료로 만든 걸까?",
  ui_story_5014_50140902_66_dialog_content = "들어오기 전까지 바깥은 밤이었어. 아니었으면 우리도 지하인 줄 몰랐을 거야.",
  ui_story_5014_50140902_67_dialog_content = "시공간의 이상 때문에 지금까지 여기가 지하라는 걸 전혀 못 느끼고 있었네요...",
  ui_story_5014_50140902_68_dialog_content = "우리가 도시를 탐색하는 걸 저 로봇들이 계속 방해했으니까.",
  ui_story_5014_50140902_69_dialog_content = "그럼 당신들은? 어떻게 들어온 거야?",
  ui_story_5014_50140902_70_dialog_content = "다들 거의 비슷해요.",
  ui_story_5014_50140902_71_dialog_content = "지진이 계속 발생해서 이 지하도시의 시설이 파괴됐어요.",
  ui_story_5014_50140902_72_dialog_content = "우리가 들어온 출입구도 포함해서요.",
  ui_story_5014_50140902_73_dialog_content = "난 저 집사가 의도적으로 입구를 열고 우리가 들어오게 만든 것 같아.",
  ui_story_5014_50140902_74_dialog_content = "우릴 여기 가두기 위해서 말이야.",
  ui_story_5014_50140902_75_dialog_content = "전 그렇게 생각하지 않아요...",
  ui_story_5014_50140902_76_dialog_content = "저 집사는 자매들을 지키려고 하고 있어요.\n자매가 외부인과 접촉하는 건 원하지 않을 거예요.",
  ui_story_5014_50140902_77_dialog_content = "「집사」? 「자매」? 무슨 소리야?",
  ui_story_5014_50140902_78_dialog_content = "여긴 고대인들이 전쟁과 재난을 피하기 위해 만든 지하도시예요.",
  ui_story_5014_50140902_79_dialog_content = "근데 일루미나의 지하성이랑은 전혀 다르잖아.",
  ui_story_5014_50140902_80_dialog_content = "맞아요. 일루미나의 지하성에는 많은 군사 시설이 있죠.",
  ui_story_5014_50140902_81_dialog_content = "하지만 여긴 자동화된 생산 시설과 고대인들의 치안 유지를 보조하는 로봇밖에 없어요.",
  ui_story_5014_50140902_82_dialog_content = "완전한 민간 거주 도시인 거예요.",
  ui_story_5014_50140902_83_dialog_content = "집사는 이 지하도시의 인공지능 시스템을 관리해요.",
  ui_story_5014_50140902_84_dialog_content = "이 도시의 운영과 고대인들의 안전을 책임지고 있어요.",
  ui_story_5014_50140902_85_dialog_content = "그렇게나 잘 알고 있는 거야?",
  ui_story_5014_50140902_86_dialog_content = "우리 일루미나의 탐험가... 시모스 씨도 한때 이곳에 있었거든요.",
  ui_story_5014_50140902_87_dialog_content = "시모스 씨와 그의 아내는 계속 이곳을 연구했고, 많은 정보를 남겨 주었어요.",
  ui_story_5014_50140902_88_dialog_content = "출구에 대한 정보도 있어?",
  ui_story_5014_50140902_89_dialog_content = "나가는 방법은 집사가 알고 있어요.\n하지만 집사는 우릴 내보내면 이곳이 발각될 위험이 커진다고 생각해요.",
  ui_story_5014_50140902_90_dialog_content = "그래서... 그는 아무도 나가지 못하게 하는 거예요.",
  ui_story_5014_50140902_91_dialog_content = "그리고 방금 말했던 「자매」는 바로 시모스 씨 부부의 자녀예요.\n두 사람은 계속 여기에서 살아왔어요.",
  ui_story_5014_50140902_92_dialog_content = "시모스 씨는 대량의 자료를 거처에 보관하고 있어요.\n저흰 이제 가서 그 자료를...",
  ui_story_5014_50140902_93_dialog_content = "그럼 너흰 출구에 대한 정보를 찾으러 가...\n우린 전리품을 찾으러 갈게!",
  ui_story_5014_50140902_94_dialog_content = "루비 언니?",
  ui_story_5014_50140902_95_dialog_content = "어쨌거나 당분간은 못 나간다는 얘기잖아.\n그럼 출구를 찾는 건 저쪽한테 맡기면 되지.",
  ui_story_5014_50140902_96_dialog_content = "찾으면 우리한테도 좀 알려줘.",
  ui_story_5014_50140902_97_dialog_content = "잠깐만, 여긴 어딜 가나 암귀랑 로봇이 잔뜩 있어.\n단독 행동은 위험해.",
  ui_story_5014_50140902_98_dialog_content = "뭐, 괜찮아. 무슨 일 있으면 부를게.",
  ui_story_5014_50140902_99_dialog_content = "시오반 씨, 그럼 번호 좀 줄래~?",
  ui_story_5014_50140902_100_dialog_content = "당신들 통신기는 자체 제작한 건가요? 좀 보여주시겠어요?",
  ui_story_5014_50140902_101_dialog_content = "응, 여기.",
  ui_story_5014_50140902_102_dialog_content = "통신기는 몇 개 있죠?",
  ui_story_5014_50140902_103_dialog_content = "두 개, 근데 왜?",
  ui_story_5014_50140902_104_dialog_content = "이 도시 안에서 그 두 기기 간에 통신이 가능한가요?",
  ui_story_5014_50140902_105_dialog_content = "그건 되는데, 바깥과는 통신이 안 돼...",
  ui_story_5014_50140902_106_dialog_content = "그거면 됐어요. 연락용으로 한 대는 저희한테 빌려주세요.",
  ui_story_5014_50140902_107_dialog_content = "좋아, 우리도 마침 그럴 생각이었어!",
  ui_story_5014_50140902_108_dialog_content = "시오반 씨, 왜 말리지 않는 거야?",
  ui_story_5014_50140902_109_dialog_content = "유적에서 보물을 찾는 일은 저 두 사람이 당신보다 더 잘 알고 있을 거예요.",
  ui_story_5014_50140902_110_dialog_content = "레디젤 렌치의 기술은 거칠지만... 때로는 많은 도움이 돼요.",
  ui_story_5014_50140902_111_dialog_content = "무슨 뜻이야?",
  ui_story_5014_50140902_112_dialog_content = "유적에서 물건을 구해다 파는 것도 레디젤 렌치의 주 수입원이거든.\n유적 탐험 쪽엔 노하우가 있으니까 걱정할 필요 없어.",
  ui_story_5014_50140902_113_dialog_content = "내가 괜한 걱정을 한 모양이네... 다들 탐험 전문가였구나.",
  ui_story_5014_50141001_1_dialog_content = "좌표가 가리키는 방향은... 이 거주 구역 안이에요.",
  ui_story_5014_50141001_2_dialog_content = "시모스 씨의 방에는 그가 남긴 연구 자료가 있어요.\n거기 출구에 대한 정보도 있을지도 몰라요.",
  ui_story_5014_50141001_3_dialog_content = "그럼 우린...",
  ui_story_5014_50141001_4_dialog_content = "크르르르...",
  ui_story_5014_50141001_5_dialog_content = "암귀들이 한곳에 모여 있어. 조심해서 움직이자.",
  ui_story_5014_50141001_6_dialog_content = "어디 모여 있죠?",
  ui_story_5014_50141001_7_dialog_content = "저쪽이야. 아까 그 로봇 제조 공장 쪽에 있어.",
  ui_story_5014_50141001_8_dialog_content = "이런... 두 자매도 아직 그 근처에 있을 거예요!",
  ui_story_5014_50141001_9_dialog_content = "당신 설마...",
  ui_story_5014_50141001_10_dialog_content = "가서 도와야죠.",
  ui_story_5014_50141001_11_dialog_content = "그럴 순 없어... 사악한 기계의 마수에서 이제 겨우 벗어났잖아.",
  ui_story_5014_50141001_12_dialog_content = "또 저 수렁 속으로 발을 들일 순 없어.",
  ui_story_5014_50141001_13_dialog_content = "가자. 시오반 씨와 같이 돌아가자.",
  ui_story_5014_50141001_14_dialog_content = "회장?",
  ui_story_5014_50141001_15_dialog_content = "시오반 씨, 암귀들의 목적이 그 자매라고 생각하는 거야?",
  ui_story_5014_50141001_16_dialog_content = "네, 시모스 씨가 남긴 음성 데이터에서도 말했어요.",
  ui_story_5014_50141001_17_dialog_content = "그들 가족은 줄곧 암귀의 위협을 받아왔고, 집사가 그들을 지켜주었다고 말이에요.",
  ui_story_5014_50141001_18_dialog_content = "하지만 우린 방금 많은 로봇을 파괴해 버렸어요. 그러니까...",
  ui_story_5014_50141001_19_dialog_content = "저들은 지금 암귀의 공격에 맞설 방법이 없겠지.",
  ui_story_5014_50141001_20_dialog_content = "<color=#e8d9bb>물러... 서십시오. 물러...</color>",
  ui_story_5014_50141001_21_dialog_content = "캬아악!",
  ui_story_5014_50141001_22_dialog_content = "<color=#e8d9bb>어서, 안전한 곳으로... 몸을 숨기십시오.</color>",
  ui_story_5014_50141001_23_dialog_content = "그레텔, 빨리!",
  ui_story_5014_50141001_24_dialog_content = "하지만 집사가... 겨우 새로 만든 로봇인데...",
  ui_story_5014_50141001_25_dialog_content = "<color=#e8d9bb>신경 쓰지 마십시오... 저희가 엄호하겠습니다...</color>",
  ui_story_5014_50141001_26_dialog_content = "이쪽으로 와! 어서!",
  ui_story_5014_50141001_27_dialog_content = "감응했어!",
  ui_story_5014_50141001_28_dialog_content = "로봇이 지금 암귀와 싸우고 있고, 자매는 저쪽으로 도망쳤어.",
  ui_story_5014_50141001_29_dialog_content = "암귀들이 그 뒤를 쫓고 있어.",
  ui_story_5014_50141001_30_dialog_content = "플로리나, PlayerName, 여러분은 암귀를 최대한 막아 주세요.",
  ui_story_5014_50141001_31_dialog_content = "저는 두 사람을 찾으러 갈게요.",
  ui_story_5014_50141002_1_dialog_content = "도망친 거 아니었어? 왜 돌아온 건데...?",
  ui_story_5014_50141002_2_dialog_content = "시오반 씨.",
  ui_story_5014_50141002_3_dialog_content = "PlayerName에게 들었어요. 당신들이 암귀에 쫓기고 있다고요.",
  ui_story_5014_50141002_4_dialog_content = "그래서 도와주러 왔어요.",
  ui_story_5014_50141002_5_dialog_content = "당신들을 그냥 둘 순 없으니까요...",
  ui_story_5014_50141002_6_dialog_content = "누가 도와달래?!",
  ui_story_5014_50141002_7_dialog_content = "집사가 곧 암귀들을 쓰러트려 줄 거라고!",
  ui_story_5014_50141002_8_dialog_content = "<color=#e8d9bb>걱정... 하지 마십시오... 곧, 해결됩니다.</color>",
  ui_story_5014_50141002_9_dialog_content = "계속되는 지진에 암귀까지, 버티는 것도 힘들겠죠...",
  ui_story_5014_50141002_10_dialog_content = "지진이 발생하면 신호 전달이 방해돼요.\n집사는 지금 로봇과 시설을 겨우 제어하고 있을 뿐이에요.",
  ui_story_5014_50141002_11_dialog_content = "그렇죠? 집사.",
  ui_story_5014_50141002_12_dialog_content = "<color=#e8d9bb>현재... 복구 중입니다. 걱정하지, 마십시오.</color>",
  ui_story_5014_50141002_13_dialog_content = "출구가 어디인지 알려주세요.",
  ui_story_5014_50141002_14_dialog_content = "일루미나의 과학자들한테 당신을 고쳐달라고 할 수 있어요.\n시모스 씨가 이 도시를 복원한 것처럼요.",
  ui_story_5014_50141002_15_dialog_content = "당신의 최우선 임무는 이 도시의 안전을 지키는 거 아닌가요?",
  ui_story_5014_50141002_16_dialog_content = "우리 일루미나는 결코 이곳을 파괴하지 않아요.",
  ui_story_5014_50141002_17_dialog_content = "당신과 함께 이 도시를 복원할 거예요.\n지진으로 파괴된 시설을 고쳐줄 거라고요.",
  ui_story_5014_50141002_18_dialog_content = "<color=#e8d9bb>저희는... 스스로 복구할 수 있습니다.</color>",
  ui_story_5014_50141002_19_dialog_content = "<color=#e8d9bb>도시의, 완전성과, 안전을... 지키는 것이... 제 책무입니다.</color>",
  ui_story_5014_50141002_20_dialog_content = "<color=#e8d9bb>여러분을... 이곳에서, 내보낼 순 없습니다.</color>",
  ui_story_5014_50141002_21_dialog_content = "<color=#e8d9bb>업데이트를 진행하여... 고장과... 암귀 문제를... 해결하겠습니다.</color>",
  ui_story_5014_50141002_22_dialog_content = "암귀... 맞아요. 시모스 씨는 암귀에 대해서도 말했었죠.",
  ui_story_5014_50141002_23_dialog_content = "이 암귀들은 대체 어디서 온 거죠?",
  ui_story_5014_50141002_24_dialog_content = "<color=#e8d9bb>권한이... 부족합니다.</color>",
  ui_story_5014_50141002_25_dialog_content = "시오반 씨, 암귀가 점점 늘어나고, 게다가 더 강해지고 있어...\n이대로면 얼마 못 버텨.",
  ui_story_5014_50141002_26_dialog_content = "암귀들이 점점 더 강해지는 게 느껴져.",
  ui_story_5014_50141002_27_dialog_content = "집사, 대답해 주세요. 이 암귀들은 어디서 온 거죠?",
  ui_story_5014_50141002_28_dialog_content = "당신이 만들어 낸 건 아닌가요?",
  ui_story_5014_50141002_29_dialog_content = "<color=#e8d9bb>제가... 만든 것이, 아닙니다.</color>",
  ui_story_5014_50141002_30_dialog_content = "그럼 누가 만든 거죠?",
  ui_story_5014_50141002_31_dialog_content = "<color=#e8d9bb>당신은... 권한이, 부족합니다.</color>",
  ui_story_5014_50141002_32_dialog_content = "캬아악──!",
  ui_story_5014_50141002_33_dialog_content = "안 돼, 더는 못 버텨! 어서 도망쳐야 해!",
  ui_story_5014_50141002_34_dialog_content = "발렌시아, 그레텔, 너희도 같이 가자!",
  ui_story_5014_50141002_35_dialog_content = "싫어!",
  ui_story_5014_50141002_36_dialog_content = "<color=#e8d9bb>후퇴...하십시오.</color>",
  ui_story_5014_50141002_37_dialog_content = "<color=#e8d9bb>가용 전투력이 부족합니다... 두 분, 어서 도망치십시오.</color>",
  ui_story_5014_50141002_38_dialog_content = "집사... 네가 해결할 수 있다고 했잖아... 분명히 네가...",
  ui_story_5014_50141002_39_dialog_content = "<color=#e8d9bb>암귀가, 너무 많습니다... 여러분, 어서 도망치십시오.</color>",
  ui_story_5014_50141002_40_dialog_content = "크오! 크오오──!",
  ui_story_5014_50141002_41_dialog_content = "그레텔, 안전한 곳으로 가서 숨어. 여기는 나랑 집사가...",
  ui_story_5014_50141002_42_dialog_content = "아니... 싫어... 더는 숨기 싫어...",
  ui_story_5014_50141002_43_dialog_content = "암귀가 이렇게 많으면... 집사가 죽을 거야... 그리고 언니도...",
  ui_story_5014_50141002_44_dialog_content = "아빠랑 엄마처럼...",
  ui_story_5014_50141002_45_dialog_content = "죽게 놔둘 수 없어... 절대로...",
  ui_story_5014_50141002_46_dialog_content = "그레텔? 진정해...",
  ui_story_5014_50141002_47_dialog_content = "싫다고!",
  ui_story_5014_50141002_48_dialog_content = "<color=#e8d9bb>콰쾅──!</color>",
  ui_story_5014_50141002_49_dialog_content = "<color=#e8d9bb>화르르륵...</color>",
  ui_story_5014_50141002_50_dialog_content = "으윽... 무슨 일이야?",
  ui_story_5014_50141002_51_dialog_content = "그레텔의 몸에서 갑자기 강력한 루미나가 폭발했어.",
  ui_story_5014_50141002_52_dialog_content = "암귀가... 전부 사라졌어.",
  ui_story_5014_50141002_53_dialog_content = "그레텔, 정신 차려! 언니 놀라게 만들지 말고! 그레텔──!",
  ui_story_5014_50141002_54_dialog_content = "으으... 언...니... 난 괜찮아...",
  ui_story_5014_50141002_55_dialog_content = "아... 다행이야... 정말 다행이야...",
  ui_story_5014_50141002_56_dialog_content = "언니가 얼른 검사하고 치료해줄게. 조금만 더 참아...",
  ui_story_5014_50141002_57_dialog_content = "집사, 얼른 도와줘!",
  ui_story_5014_50141002_58_dialog_content = "<color=#e8d9bb>긴급, 치료 시스템을... 가동했습니다. 저를, 따라 오십시오.</color>",
  ui_story_5014_50141002_59_dialog_content = "발렌시아, 우리도 갈게요...",
  ui_story_5014_50141002_60_dialog_content = "오지 마!",
  ui_story_5014_50141002_61_dialog_content = "다들 여기 있어. 아무 데도 가지 마.",
  ui_story_5014_50141002_62_dialog_content = "발렌시아, 우린 그냥 치료를 도와주고 싶어서...",
  ui_story_5014_50141002_63_dialog_content = "필요 없어!",
  ui_story_5014_50141002_64_dialog_content = "동생이... 원하지 않으니까.",
  ui_story_5014_50141101_1_dialog_content = "...아까 그거, 정말 그레텔이 한 거야?",
  ui_story_5014_50141101_2_dialog_content = "네, 아마 감정이 격해져서 루미나가 폭발한 거겠죠.",
  ui_story_5014_50141101_3_dialog_content = "그렇게 강한 힘을 가지고 있었을 줄은 몰랐어.",
  ui_story_5014_50141101_4_dialog_content = "회장, 뭔가 불길한 예감이 들어...",
  ui_story_5014_50141101_5_dialog_content = "불안한 건 나도 알아.",
  ui_story_5014_50141101_6_dialog_content = "지금 상황은 전부 우리 예상을 벗어났어.\n아니지, 통제를 벗어났다고 해야겠지.",
  ui_story_5014_50141101_7_dialog_content = "어서 출구를 찾아서 헤이디 선배한테 연락해야 돼.",
  ui_story_5014_50141101_8_dialog_content = "당신들의 보고가 자매의 안전을 위협하진 않았으면 좋겠네요...",
  ui_story_5014_50141101_9_dialog_content = "그럴 일은 없어... 둘은 백야성 사람이기도 하니까.",
  ui_story_5014_50141101_10_dialog_content = "발렌시아는 여기서 움직이지 말라고 했는데, 이제 어떡하지?",
  ui_story_5014_50141101_11_dialog_content = "역시 시모스 씨의 방을 찾으러 가는 게 좋겠어요.",
  ui_story_5014_50141101_12_dialog_content = "저 집사와 이야기하고 나서 더 확신이 생겼어요.\n시모스 씨가 남긴 자료를 어서 찾아야 해요.",
  ui_story_5014_50141101_13_dialog_content = "그 방 좌표는 기억하고 있어. 내가 앞장설게.",
  ui_story_5014_50141101_14_dialog_content = "<color=#e8d9bb>삑── 삐익──</color>",
  ui_story_5014_50141101_15_dialog_content = "무슨 소리야?",
  ui_story_5014_50141101_16_dialog_content = "루비 쪽에서 메시지를 보냈네요...",
  ui_story_5014_50141101_17_dialog_content = "어이──! 내 말 들려?",
  ui_story_5014_50141101_18_dialog_content = "빨리! 도와주러! 와!",
  ui_story_5014_50141101_19_dialog_content = "안 그러면 루즈가 나 때문에 화병 나게 생겼으니까!",
  ui_story_5014_50141101_20_dialog_content = "으윽... 고막 찢어지는 줄 알았네!",
  ui_story_5014_50141101_21_dialog_content = "역시 위험해진 모양이네... 구하러 갈 거야?",
  ui_story_5014_50141101_22_dialog_content = "아무리 레디젤 렌치 멤버라지만, 그렇게 냉정하게 대할 필요는 없잖아요?",
  ui_story_5014_50141101_23_dialog_content = "도울 거면 빨리 가자고. 우물쭈물할 시간 없으니까.",
  ui_story_5014_50141101_24_dialog_content = "두 사람이 준 좌표도 마침 목적지 근처예요.",
  ui_story_5014_50141101_25_dialog_content = "아마 로봇이나 암귀가 거기 있는 모양이네요.",
  ui_story_5014_50141101_26_dialog_content = "거기 시모스가 남긴 자료가 있어서 그런 건가?",
  ui_story_5014_50141101_27_dialog_content = "맞아요. 아마 집사는 우리가 그 자료를 원한다는 걸 알아챘을 거예요. 서두르죠.",
  ui_story_5014_50141101_28_dialog_content = "좋아. 우리가 앞장설게.",
  ui_story_5014_50141101_29_dialog_content = "에리카, 속도도 힘도 최대로 높여. 신속히 달려가서 장애물을 제거하는 거야!",
  ui_story_5014_50141101_30_dialog_content = "알겠어, 회장.",
  ui_story_5014_50141101_31_dialog_content = "<color=#e8d9bb>퍼엉! 쾅!</color>",
  ui_story_5014_50141101_32_dialog_content = "루비 언니, 다들 와 줬어!",
  ui_story_5014_50141101_33_dialog_content = "루비, 루즈! 괜찮아?",
  ui_story_5014_50141101_34_dialog_content = "끼긱── 끼익── 끼긱── 끼익──",
  ui_story_5014_50141101_35_dialog_content = "헤에~ 안 오는 줄 알았잖아~",
  ui_story_5014_50141101_36_dialog_content = "무슨 일이죠? 로봇에게 포위당했던 건가요? 로봇이 뭐라고 했죠?",
  ui_story_5014_50141101_37_dialog_content = "몰라. 난 아무 짓도 안 했어.",
  ui_story_5014_50141101_38_dialog_content = "경고, 기물을 제자리에 가져다 두십시오!\n경고, 기물을 제자리에 가져다 두십시오!",
  ui_story_5014_50141101_39_dialog_content = "거 봐... 루비 언니.\n눈앞에서 대놓고 물건을 가져가면 안 된다고 했잖아!",
  ui_story_5014_50141101_40_dialog_content = "...너네 뭘 훔친 거야?",
  ui_story_5014_50141101_41_dialog_content = "아아, 귀찮게시리. 이건 다 유물이라고, 유물!\n아무도 안 쓰는 거라고!",
  ui_story_5014_50141101_42_dialog_content = "이게 이 쇳덩어리들이랑 무슨 상관인데?!",
  ui_story_5014_50141101_43_dialog_content = "체포 프로그램, 실행!",
  ui_story_5014_50141101_44_dialog_content = "캬아악!",
  ui_story_5014_50141101_45_dialog_content = "또 암귀한테 포위됐어!",
  ui_story_5014_50141101_46_dialog_content = "사방에 적이 있어요. 조심해요...",
  ui_story_5014_50141102_1_dialog_content = "하나, 둘!",
  ui_story_5014_50141102_2_dialog_content = "끼... 끼긱...",
  ui_story_5014_50141102_3_dialog_content = "셋, 넷...",
  ui_story_5014_50141102_4_dialog_content = "루비, 싸움에만 몰두하면 안 돼요. 적은 계속 늘어날 뿐이에요.",
  ui_story_5014_50141102_5_dialog_content = "지금 더 중요한 건 시모스 씨가 남긴 자료를 손에 넣는 거예요.",
  ui_story_5014_50141102_6_dialog_content = "아까 말했던 그 시모스? 그 자료는 또 어디 있는데?",
  ui_story_5014_50141102_7_dialog_content = "거주 구역 쪽이에요... 저흴 따라오세요.\n플로리나가 앞서서 길을 뚫고 있어요.",
  ui_story_5014_50141102_8_dialog_content = "뭐? 그럼 우리가 뒤를 맡아줘야 한다는 거잖아?",
  ui_story_5014_50141102_9_dialog_content = "시오반 씨, 찾았어! 그 방은 앞쪽 건물 안에 있어.",
  ui_story_5014_50141102_10_dialog_content = "다행이네요. 잠깐이나마 저 로봇들을 따돌렸네요. 서두르죠.",
  ui_story_5014_50141102_11_dialog_content = "휴... 드디어... 도착했네.",
  ui_story_5014_50141102_12_dialog_content = "여기 건물은 튼튼한가?",
  ui_story_5014_50141102_13_dialog_content = "혹시 적이랑 또 싸우다가 무너지거나 하진 않겠지?",
  ui_story_5014_50141102_14_dialog_content = "가능성은 있어요. 여긴 평범한 거주 구역이고, 건물도 오래됐으니까요.",
  ui_story_5014_50141102_15_dialog_content = "그러니까 전투가 벌어져도 좀 참아가며 싸우세요.",
  ui_story_5014_50141102_16_dialog_content = "당신 전투 방식은 너무 난폭해요.",
  ui_story_5014_50141102_17_dialog_content = "물론이지, 시키는 대로 할게.\n지금부터 우린 한 「모험단」이니까.",
  ui_story_5014_50141102_18_dialog_content = "시모스 씨의 방에 도착했네요... 바로 여기예요.",
  ui_story_5014_50141102_19_dialog_content = "이 방...",
  ui_story_5014_50141102_20_dialog_content = "사람이 안 산 지 정말 오래된 것 같네.",
  ui_story_5014_50141102_21_dialog_content = "여기 방은 다 그런 거 아냐?",
  ui_story_5014_50141102_22_dialog_content = "잘 보세요... 옷이랑 서적에는 먼지 하나 없어요.",
  ui_story_5014_50141102_23_dialog_content = "두 자매가... 계속 여길 청소했던 거네요.",
  ui_story_5014_50141102_24_dialog_content = "우와, 옷장에 여자 옷이 잔뜩 있는데? 잘 팔릴까?",
  ui_story_5014_50141102_25_dialog_content = "루비 언니, 여기 물건을 건드리면 그 자매가 우릴 가만두지 않을걸!",
  ui_story_5014_50141102_26_dialog_content = "농담이야, 농담... 여기 물건들은 전부 시모스 부부의 유품이잖아?",
  ui_story_5014_50141102_27_dialog_content = "훔치더라도 너희 눈앞에서 대놓고 훔치진 않는다고.",
  ui_story_5014_50141102_28_dialog_content = "너 정말...",
  ui_story_5014_50141102_29_dialog_content = "방금 것도 농담이야. 유머 감각도 없기는.",
  ui_story_5014_50141102_30_dialog_content = "우린 직업윤리를 아는 모험가라고. 훔치면 안 될 물건은 안 훔쳐.",
  ui_story_5014_50141102_31_dialog_content = "하지만 시모스 씨의 자료는 꼭 확보해야 돼.",
  ui_story_5014_50141102_32_dialog_content = "여긴 자료가 너무 많아요... 바이스, 중요한 문서 분류부터 좀 도와주세요.",
  ui_story_5014_50141102_33_dialog_content = "네, 알겠어요!",
  ui_story_5014_50141102_34_dialog_content = "시오반 선생님, 이 일기는 전부 시모스 씨가 남긴 거겠죠?",
  ui_story_5014_50141102_35_dialog_content = "맞아요. 시모스 씨의 필체예요.",
  ui_story_5014_50141102_36_dialog_content = "알 수 있어요, 무척 익숙한 글씨니까요...",
  ui_story_5014_50141102_37_dialog_content = "시오반 선생님, 괜찮아요? 손이 떨리고 있는데요?",
  ui_story_5014_50141102_38_dialog_content = "네... 이런 귀중한 연구 자료를 다시 보게 될 줄은 정말 몰랐거든요...",
  ui_story_5014_50141102_39_dialog_content = "조금 감정이 격해져 버렸네요...\n괜찮아요. 작업에는 영향을 주지 않을 거예요.",
  ui_story_5014_50141102_40_dialog_content = "시오반 선생님, 안에 암호가 너무 많아요... 해독을 못 하겠어요.",
  ui_story_5014_50141102_41_dialog_content = "조급해할 거 없어요. 통용 키로 해독할 수 있는 부분만 먼저 해독하세요.\n다중 암호화 부분은 제가 맡을게요.",
  ui_story_5014_50141102_42_dialog_content = "네!",
  ui_story_5014_50141102_43_dialog_content = "카렌, 다들 정보를 얻는 데 시간이 좀 걸릴 거야.",
  ui_story_5014_50141102_44_dialog_content = "암귀나 로봇이 또 나타날 수도 있으니까...",
  ui_story_5014_50141102_45_dialog_content = "알고 있어. 우리가 입구를 지킬게. 그 누구도 접근하게 두지 않을 거야.",
  ui_story_5014_50141102_46_dialog_content = "회장, 이거 좀 봐.",
  ui_story_5014_50141102_47_dialog_content = "왜 그래? 에리카.",
  ui_story_5014_50141102_48_dialog_content = "여기도 일기가 잔뜩 있어.",
  ui_story_5014_50141102_49_dialog_content = "그리고 금박 인장도 남아 있어...",
  ui_story_5014_50141102_50_dialog_content = "이 암흑과 이단의 대지에도 빛의 신의 흔적이 존재했던 걸까?",
  ui_story_5014_50141102_51_dialog_content = "이 인장은 백야성의 양식이야...\n아마 그 클라우드라는 사람의 일기겠지.",
  ui_story_5014_50141102_52_dialog_content = "읽어볼 거야?",
  ui_story_5014_50141102_53_dialog_content = "음... 백야성의 귀족이 왜 여기 온 건지 궁금하긴 해.",
  ui_story_5014_50141102_54_dialog_content = "너네... 클라우드 씨 일기 보는 거야?",
  ui_story_5014_50141102_55_dialog_content = "크흠, 왜 갑자기 다가오고 그래...",
  ui_story_5014_50141102_56_dialog_content = "미안, 그냥 나도 좀 궁금해서.",
  ui_story_5014_50141102_57_dialog_content = "괜찮아, 어차피 회장도 못 읽는 것 같거든.",
  ui_story_5014_50141102_58_dialog_content = "어? 전부 휘갈겨 쓴 글씨뿐인데, 왜 이런 거야?",
  ui_story_5014_50141102_59_dialog_content = "이건 귀족들이 쓰는 비밀 서체야. 난 조금밖에 몰라.",
  ui_story_5014_50141102_60_dialog_content = "「비밀 서체」가 뭔데?",
  ui_story_5014_50141102_61_dialog_content = "글씨체를 바꿔서 문자를 암호화하는 거야.\n아는 사람들끼리만 읽을 수 있게 만드는 거지.",
  ui_story_5014_50141102_62_dialog_content = "이 부부... 암호를 되게 좋아했나 보네.",
  ui_story_5014_50141102_63_dialog_content = "아마 클라우드는 백야성에만 전하고 싶은 말이 있었던 거겠지...",
  ui_story_5014_50141102_64_dialog_content = "반대로 시모스는 일루미나에만 전하고 싶은 정보가 있었다는 건가?",
  ui_story_5014_50141102_65_dialog_content = "완전 백야성이랑 일루미나의 관계 그 자체잖아...\n서로 비밀주의라니...",
  ui_story_5014_50141102_66_dialog_content = "근데 두 사람 부부 아냐?",
  ui_story_5014_50141102_67_dialog_content = "세상에 그런 껄끄러운 부부가 어디 있어?",
  ui_story_5014_50141102_68_dialog_content = "거기 레디젤 렌치 사람들, 조용히 하세요...\n시모스 씨는 일기에서 아내에 대한 애정을 표현하고 있어요.",
  ui_story_5014_50141102_69_dialog_content = "두 사람은 서로를 존중했으니까, 서로의 비밀도 지켜준 거예요.",
  ui_story_5014_50141102_70_dialog_content = "시모스 부부는 서로가 암호화된 문서를 쓰고 있다는 걸 알고 있었어...\n클라우드의 일기에도 그렇게 적혀 있어.",
  ui_story_5014_50141102_71_dialog_content = "<color=#e8d9bb>끼이익── 끽.</color>",
  ui_story_5014_50141102_72_dialog_content = "뭔가 온 것 같은데?",
  ui_story_5014_50141102_73_dialog_content = "로봇인가요? 아니면 암귀?",
  ui_story_5014_50141102_74_dialog_content = "로봇이야... 근데...",
  ui_story_5014_50141102_75_dialog_content = "위험하진 않을 것 같은데?",
  ui_story_5014_50141102_76_dialog_content = "삐뽀──",
  ui_story_5014_50141102_77_dialog_content = "로봇 강아지... 시모스 씨 건가?",
  ui_story_5014_50141102_78_dialog_content = "공격성은 없어 보이네.",
  ui_story_5014_50141102_79_dialog_content = "위험하지 않다면 신경 쓰지 마... 정보가 더 급하니까.",
  ui_story_5014_50141102_80_dialog_content = "응, 그것도 그렇네.",
  ui_story_5014_50141102_81_dialog_content = "시오반 선생님, 이 일기 좀 보세요...",
  ui_story_5014_50141102_82_dialog_content = "삐, 삐, 삐, 삐뽀──",
  ui_story_5014_50141102_83_dialog_content = "이 녀석, 다른 데 가려는 것 같은데?",
  ui_story_5014_50141102_84_dialog_content = "루즈, 우린 마침 할 일도 없으니까... 얘랑 놀아도 되겠지?",
  ui_story_5014_50141102_85_dialog_content = "휴... 너무 심하게 굴지만 마.",
  ui_story_5014_50141102_86_dialog_content = "알았어, 물론이지~",
  ui_story_5014_50141102_87_dialog_content = "「이 강아지 재미있네...」",
  ui_story_5014_50141102_88_dialog_content = "<color=#e8d9bb>시모스의 방에... 오로리안이, 침입했습니다.</color>",
  ui_story_5014_50141102_89_dialog_content = "나도 봤어... 쳇.",
  ui_story_5014_50141102_90_dialog_content = "<color=#e8d9bb>지시를... 내려 주십시오.</color>",
  ui_story_5014_50141102_91_dialog_content = "움직일 수 있는 로봇은 모두 그쪽으로 보내. 서둘러!",
  ui_story_5014_50141102_92_dialog_content = "<color=#e8d9bb>이미, 집결을 시작했습니다... 거주 구역으로... 보내는 중입니다.</color>",
  ui_story_5014_50141102_93_dialog_content = "언니도... 갈 거야?",
  ui_story_5014_50141102_94_dialog_content = "응, 꼭 가서 그 사람들을 막아야 해...\n아빠랑 엄마 방을 엉망으로 만들 순 없어.",
  ui_story_5014_50141102_95_dialog_content = "나도 갈래!",
  ui_story_5014_50141102_96_dialog_content = "안 돼... 넌 일단 여기서 검사를 받고 있어. 알겠지?",
  ui_story_5014_50141102_97_dialog_content = "그 사람들을 처리하고 금방 돌아올게.",
  ui_story_5014_50141102_98_dialog_content = "근데 언니는 그 사람들 못 이겨.",
  ui_story_5014_50141102_99_dialog_content = "난 이 힘을 얻었으니까, 분명히...",
  ui_story_5014_50141102_100_dialog_content = "함부로 쓰면 안 돼. 몸이 상하지 않게 조심해야 해.",
  ui_story_5014_50141102_101_dialog_content = "언니는 그동안 싸우고 싶지 않았을 뿐이야.",
  ui_story_5014_50141102_102_dialog_content = "지금은... 뭘 해야 할지 알고 있으니까.",
  ui_story_5014_50141102_103_dialog_content = "나도 데리고 가 줘... 혼자 여기 있기 싫어.",
  ui_story_5014_50141102_104_dialog_content = "부탁이야, 언니... 혼자선 무서워.",
  ui_story_5014_50141102_105_dialog_content = "휴... 알겠어. 대신 절대 무리하지 마. 그리고 너무 흥분하지도 마.",
  ui_story_5014_50141102_106_dialog_content = "알겠어, 언니!",
  ui_story_5014_50141201_1_dialog_content = "로봇이 오고 있어! 다들 조심해!",
  ui_story_5014_50141201_2_dialog_content = "어라? 그럼 우리가 나설 차례인가?",
  ui_story_5014_50141201_3_dialog_content = "너희들은 안심하고 하던 일 해. 우리끼리 막을 테니까.",
  ui_story_5014_50141201_4_dialog_content = "아무래도... 막을 수 없을 것 같아.",
  ui_story_5014_50141201_5_dialog_content = "어째서?",
  ui_story_5014_50141201_6_dialog_content = "발렌시아랑 그레텔도 왔어...",
  ui_story_5014_50141201_7_dialog_content = "우린 두 사람이... 부모님 방에 들어가는 걸 막을 권리는 없어요.",
  ui_story_5014_50141201_8_dialog_content = "제가 발렌시아와 얘기하고 올게요.",
  ui_story_5014_50141201_9_dialog_content = "이 도둑들!",
  ui_story_5014_50141201_10_dialog_content = "발렌시아, 우선 제 얘기를 들어주세요...",
  ui_story_5014_50141201_11_dialog_content = "당장 아빠 엄마 방에서 나가!",
  ui_story_5014_50141201_12_dialog_content = "뭘 소리를 버럭 지르고 그래?",
  ui_story_5014_50141201_13_dialog_content = "우린 방 청소를 해주려던 거라고. 도둑질 같은 건 안 했어!",
  ui_story_5014_50141201_14_dialog_content = "그 자료는... 우리 부모님 거야! 너희가 멋대로 건드려도 되는 게 아니라고!",
  ui_story_5014_50141201_15_dialog_content = "발렌시아, 우린 시모스 씨의 음성 데이터를 받았기 때문에 이곳에 온 거예요.",
  ui_story_5014_50141201_16_dialog_content = "이건 당신 아버지의 뜻이에요...",
  ui_story_5014_50141201_17_dialog_content = "무슨 음성 데이터? 왜 난 모르는 건데?",
  ui_story_5014_50141201_18_dialog_content = "음성 데이터는 시모스 씨의 통신기에서 발송된 거야. 확인해 봐...",
  ui_story_5014_50141201_19_dialog_content = "<color=#e8d9bb>시모스의, 통신기 검사를... 요청합니다.</color>",
  ui_story_5014_50141201_20_dialog_content = "언니, 아빠 통신기를 집사한테 줘.",
  ui_story_5014_50141201_21_dialog_content = "...알았어.",
  ui_story_5014_50141201_22_dialog_content = "<color=#e8d9bb>검사 완료... 어떤, 메시지도... 발송되지 않았습니다.</color>",
  ui_story_5014_50141201_23_dialog_content = "그럴 리 없어! 우린 분명히 받았다고!",
  ui_story_5014_50141201_24_dialog_content = "집사는 거짓말하지 않아! 너희가 멋대로 지어낸 거겠지!",
  ui_story_5014_50141201_25_dialog_content = "아니에요, 제 말 들어 보세요.\n집사는 그걸 찾아내지 못했을 뿐이에요.",
  ui_story_5014_50141201_26_dialog_content = "시모스 씨는 그때 집사의 감시를 피하고 있었어요...",
  ui_story_5014_50141201_27_dialog_content = "아, 죄송해요... 그건 미처 생각을 못 했네요...",
  ui_story_5014_50141201_28_dialog_content = "괜찮아요.",
  ui_story_5014_50141201_29_dialog_content = "발렌시아, 여기 다른 증거들도 있어요. 이걸 보면...",
  ui_story_5014_50141201_30_dialog_content = "언니, 저 사람들 말 듣지 마! 또 거짓말하고 있잖아!",
  ui_story_5014_50141201_31_dialog_content = "갑자기 남의 집에 나타나서 로봇을 잔뜩 부수고,\n그것도 모자라서 집사까지 공격했어...",
  ui_story_5014_50141201_32_dialog_content = "이젠 여기까지 침입해서... 우릴 속이려고 하고 있어!",
  ui_story_5014_50141201_33_dialog_content = "끼긱── 끼익──",
  ui_story_5014_50141201_34_dialog_content = "로봇들이 또 나타났어.",
  ui_story_5014_50141201_35_dialog_content = "회, 회장...!",
  ui_story_5014_50141201_36_dialog_content = "에리카, 진정해... 일단은 공격하지 마.",
  ui_story_5014_50141201_37_dialog_content = "지금까지의 경험으로 보면, 이쪽이 먼저 공격하지 않는 이상,\n로봇들은 공격하지 않았어요...",
  ui_story_5014_50141201_38_dialog_content = "로봇이 공격하게 만드는 방법은 얼마든지 있어! 이 사기꾼, 좀도둑, 침입자!",
  ui_story_5014_50141201_39_dialog_content = "그레텔, 흥분하지 마...",
  ui_story_5014_50141201_40_dialog_content = "집사, 놈들을 모조리 없애버려!",
  ui_story_5014_50141201_41_dialog_content = "이 오로리안들은 모두 적이야!\n우리의 안전을 위협하고, 도시의 안전을 위협하는 자들이라고!",
  ui_story_5014_50141201_42_dialog_content = "<color=#e8d9bb>그레텔 님의, 명령을... 받았습니다.</color>",
  ui_story_5014_50141201_43_dialog_content = "끼기긱!",
  ui_story_5014_50141201_44_dialog_content = "이런... 로봇한테 살상 명령을 내렸어요!",
  ui_story_5014_50141201_45_dialog_content = "저 애가 여기 로봇들한테 명령도 내린단 말이야?!",
  ui_story_5014_50141201_46_dialog_content = "조심해! PlayerName!",
  ui_story_5014_50141201_47_dialog_content = "<color=#e8d9bb>퍼어엉!</color>",
  ui_story_5014_50141201_48_dialog_content = "체포하겠습니다... 체포하겠습니다...",
  ui_story_5014_50141201_49_dialog_content = "<color=#e8d9bb>경계 레벨, 향상... 지령, 갱신.</color>",
  ui_story_5014_50141201_50_dialog_content = "갱신... 침입자를 섬멸합니다!",
  ui_story_5014_50141201_51_dialog_content = "다들 전투 준...",
  ui_story_5014_50141201_52_dialog_content = "크아악──",
  ui_story_5014_50141201_53_dialog_content = "이런, 암귀도 잔뜩 몰려왔어!",
  ui_story_5014_50141201_54_dialog_content = "발렌시아! 그레텔! 뒤를 조심해요!",
  ui_story_5014_50141201_55_dialog_content = "무슨 소리야? 놈들이 우릴 공격할 줄 알았어?",
  ui_story_5014_50141201_56_dialog_content = "캬악, 크아악...!",
  ui_story_5014_50141201_57_dialog_content = "시오반 씨, 적은 모두 우리 쪽으로 오고 있어.",
  ui_story_5014_50141201_58_dialog_content = "저 암귀들... 마치 저 두 자매가 보이지 않는 것처럼 행동하고 있어!",
  ui_story_5014_50141201_59_dialog_content = "시오반 씨, 어째서 암귀의 행동이 변한 거지?",
  ui_story_5014_50141201_60_dialog_content = "그리고 저 로봇들... 암귀를 공격하던 거 아니었어?",
  ui_story_5014_50141201_61_dialog_content = "음... 이건...",
  ui_story_5014_50141201_62_dialog_content = "전에는 암귀가 우릴 공격하면 로봇이 분명히 암귀를 공격했어요...\n하지만 지금은 오히려 협력하고 있죠.",
  ui_story_5014_50141201_63_dialog_content = "로봇은 자매의 말을 듣고... 암귀로부터 저들을 지키고 있었어요.",
  ui_story_5014_50141201_64_dialog_content = "그레텔, 발렌시아, 설마...",
  ui_story_5014_50141201_65_dialog_content = "당신들, 설마 암귀도 조종할 수 있는 건가요?!",
  ui_story_5014_50141202_1_dialog_content = "바이스, 마지막 일격이야!",
  ui_story_5014_50141202_2_dialog_content = "내 창이 기계에 걸렸어!",
  ui_story_5014_50141202_3_dialog_content = "나한테 맡겨! 속사 감지!",
  ui_story_5014_50141202_4_dialog_content = "키이익...",
  ui_story_5014_50141202_5_dialog_content = "카렌, 무리하지 마. 상처가 아직 안 나았잖아...",
  ui_story_5014_50141202_6_dialog_content = "걱정하지 마. 이 정도 상처는 전투에 문제가 안 되니까.",
  ui_story_5014_50141202_7_dialog_content = "이쪽 로봇은 모두 처리했어.",
  ui_story_5014_50141202_8_dialog_content = "응. 그럼 시오반 선생님을 도우러 가자!",
  ui_story_5014_50141202_9_dialog_content = "캬아악!",
  ui_story_5014_50141202_10_dialog_content = "전부 물러서! 지저분한 것들!",
  ui_story_5014_50141202_11_dialog_content = "<color=#e8d9bb>콰르릉──!</color>",
  ui_story_5014_50141202_12_dialog_content = "또 지진인가?!",
  ui_story_5014_50141202_13_dialog_content = "회장... 나, 계시를 받았어... 이 사악한 로봇과 암귀는 이길 수 없어. 도망가자.",
  ui_story_5014_50141202_14_dialog_content = "끝없이 몰려와서 우리 힘을 소모시킬 거야.",
  ui_story_5014_50141202_15_dialog_content = "알겠어. 내가 다른 사람들한테 말할게...",
  ui_story_5014_50141202_16_dialog_content = "시오반 씨! 저 집사가 또 새로운 로봇을 만들었어. 이제 곧 이리로 올 거야.",
  ui_story_5014_50141202_17_dialog_content = "녀석들이 지진의 영향을 받는 동안 이곳을 떠나자.",
  ui_story_5014_50141202_18_dialog_content = "일단... 저 자매는 잊어버려. 출구를 찾는 게 먼저야.",
  ui_story_5014_50141202_19_dialog_content = "......",
  ui_story_5014_50141202_20_dialog_content = "우린 모두 당신 결정을 기다리고 있다고!",
  ui_story_5014_50141202_21_dialog_content = "바이스, 마지막에 본 그 일기장을 챙기세요...",
  ui_story_5014_50141202_22_dialog_content = "우선 이곳에서 벗어나죠!",
  ui_story_5014_50141202_23_dialog_content = "알겠어요!",
  ui_story_5014_50141202_24_dialog_content = "<color=#e8d9bb>지진이... 발생했습니다... 대피하십시오... 신호가...</color>",
  ui_story_5014_50141202_25_dialog_content = "삐걱... 삐걱...",
  ui_story_5014_50141202_26_dialog_content = "이런, 우리도 피해야 해... 그레텔!",
  ui_story_5014_50141202_27_dialog_content = "으윽... 언니... 녀석들이...",
  ui_story_5014_50141202_28_dialog_content = "그레텔, 왜 그래?",
  ui_story_5014_50141202_29_dialog_content = "으... 괜찮아... 그냥 갑자기... 머리가 아파...",
  ui_story_5014_50141202_30_dialog_content = "이리 와! 언니한테 보여줘!",
  ui_story_5014_50141202_31_dialog_content = "으윽... 정말 괜찮으니까... 언니...",
  ui_story_5014_50141202_32_dialog_content = "얼른 쫓아가... 녀석들이... 아빠 엄마 유품을 훔쳐 갔어.",
  ui_story_5014_50141202_33_dialog_content = "...알았어. 지진이 잠잠해지면 쫓아갈게.",
  ui_story_5014_50141202_34_dialog_content = "집사, 그레텔을 부탁할게.",
  ui_story_5014_50141202_35_dialog_content = "<color=#e8d9bb>제가... 잘, 돌봐드리겠습니다.</color>",
  ui_story_5014_50141301_1_dialog_content = "......",
  ui_story_5014_50141301_2_dialog_content = "야... 어이...",
  ui_story_5014_50141301_3_dialog_content = "PlayerName, 내가 불렀잖아. 적이 쫓아오고 있어?",
  ui_story_5014_50141301_4_dialog_content = "아, 미안. 방금 감응에 집중하느라.",
  ui_story_5014_50141301_5_dialog_content = "...쫓아오는 로봇이나 암귀는 없어.",
  ui_story_5014_50141301_6_dialog_content = "다행이네. 루즈 덕분이야...",
  ui_story_5014_50141301_7_dialog_content = "루즈, 네가 찾은 도주 경로, 정말 얍삽하네!",
  ui_story_5014_50141301_8_dialog_content = "루비 언니... 그거 칭찬으로는 안 들리는데...",
  ui_story_5014_50141301_9_dialog_content = "이젠 어떡하지?",
  ui_story_5014_50141301_10_dialog_content = "쉿, 시오반 선생님이랑 플로리나가 지금 정보를 해석하고 있어.",
  ui_story_5014_50141301_11_dialog_content = "미안, 그럼 우린 구석에 가서 얘기하자...",
  ui_story_5014_50141301_12_dialog_content = "시오반 씨, 무슨 문제라도 있나? 뭔가 힘들어 보이네...",
  ui_story_5014_50141301_13_dialog_content = "저 일기엔 아주 복잡한 정보들이 있거든.\n그래서 선생님도 시간이 좀 필요하신 것 같아.",
  ui_story_5014_50141301_14_dialog_content = "플로리나도 일기 해독을 도와주고 있는 거야?",
  ui_story_5014_50141301_15_dialog_content = "회장은 클라우드가 남긴 수수께끼의 문자를 해독하고 있어.",
  ui_story_5014_50141301_16_dialog_content = "아까 빛의 의지가 회장의 머리를 비췄고,\n계속 시도한 끝에 회장이 일기 속 수수께끼를 깨달을 수 있었어.",
  ui_story_5014_50141301_17_dialog_content = "...이해했어. 플로리나가 계속 시도해서 해독 방법을 찾았다는 거지?",
  ui_story_5014_50141301_18_dialog_content = "<color=#e8d9bb>쿠르릉...</color>",
  ui_story_5014_50141301_19_dialog_content = "PlayerName, 그레텔이 대체 어떻게 암귀를 조종할 수 있었던 걸까?",
  ui_story_5014_50141301_20_dialog_content = "로봇 제어라면 이해하겠는데... 시오반 선생님은 그 애가 암귀를 조종했다고 하셨어.",
  ui_story_5014_50141301_21_dialog_content = "아이테르의 감응 능력이랑 비슷한 거겠지.\n아이테르도 오로리안의 행동을 조종할 수 있잖아?",
  ui_story_5014_50141301_22_dialog_content = "아니야, 그런 건 못 해. 그건 과장된 소문이야.",
  ui_story_5014_50141301_23_dialog_content = "난 그저 감응 능력을 통해 제한된 정보를 전달하고 있을 뿐이야.",
  ui_story_5014_50141301_24_dialog_content = "그레텔 일은 시오반 씨한테 물어보는 게 좋겠어.\n해독이 끝날 때까지 기다리자.",
  ui_story_5014_50141301_25_dialog_content = "응, 그래.",
  ui_story_5014_50141301_26_dialog_content = "여러분, 새로운 정보를 알게 됐어요.",
  ui_story_5014_50141301_27_dialog_content = "그 시모스가 일기에 뭔가 더 남겼나요?",
  ui_story_5014_50141301_28_dialog_content = "조급해하지 마세요. 일기의 앞부분은 시모스 씨의 수기였어요.\n우리 일루미나에 대한 부탁도 적혀 있었죠.",
  ui_story_5014_50141301_29_dialog_content = "그리고 뒷부분에는 중요한 자료가 있었어요.\n이 도시 심층부의 시설에 대한 정보였어요.",
  ui_story_5014_50141301_30_dialog_content = "그 정보들을 여러분에게 공유할게요.",
  ui_story_5014_50141301_31_dialog_content = "일단은 앞부분부터 들려드리는 게 좋을 것 같네요...",
  ui_story_5014_50141301_32_dialog_content = "「나와 클라우드는 뜻하지 않게 이곳으로 떨어지고 말았다.」",
  ui_story_5014_50141301_33_dialog_content = "「나는 이 장소에 대한 연구 자료를 찾으려 했지만, 실마리를 찾지 못했다.」",
  ui_story_5014_50141301_34_dialog_content = "이곳에는 많은 로봇이 있고, 저마다 자기 직무를 가지고 있다.\n나는 그들의 가동 상황을 평가하는 중이다.",
  ui_story_5014_50141301_35_dialog_content = "다만 난처하게도, 이곳에서 자유롭게 행동하기 위해...\n나와 클라우드는 반드시 어떤 특정한 옷을 입어야만 했다.",
  ui_story_5014_50141301_36_dialog_content = "반드시 이 옷을 벗을 수 있는 방법을 찾을 것이다...\n도저히 익숙해질 수가 없다.",
  ui_story_5014_50141301_37_dialog_content = "나는 로봇 몇 개를 포획하여 개조를 시도했고,\n때로는 고의로 파괴해 보기도 했지만...",
  ui_story_5014_50141301_37X_dialog_content = "여전히 유의미한 데이터를 얻지 못했다.",
  ui_story_5014_50141301_38_dialog_content = "이곳의 로봇들은 우리에게 적의를 보인 적이 없다.\n나는 이곳에서 안심하고 살 수 있을 거라 생각했다.",
  ui_story_5014_50141301_39_dialog_content = "우릴 위협하는 것은... 오직 암귀뿐이다.\n이곳에는 야생동물처럼 많은 암귀가 있다.",
  ui_story_5014_50141301_40_dialog_content = "다행히 암귀가 우릴 공격하려 할 때면...\n로봇이 우릴 지켜준다.",
  ui_story_5014_50141301_41_dialog_content = "그들의 사명은 이곳의 주민을 지키는 것일지도 모른다.\n그리고 그 주민은 우리와 다를 바 없는 모습일 것이다.",
  ui_story_5014_50141301_42_dialog_content = "곧 「집사」라고 자칭하는 인공지능이 나타났고,\n그는 우리의 방문을 환영했다.",
  ui_story_5014_50141301_43_dialog_content = "또한 몇 가지 질문에도 답을 해 주었다.",
  ui_story_5014_50141301_44_dialog_content = "이 도시는 고대인들이 건설한 것이었다.\n그들은 재난이 지나갈 때까지 이곳에서 살면서 번영하려 했다고 한다.",
  ui_story_5014_50141301_45_dialog_content = "그것은 대체 어떤 재난이었을까.\n무엇이 그들로 하여금 지하 생활을 택할 수밖에 없게 만들었던 것일까.",
  ui_story_5014_50141301_46_dialog_content = "나는 집사에게 그 답을 듣고자 했지만,\n그는 매번 같은 대답밖에 하지 않았다.",
  ui_story_5014_50141301_47_dialog_content = "「권한이 부족」하다고.",
  ui_story_5014_50141301_48_dialog_content = "이 질문만 제외하면, 집사는 대답할 수 있는 질문은 모두 사실대로 답해주는 것 같았다.",
  ui_story_5014_50141301_49_dialog_content = "이는 나를 더 곤혹스럽게 만들었다. 집사는 대체 무엇을 위해 존재하는 것일까.\n만약 주민을 지키기 위해서라면...",
  ui_story_5014_50141301_50_dialog_content = "그 주민들은 대체 어디로 가버린 것일까.",
  ui_story_5014_50141301_51_dialog_content = "나는 답을 찾지 못했다.",
  ui_story_5014_50141301_52_dialog_content = "...우리는 나가지 못하게 되었다.",
  ui_story_5014_50141301_53_dialog_content = "집사는 밖으로 나가는 길을 모두 숨겼고, 나는 더 많은 정보를 얻을 수 없었다.",
  ui_story_5014_50141301_54_dialog_content = "하지만 클라우드는... 이곳에 머물고 싶다고 했다.",
  ui_story_5014_50141301_55_dialog_content = "이곳은 전쟁과 이단 심판을 피할 수 있는 곳이니까.",
  ui_story_5014_50141301_56_dialog_content = "그 후... 나와 클라우드 사이에 아이가 태어났고,\n집사가 교육 로봇을 선물해 주었다.",
  ui_story_5014_50141301_57_dialog_content = "나는 마침내 이 도시의 과거를 알아낼 기회가 왔다고 생각했다.",
  ui_story_5014_50141301_58_dialog_content = "하지만 교재의 내용은 이미 일부가 빠져 있었고,\n얻을 수 있는 유효한 정보는 한계가 있었다.",
  ui_story_5014_50141301_59_dialog_content = "가장 중요한 정보는 권한을 수정하는 방법이었다.",
  ui_story_5014_50141301_60_dialog_content = "나는 일부 권한을 수정하는 데 성공했지만... 아직 많이 부족하다.",
  ui_story_5014_50141301_61_dialog_content = "집사는 출구가 어디 있는지 알려주는 것을 거절했다.",
  ui_story_5014_50141301_62_dialog_content = "설마 우리는 영원히 이곳에 머물러야 하는 것일까.",
  ui_story_5014_50141301_63_dialog_content = "발렌시아는, 그레텔은 어떻게 해야 한단 말인가.",
  ui_story_5014_50141301_64_dialog_content = "이대로 영원히 나갈 수 없다면, 나는 아이들에게...\n내가 일루미나 사람이라는 것을 어떻게 설명해야 할까.",
  ui_story_5014_50141301_65_dialog_content = "바깥에는 더 큰 세상이 펼쳐져 있다는 것은 어떻게 설명할 수 있을까.",
  ui_story_5014_50141301_66_dialog_content = "매일 밤 클라우드가 말없이 나를 바라볼 때마다, 나는 되새긴다...",
  ui_story_5014_50141301_67_dialog_content = "저들을 위해서라도... 반드시 문제를 해결할 방법을 찾아야만 한다.",
  ui_story_5014_50141301_68_dialog_content = "집사의 의지를 거스르고 출구를 찾는 일은 매우 위험할지도 모른다.\n하지만 난 반드시 해내야만 한다.",
  ui_story_5014_50141301_69_dialog_content = "또한 더 많은 지식과 기술을 발렌시아와 그레텔에게 가르쳐 주어야 한다.",
  ui_story_5014_50141301_70_dialog_content = "아이들이 미래의 어느 날에는... 더 좋은 선택을 할 수 있길 바란다.",
  ui_story_5014_50141301_71_dialog_content = "그 미래는 아마 멀지 않을 것이다.\n일루미나는 반드시 모두를 이끌고 전쟁에서 승리할 것이다.",
  ui_story_5014_50141301_72_dialog_content = "어쩌면 우리가 출구를 찾아서 고향 땅을 다시 밟을지도 모른다.",
  ui_story_5014_50141301_72X_dialog_content = "아니면 그 전에 전우들이 우릴 찾아내 줄지도 모른다.",
  ui_story_5014_50141301_73_dialog_content = "최악의 상황이라면, 나와 클라우드가 예상치 못한 일을 당하는 것이겠지만.",
  ui_story_5014_50141301_74_dialog_content = "정말로 그때가 온다면... 이 자료들, 모든 자료들이 나의 유산이 될 것이다.",
  ui_story_5014_50141301_75_dialog_content = "이것을 나의 아내와 딸에게, 그리고 나의 전우에게 남길 것이다.",
  ui_story_5014_50141301_76_dialog_content = "부디 이곳을 찾아내 자료를 해독한 사람이 이 자료들을 올바르게 사용해 주길 바란다.",
  ui_story_5014_50141301_77_dialog_content = "...그리고 시모스 씨는 발렌시아에게 따로 유언장을 한 통 남겼어요.",
  ui_story_5014_50141301_78_dialog_content = "우리가 발렌시아한테 전해줘야 하는 거야?",
  ui_story_5014_50141301_79_dialog_content = "맞아요. 시모스 씨는 「일루미나의 전우」가\n자기 대신 그 유언장을 전해주길 원했어요.",
  ui_story_5014_50141301_80_dialog_content = "하지만 그 전에 조건이 있었어요.\n발렌시아가 바깥세상을 받아들일 준비를 마쳤다는 전제였죠.",
  ui_story_5014_50141301_81_dialog_content = "시모스 씨는 이 유언서를 자신이 고안해낸 암호화 방식으로 썼고,\n발렌시아만 그걸 해독할 수 있다고 했어요.",
  ui_story_5014_50141301_82_dialog_content = "일루미나에게는 자료를, 딸에게는 유언을 남겼군요...",
  ui_story_5014_50141301_83_dialog_content = "네. 그리고 마지막 단락은 아직 해독 중이지만,\n대체로 이런 내용이었어요.",
  ui_story_5014_50141301_84_dialog_content = "클라우드의 일기는 그것보단 훨씬 간단했어.",
  ui_story_5014_50141301_85_dialog_content = "당신도 해독이 끝났나요?",
  ui_story_5014_50141301_86_dialog_content = "응. 일부... 누설할 수 없는 기록만 빼고,\n마지막 비밀 서체는 전부 이해했어.",
  ui_story_5014_50141301_87_dialog_content = "무슨 내용이었죠?",
  ui_story_5014_50141301_88_dialog_content = "......",
  ui_story_5014_50141301_89_dialog_content = "「이 글자를 해독할 수 있는 건 오직 백야성 교회뿐이겠죠.」",
  ui_story_5014_50141301_90_dialog_content = "「부디 제 죄업에 종지부를 찍어 주세요. 제 딸들은 아무 관계도 없어요.」",
  ui_story_5014_50141301_91_dialog_content = "「만약 전쟁이 이미 끝났다면, 저 순수하고 때 묻지 않은 영혼들을 지켜주세요.」",
  ui_story_5014_50141301_92_dialog_content = "「만약 세계가 아직도 어둠에 잠겨 있다면,\n부디 이 낙원을 남겨두고 떠나 주세요.」",
  ui_story_5014_50141301_93_dialog_content = "「온 마음을 다해 간청합니다. 부디 제 딸들을 해치지 말아 주세요.」",
  ui_story_5014_50141301_94_dialog_content = "「발렌시아, 그레텔, 너희는 계속해서 앞으로 나아가렴.\n그것이 백야 아래이든, 아니면 부드러운 꿈속이든.」",
  ui_story_5014_50141301_95_dialog_content = "「엄마는 어디에 있든 항상 너희 곁에 있을 거란다...」",
  ui_story_5014_50141301_96_dialog_content = "「너희 손을 잡고, 늘 그랬듯이 너희와 함께할 거야...」",
  ui_story_5014_50141301_97_dialog_content = "「모든 미래는 전과 같이 아름다울 거야.」",
  ui_story_5014_50141301_98_dialog_content = "...느낄 수 있어...",
  ui_story_5014_50141301_99_dialog_content = "빛의 신조차도 이 깊은 사랑에 눈물을 흘리실 거야.",
  ui_story_5014_50141301_100_dialog_content = "시모스와 클라우드는... 딸들을 무척이나 사랑했던 거겠지.",
  ui_story_5014_50141301_101_dialog_content = "오래전, 클라우드는 「죄」를 지었어.\n그러다 전쟁의 위협을 받고 우연히 이곳에 왔어.",
  ui_story_5014_50141301_102_dialog_content = "시모스 씨는 탐색을 위해, 그리고 또 전쟁 때문에...\n마찬가지로 우연히 이곳에 왔어요.",
  ui_story_5014_50141301_103_dialog_content = "인공지능과 로봇이 저들을 지켜 주었군요.",
  ui_story_5014_50141301_104_dialog_content = "하지만 집사가 저들이 떠나지 못하게 했고...\n그래서 어쩔 수 없이 인공지능, 암귀와 함께 살아야만 했던 거야.",
  ui_story_5014_50141301_105_dialog_content = "......",
  ui_story_5014_50141301_106_dialog_content = "PlayerName, 괜찮아?",
  ui_story_5014_50141301_107_dialog_content = "괜찮아. 그냥 갑자기...",
  ui_story_5014_50141301_108_dialog_content = "두 사람은 이미 이 세상엔 없지만,\n두 사람의 사랑은 계속 남아있다는 생각이 들었어...",
  ui_story_5014_50141301_109_dialog_content = "일기 속이나... 이 도시 안에 말이야.",
  ui_story_5014_50141301_110_dialog_content = "응, 그렇네...",
  ui_story_5014_50141301_111_dialog_content = "크흠, 얘기 끊어서 미안한데, 사정은 이제 알았으니까...",
  ui_story_5014_50141301_112_dialog_content = "그 일기들, 이제 다시 갖다 놓아야 하지 않을까?",
  ui_story_5014_50141301_113_dialog_content = "그리고 <size=45>진심을 가득 담아서</size> 자매한테 사과하는 거야.",
  ui_story_5014_50141301_114_dialog_content = "화가 풀리면 우리 얘길 잘 들어줄지도 모르잖아?",
  ui_story_5014_50141301_115_dialog_content = "발렌시아라면 그럴지도 모르죠. 하지만 그레텔은...",
  ui_story_5014_50141301_116_dialog_content = "아~ 대체 시모스 부부는 왜 딸들한테 제대로 말을 안 한 건데?",
  ui_story_5014_50141301_117_dialog_content = "「누가 오면 이 일기장들을 보여줘라.」",
  ui_story_5014_50141301_118_dialog_content = "「해독한 사람이 있으면 따라가라」...라고 했으면 얼마나 좋아?",
  ui_story_5014_50141301_119_dialog_content = "전 시모스 씨의 마음도 이해할 수 있어요...\n아이들이 바깥세상에 경계심을 갖도록 하는 건 옳은 선택이에요.",
  ui_story_5014_50141301_120_dialog_content = "이곳에 어떤 사람이 찾아올지는 아무도 모르니까요.",
  ui_story_5014_50141301_121_dialog_content = "<color=#e8d9bb>쿠르릉...</color>",
  ui_story_5014_50141301_122_dialog_content = "왜 또 지진인 건데?! 지겹지도 않냐고!",
  ui_story_5014_50141301_123_dialog_content = "시오반 씨, 그럼 이젠 어디로...",
  ui_story_5014_50141301_124_dialog_content = "도시 심층부로 가죠...\n제어 시스템, 에너지 시스템 같은 핵심 시설은 모두 거기 있어요.",
  ui_story_5014_50141301_125_dialog_content = "지진의 위험을 감수하고 더 깊이 들어간다니...\n거기 출입구가 있기라도 한 거야?",
  ui_story_5014_50141301_126_dialog_content = "시모스 씨가 도시 심층부의 좌표를 남긴 데는 두 가지 이유가 있어요...",
  ui_story_5014_50141301_127_dialog_content = "하나는 제어 시스템 안에 출입구의 정보가 있을 가능성 때문이고...",
  ui_story_5014_50141301_128_dialog_content = "다른 하나는 지진이 계속 발생하는 이유가\n바로 이 도시의 불안정한 에너지 코어 탓이기 때문이에요.",
  ui_story_5014_50141301_129_dialog_content = "시모스 씨는 에너지 코어를 수리하려 했던 것 같아요.",
  ui_story_5014_50141301_130_dialog_content = "수리 방법에 대한 기록도 있어?",
  ui_story_5014_50141301_131_dialog_content = "기록엔 이론적인 방법밖에 없어요.\n이 일기는 시모스 씨가 심층부에 들어가기 전에 남긴 거니까요.",
  ui_story_5014_50141301_132_dialog_content = "도시 심층부로 향하는 입구의 좌표가 몇 개 적혀 있어요.\n하나씩 조사해 보기로 하죠...",
  ui_story_5014_50141301_133_dialog_content = "지금도 사용할 수 있는지, 집사가 막아버리진 않았는지 확인이 필요해요.",
  ui_story_5014_50141301_134_dialog_content = "<color=#e8d9bb>쿠르르릉! 우르르...</color>",
  ui_story_5014_50141301_135_dialog_content = "으윽, 이러다 설마 반도 못 가서 매장당하는 건 아니겠지...",
  ui_story_5014_50141301_136_dialog_content = "여기는 지하도시야. 심층부에 가든 말든 매장당할 수 있다고.",
  ui_story_5014_50141301_137_dialog_content = "그래도... 역시 저 하늘이 무너져 내리는 모습은 보고 싶지 않아.",
  ui_story_5014_50141301_138_dialog_content = "시오반 씨, 이 도시가 붕괴할까?",
  ui_story_5014_50141301_139_dialog_content = "그건 에너지 코어의 상태에 달려 있어요.\n하지만 제가 직접 확인해 보기 전까진 판단할 수 없겠네요.",
  ui_story_5014_50141301_140_dialog_content = "어쨌든 서둘러야 해요.",
  ui_story_5014_50141301_141_dialog_content = "우리도 가자. 도와줄게.",
  ui_story_5014_50141301_142_dialog_content = "그래. 어차피 갈 데도 없으니까.",
  ui_story_5014_50141301_143_dialog_content = "그럼 저와 PlayerName 일행은 발렌시아와 그레텔을 찾으러 갈게요.",
  ui_story_5014_50141301_144_dialog_content = "두 사람은 입구의 상황을 확인하고, 심층부로 향하는 경로를 찾아 주세요.",
  ui_story_5014_50141301_145_dialog_content = "나랑 에리카가 고대 과학 자료를 보고 없애버릴까 걱정되지 않아?",
  ui_story_5014_50141301_146_dialog_content = "당신이라면 그럴 수 있겠죠.\n그래도 고대 유물은 다음 기회가 있을 테니까요.",
  ui_story_5014_50141301_147_dialog_content = "하지만 전우의 자녀는 유일한 존재예요.",
  ui_story_5014_50141301_148_dialog_content = "역시 아직도 포기하지 않은 모양이네...",
  ui_story_5014_50141301_149_dialog_content = "설마 클라우드의 일기를 읽고도 저 아이들을 내버려 둘 생각인 건가요?",
  ui_story_5014_50141301_150_dialog_content = "물론 우리도 저들에게 무슨 일이 생기길 바라진 않아.\n저 둘은 백야성의 자녀이기도 하니까...",
  ui_story_5014_50141301_151_dialog_content = "그럼 두 자매는 당신한테 맡길 테니까, 꼭...",
  ui_story_5014_50141301_152_dialog_content = "이 위험한 곳을 떠나서 함께 돌아가자고 설득해 줘.",
  ui_story_5014_50141301_153_dialog_content = "일루미나든 백야성든 둘이 원하는 곳으로 가라고 말이야.",
  ui_story_5014_50141301_154_dialog_content = "네, 그럴 거예요.",
  ui_story_5014_50141301_155_dialog_content = "대신 나도 저 인공지능만 빼고... 나머지는 못 본 거로 해줄게.",
  ui_story_5014_50141301_156_dialog_content = "어떻게 당신이 더 빠를 거라 생각하죠?",
  ui_story_5014_50141301_157_dialog_content = "출입구만 찾으면 되는 일인데, 그 자매를 설득하는 것보다 어렵겠어?",
  ui_story_5014_50141301_158_dialog_content = "후훗... 심층부로 통하는 길은 무척 위험할 거예요. 조심하세요.",
  ui_story_5014_50141301_159_dialog_content = "걱정할 거 없어. 우리 실력을 얕보면 안 되지...\n그럼 이따가 봐.",
  ui_story_5014_50141301_160_dialog_content = "그래요. 나중에 봐요.",
  ui_story_5014_50141401_1_dialog_content = "후... 휴우...",
  ui_story_5014_50141401_2_dialog_content = "시, 시오반 씨... 조금만 천천히... 바이스... 나...",
  ui_story_5014_50141401_3_dialog_content = "업어줄까? PlayerName.",
  ui_story_5014_50141401_4_dialog_content = "아니, 괜찮아. 넌 계속 다친 채로 움직이고 있잖아...\n절대... 너희한테 짐이 될 순 없어... 열심히 따라갈게!",
  ui_story_5014_50141401_5_dialog_content = "곧 거주 구역이에요. 조금만 더 힘내요...",
  ui_story_5014_50141401_6_dialog_content = "잠깐만... 더는 달릴 필요가 없겠어.\n저쪽에서 먼저 쫓아왔으니까.",
  ui_story_5014_50141401_7_dialog_content = "게다가 로봇도 잔뜩 데리고 왔어...",
  ui_story_5014_50141401_8_dialog_content = "아무래도 애써 찾을 필요는 없었던 것 같네...",
  ui_story_5014_50141401_9_dialog_content = "발렌시아, 제 얘기 좀 들어보세요...",
  ui_story_5014_50141401_10_dialog_content = "닥쳐!",
  ui_story_5014_50141401_11_dialog_content = "아빠 방에 들어가서 또 유품을 훔칠 생각이지?!",
  ui_story_5014_50141401_12_dialog_content = "아니에요, 발렌시아...\n우린 시모스 씨의 일기를 읽고 이곳 상황을 어느 정도 이해했어요.",
  ui_story_5014_50141401_13_dialog_content = "시모스 씨는 계속해서 일루미나의 전우가 이곳을 찾아주길 원했고...\n계속해서 음성 데이터를 보냈어요.",
  ui_story_5014_50141401_14_dialog_content = "하지만 저흰 그걸 너무 늦게 받았던 거예요.\n그때 이미 당신은 우릴 오해하고 있었죠...",
  ui_story_5014_50141401_15_dialog_content = "그래서 지금과 같은 상황이 되어버린 거예요...",
  ui_story_5014_50141401_16_dialog_content = "쓸데없는 얘긴 집어치우고 아빠 일기나 돌려줘!",
  ui_story_5014_50141401_17_dialog_content = "흥분하지 말고 보세요... 일기는 흠집 하나 없이 온전해요.",
  ui_story_5014_50141401_18_dialog_content = "당신 아버지는 우리가 당신들을 데리고 이곳을 떠나길 원했어요.\n여긴 언제 붕괴해도 이상하지 않은 상황이에요...",
  ui_story_5014_50141401_19_dialog_content = "붕괴한다고...?",
  ui_story_5014_50141401_20_dialog_content = "맞아요, 시모스 씨는 일기장에 암호화된 자료들을 많이 남겨 두셨어요.",
  ui_story_5014_50141401_21_dialog_content = "그중에는 이 도시의 에너지 코어에 문제가 있는 것도 언급하고 있어요.",
  ui_story_5014_50141401_22_dialog_content = "그분은 줄곧 코어를 복구할 방법을 찾아왔고,\n여기서 나가는 길도 찾고 있었어요.",
  ui_story_5014_50141401_23_dialog_content = "그리고 당신에게 남긴 유언장도 있어요.\n이걸 읽으면 당신도 전부 이해할 수 있을 거예요...",
  ui_story_5014_50141401_24_dialog_content = "......",
  ui_story_5014_50141401_25_dialog_content = "발렌시아?",
  ui_story_5014_50141401_26_dialog_content = "아빠의 일기장도 들춰보고, 아빠가 나한테 남긴 유언장까지... 가져갔다고?",
  ui_story_5014_50141401_27_dialog_content = "오해하지 마세요. 그건 당신 아버지의 뜻이었어요.",
  ui_story_5014_50141401_28_dialog_content = "일단 가져간 것부터 전부 돌려줘.",
  ui_story_5014_50141401_29_dialog_content = "자, 받으세요.",
  ui_story_5014_50141401_30_dialog_content = "그리고 나한테서 떨어져.",
  ui_story_5014_50141401_31_dialog_content = "발렌시아, 우선 유언장부터 읽어 보세요. 당신 아버지는...",
  ui_story_5014_50141401_32_dialog_content = "시끄러워...",
  ui_story_5014_50141401_33_dialog_content = "시오반 씨, 일단... 좀 떨어져 있는 게 좋겠어.",
  ui_story_5014_50141401_34_dialog_content = "발렌시아, 표정이 좀 이상해... 지금 뭔가 격한 감정이 느껴져...",
  ui_story_5014_50141401_35_dialog_content = "너흰... 멋대로 남의 집에 쳐들어와서...",
  ui_story_5014_50141401_36_dialog_content = "아빠의 물건을 멋대로 가져가고... 계속 거짓말을 하더니...",
  ui_story_5014_50141401_37_dialog_content = "심지어 나조차 마음대로 읽을 수 없었던 것까지...",
  ui_story_5014_50141401_38_dialog_content = "발렌시아, 진정해.",
  ui_story_5014_50141401_39_dialog_content = "나조차 함부로 다루면 안 되는 자료였다고!",
  ui_story_5014_50141401_40_dialog_content = "<size=45>그건 아빠의 유품이었어!</size>",
  ui_story_5014_50141401_41_dialog_content = "제 얘기부터 좀 들어봐요...",
  ui_story_5014_50141401_42_dialog_content = "끼기긱!",
  ui_story_5014_50141402_1_dialog_content = "일단 로봇들부터 해결해야... 차분하게 얘길 할 수 있을 것 같아.",
  ui_story_5014_50141402_2_dialog_content = "이 「무기」들을 잃고 나면 조금은 냉정해질 수 있겠지.",
  ui_story_5014_50141402_3_dialog_content = "PlayerName. 지금 저 애 감정이 어떤 것 같아?",
  ui_story_5014_50141402_4_dialog_content = "적어도 공격을 더 하려고 들진 않아.",
  ui_story_5014_50141402_5_dialog_content = "...고작 이 로봇들만 부수면 내가 아무것도 못 할 줄 알았어?",
  ui_story_5014_50141402_6_dialog_content = "나한텐 아직...",
  ui_story_5014_50141402_7_dialog_content = "발렌시아, 너희 아버지는 정말로 너희가 여길 떠나길 원했어.",
  ui_story_5014_50141402_8_dialog_content = "여긴 고대인들이 만든 피난처야. 너희 아버지가 오래전에 이곳을 발견한 거고.",
  ui_story_5014_50141402_9_dialog_content = "여긴 발전된 인공지능과 생활을 돕는 여러 시설들이 있지만...",
  ui_story_5014_50141402_10_dialog_content = "마찬가지로 다른 문제도 많아.",
  ui_story_5014_50141402_11_dialog_content = "특히 지금... 계속 이렇게 지진이 발생한다면 도시가 붕괴될 수도 있어!",
  ui_story_5014_50141402_12_dialog_content = "발렌시아, 아마 당신은 아버지한테서 에너지 코어에 대한 지식을 배웠을 거예요.",
  ui_story_5014_50141402_13_dialog_content = "에너지 코어엔 아무 문제도 없다고...",
  ui_story_5014_50141402_14_dialog_content = "붕괴돼도 건물을 다시 지으면 되는 거잖아. 너희랑 무슨 상관이야!",
  ui_story_5014_50141402_15_dialog_content = "마지막으로 충고할 테니 잘 들어요! 먼저 유언장부터 읽으세요!",
  ui_story_5014_50141402_16_dialog_content = "시모스 씨는 자신이 만든 「암호화 방식」으로\n당신이 유언장을 해석할 수 있다고 했어요.",
  ui_story_5014_50141402_17_dialog_content = "그것까지 알고 있단 말이야?!",
  ui_story_5014_50141402_18_dialog_content = "이런... 또 이상한 방향으로 생각하기 시작한 것 같은데...",
  ui_story_5014_50141402_19_dialog_content = "아직 어린아이잖아요. 극단적인 생각으로 치닫기 쉬워요.",
  ui_story_5014_50141402_20_dialog_content = "그래도 전 믿어요. 당신 아버지가 이것도 가르쳐 준 적 있겠죠.\n눈앞에 위협이 닥쳤을 때일수록 더 냉정함이 필요하다고 말이에요.",
  ui_story_5014_50141402_21_dialog_content = "최대한 많은 정보를 모아 상황을 객관적으로 판단한다...\n그게 바로 우리 일루미나의 교육 이념이에요...",
  ui_story_5014_50141402_22_dialog_content = "전 당신을 처음 만났을 때부터 무척 친밀한 감정을 느꼈어요.",
  ui_story_5014_50141402_23_dialog_content = "당신은 강하고, 용감하고, 선량하죠.\n열정과 호기심, 지식욕도 있어요.",
  ui_story_5014_50141402_24_dialog_content = "모든 일루미나인이 그렇듯이... 당신도 일루미나의 아이니까요.",
  ui_story_5014_50141402_25_dialog_content = "......",
  ui_story_5014_50141402_26_dialog_content = "미안해요, 발렌시아. 우리가 예의에 어긋난 일을 한 건 맞아요.",
  ui_story_5014_50141402_27_dialog_content = "부디 제가 설명할 기회를 주세요. 다시 한번 절 믿어줬으면 해요.",
  ui_story_5014_50141402_28_dialog_content = "지금 이 도시는 위험에 처해 있어요.",
  ui_story_5014_50141402_29_dialog_content = "하지만 전 당신들을 이대로 내버려 둘 수 없어요.\n당신들은 시모스 씨의 자녀들이니까요.",
  ui_story_5014_50141402_30_dialog_content = "시모스 씨가 일루미나에 부탁한 소중한 아이들인걸요.",
  ui_story_5014_50141402_31_dialog_content = "...유언장을 읽을게, 지금 여기서.",
  ui_story_5014_50141402_32_dialog_content = "대신 내가 유언장을 읽는 동안 뭔가 한다면, 절대로...",
  ui_story_5014_50141402_33_dialog_content = "아무것도 하지 않아요. 당신의 안전을 위협하지도 않을 거예요.\n...저희를 믿으세요.",
  ui_story_5014_50141402_34_dialog_content = "언니, 절대 믿으면 안 돼!",
  ui_story_5014_50141402_35_dialog_content = "그레텔...",
  ui_story_5014_50141402_36_dialog_content = "저 여자는 녀석들이 우릴 막으려고 보낸 거야!",
  ui_story_5014_50141402_37_dialog_content = "다른 녀석들은 지금 심층부에 침입하고 있다고!",
  ui_story_5014_50141402_38_dialog_content = "여기가 마지막 좌표야...",
  ui_story_5014_50141402_39_dialog_content = "찾았어, 루비 언니. 플로리나, 정말 밑으로 통하는 길이 있었어.",
  ui_story_5014_50141402_40_dialog_content = "당신들 레디젤 렌치가 이렇게 솜씨가 좋을 줄은 몰랐네...",
  ui_story_5014_50141402_41_dialog_content = "어라? 우리 지금 대모험가의 인정을 받은 거야?",
  ui_story_5014_50141402_42_dialog_content = "이거 대단한 일이잖아?",
  ui_story_5014_50141402_43_dialog_content = "이 아래쪽 통로도 전의 통로들처럼 막혀 있진 않을까?",
  ui_story_5014_50141402_44_dialog_content = "걱정하지 마. 내 오랜 경험에 따르면 밑에 뭐가 있는지 정도는 바로 알 수 있어.",
  ui_story_5014_50141402_45_dialog_content = "그리고 여긴...",
  ui_story_5014_50141402_46_dialog_content = "에헤헤, 대성공~",
  ui_story_5014_50141402_47_dialog_content = "회장, 이 아래에서 지극히 사악한 과거의 기운이 전해져.\n그 기운은 지금 통제를 잃어가고 있어.",
  ui_story_5014_50141402_48_dialog_content = "내 마음속의 신앙이 아래로 내려가서 그걸 파괴하라고 호소하고 있어!",
  ui_story_5014_50141402_49_dialog_content = "알겠어, 에리카.",
  ui_story_5014_50141402_50_dialog_content = "도시의 에너지 코어와 그 제어 시스템은 이 아래에 있어.",
  ui_story_5014_50141402_51_dialog_content = "지하도시에서 벗어날 방법이 거기 있을지도 몰라.",
  ui_story_5014_50141402_52_dialog_content = "아래로 내려가고 나면 내 지시에 따라.\n충동적으로 움직이지 마.",
  ui_story_5014_50141402_53_dialog_content = "알겠어, 회장... 지시대로 할게.",
  ui_story_5014_50141402_54_dialog_content = "루비, 루즈, 너희도 마찬가지야. 멋대로 행동하면 안 돼.",
  ui_story_5014_50141402_55_dialog_content = "아래로 내려가면 내 말을 듣는 게 좋을 거야.",
  ui_story_5014_50141501_1_dialog_content = "겨우 발렌시아를 설득했는데, 이번엔 그레텔이냐고...\n이래서는 다시 처음부터 말해야 되잖아.",
  ui_story_5014_50141501_2_dialog_content = "문제를 빨리 해결하려고 두 팀으로 나누어 움직인 게...",
  ui_story_5014_50141501_3_dialog_content = "또 새로운 오해를 만들다니...",
  ui_story_5014_50141501_4_dialog_content = "게다가 그레텔이 어떻게 알고 있는 거지...",
  ui_story_5014_50141501_5_dialog_content = "바이스, 그런 말은 해선 안 돼요. 그레텔이 오해할 거예요.",
  ui_story_5014_50141501_6_dialog_content = "우리의 일거수일투족이 모두 감시당하는 것도... 이상할 건 없어요.",
  ui_story_5014_50141501_7_dialog_content = "그레텔은 처음부터 계속 우릴 적대시하고 있었어...\n이건 이미 오해라든가 그런 수준이 아니라고 생각해.",
  ui_story_5014_50141501_8_dialog_content = "저 애한테 있어서... 「바깥세상」은 미지와 공포가 가득한 곳인 거겠지.",
  ui_story_5014_50141501_9_dialog_content = "내 욕 그만해. 안 들릴 거라고 생각해?!",
  ui_story_5014_50141501_10_dialog_content = "난 귀가 좋다고!",
  ui_story_5014_50141501_11_dialog_content = "저기, 그러니까 말이지...",
  ui_story_5014_50141501_12_dialog_content = "너희 아버지는 일루미나 연방 사람이고, 우린 아버지의 전우야.",
  ui_story_5014_50141501_13_dialog_content = "너희 아빠랑 엄마는 우연히 여기 갇혔기 때문에 여기서 살 수밖에 없었어.",
  ui_story_5014_50141501_14_dialog_content = "두 사람은 너희가 평온하게 성장하길 원했어.\n그래서 너희들한테도 말하지 않은 것들이 있었던 거야.",
  ui_story_5014_50141501_15_dialog_content = "대신 일루미나 연방의 전우들에게 메시지를 남겼고,\n그 동료들이 너흴 여기서 데리고 나가 주길 원했어...",
  ui_story_5014_50141501_16_dialog_content = "그 일기들을 읽어 봐. 그리고 네 언니한테 물어봐도 돼. 네 언니는 알고 있으니까...",
  ui_story_5014_50141501_17_dialog_content = "언니는 너희한테 속은 거야! 난 다 안다고!",
  ui_story_5014_50141501_18_dialog_content = "너 정말... 왜 그렇게 생각이 극단적이야?!",
  ui_story_5014_50141501_19_dialog_content = "지금 나 욕한 거야?!",
  ui_story_5014_50141501_20_dialog_content = "그런 거 아니야. 그리고 방금 그건 욕도 아니고...",
  ui_story_5014_50141501_21_dialog_content = "이 도시는 지금 붕괴하고 있어. 에너지 코어에 문제가 있어서 모두가 똑같이 위험하다고!",
  ui_story_5014_50141501_22_dialog_content = "우리가 이러는 것도 다 너희를 위해서...",
  ui_story_5014_50141501_23_dialog_content = "말은 다 했어?",
  ui_story_5014_50141501_24_dialog_content = "너, 넌... 왜 뭐 하나 제대로 듣지를 않아?!",
  ui_story_5014_50141501_25_dialog_content = "내가 언니처럼 그렇게 쉽게 속을 줄 알았어?",
  ui_story_5014_50141501_26_dialog_content = "그레텔, 내가 한 말은 다 진짜야!",
  ui_story_5014_50141501_27_dialog_content = "집사, 언니 상태는?",
  ui_story_5014_50141501_28_dialog_content = "그레텔, 난 괜찮아... 걱정할 거 없어.",
  ui_story_5014_50141501_29_dialog_content = "<color=#e8d9bb>신체... 검사를 시작합니다... 피로, 정신적 자극을... 받은 것으로 추정.</color>",
  ui_story_5014_50141501_30_dialog_content = "<color=#e8d9bb>방금, 치열한... 전투가 있었습니다.</color>",
  ui_story_5014_50141501_31_dialog_content = "너희가 언니를 공격했어?!",
  ui_story_5014_50141501_32_dialog_content = "그건 어쩔 수 없었어...",
  ui_story_5014_50141501_33_dialog_content = "발렌시아가 먼저 우릴 공격했어.",
  ui_story_5014_50141501_34_dialog_content = "발렌시아는 무리해서 로봇을 제어해 싸웠기 때문에 지쳐 있는 거예요.",
  ui_story_5014_50141501_35_dialog_content = "못 믿으시면 집사에게 물어보세요.",
  ui_story_5014_50141501_36_dialog_content = "집사, 이 아이들은 지금까지 당신을 통하지 않으면 로봇을 지휘할 수 없었을 텐데요.",
  ui_story_5014_50141501_37_dialog_content = "왜 갑자기 직접 지휘할 수 있게 됐죠?",
  ui_story_5014_50141501_38_dialog_content = "<color=#e8d9bb>오로리안... 당신은, 권한이 부족합니다.</color>",
  ui_story_5014_50141501_39_dialog_content = "물어볼 필요도 없어. 집사는 너처럼 거짓말쟁이가 아니니까.",
  ui_story_5014_50141501_40_dialog_content = "<color=#e8d9bb>제, 정보는... 모두 진실입니다.</color>",
  ui_story_5014_50141501_41_dialog_content = "그레텔, 당신은 집사를 통해 이 도시의 시스템을 조종하고 있죠?",
  ui_story_5014_50141501_42_dialog_content = "도시의 상태를 다시 한번 점검해 본다면, 이곳이 얼마나 위험한지 알 수 있을 거예요.",
  ui_story_5014_50141501_43_dialog_content = "시스템만이 아냐. 난 이곳의 모든 걸 조종할 수 있다고...",
  ui_story_5014_50141501_44_dialog_content = "생각나게 해 줘서 고마워. 침입자, 사기꾼, 좀도둑!",
  ui_story_5014_50141501_45_dialog_content = "집사, 내 말대로 그 프로그램을 켜서 경계도를 더 높여.",
  ui_story_5014_50141501_46_dialog_content = "그레텔, 안 돼...",
  ui_story_5014_50141501_47_dialog_content = "<color=#e8d9bb>알겠습니다. 프로그램 클리어... 리셋, 경계도 강화를... 다시 실행합니다.</color>",
  ui_story_5014_50141501_48_dialog_content = "또 싸우는 거야?",
  ui_story_5014_50141501_49_dialog_content = "암귀도 몰려오기 시작했어. 저번이랑 똑같아...\n놈들은 우리만 노리고 있는 것 같아.",
  ui_story_5014_50141501_50_dialog_content = "그레텔은 대체 어떻게 암귀를 조종하고 있는 거죠...",
  ui_story_5014_50141501_51_dialog_content = "난 그것보다 도대체 어떻게 해야 저 고집불통이랑 말이 통할지가 궁금한걸.",
  ui_story_5014_50141502_1_dialog_content = "뒤에... 마지막 한 마리!",
  ui_story_5014_50141502_2_dialog_content = "이쪽에 또 있어! 피어나라, 빙화여!",
  ui_story_5014_50141502_3_dialog_content = "왜 못 이기는 거야... 겨우 세 명을 왜 못 이겨?!",
  ui_story_5014_50141502_4_dialog_content = "세 명? 난 같이 세지도 않는 거야?",
  ui_story_5014_50141502_5_dialog_content = "역시 내 힘이 아직 부족한 거야...",
  ui_story_5014_50141502_6_dialog_content = "내가 힘이 부족해서... 아빠 엄마가 돌아가셨어...",
  ui_story_5014_50141502_7_dialog_content = "내 힘이 부족해서... 너희 같은 녀석들이 침입하고...\n언니가 위험해진 거라고!",
  ui_story_5014_50141502_8_dialog_content = "그레텔, 부모님을 생각해 보세요.\n그분들은 당신이 이러는 걸 원치 않을 거예요...",
  ui_story_5014_50141502_9_dialog_content = "엄마 아빠를 생각하라고...?",
  ui_story_5014_50141502_10_dialog_content = "생각하고 있어. 난 계속 생각해 왔다고...",
  ui_story_5014_50141502_11_dialog_content = "계속 생각했어. 아빠랑 엄마가 있었으면 좋았을 텐데...\n그랬으면 너희들이...",
  ui_story_5014_50141502_12_dialog_content = "너희 같은 게... 나랑 언니를 괴롭히지도 않았을 거라고...",
  ui_story_5014_50141502_13_dialog_content = "그레텔, 진정해. 언니가 먼저 아빠 유언장부터 읽게 해주지 않겠니?",
  ui_story_5014_50141502_14_dialog_content = "흐윽...",
  ui_story_5014_50141502_15_dialog_content = "발렌시아, 당신 부모님은 출구를 찾다가 암귀에게 공격을 받은 거죠?",
  ui_story_5014_50141502_16_dialog_content = "맞아, 근데 그레텔은 기억 못 해... 나도 그 얘긴 하고 싶지 않아.",
  ui_story_5014_50141502_17_dialog_content = "여보, 또 지진이야.",
  ui_story_5014_50141502_18_dialog_content = "그러게. 이대로는 좋지 않아.",
  ui_story_5014_50141502_19_dialog_content = "아니면... 출구를 찾는 건 일단 그만두자.\n지진이 가라앉고 난 후에 찾는 게 좋겠어.",
  ui_story_5014_50141502_20_dialog_content = "나도 그러려던 참이야. 이 도시엔 그나마 방호시설도 있으니까.",
  ui_story_5014_50141502_21_dialog_content = "우선 돌아가자...",
  ui_story_5014_50141502_22_dialog_content = "캬아악!",
  ui_story_5014_50141502_23_dialog_content = "암귀가 여길 발견했다고?!",
  ui_story_5014_50141502_24_dialog_content = "이런, 경비 로봇은 지진 때문에...",
  ui_story_5014_50141502_25_dialog_content = "어서 가자, 이쪽으로!",
  ui_story_5014_50141502_26_dialog_content = "머리가... 아파. 기억하기 싫어... 안 돼... 훌쩍...",
  ui_story_5014_50141502_27_dialog_content = "그레텔, 왜 그래?! 언니 여기 있어. 무서워하지 마....",
  ui_story_5014_50141502_28_dialog_content = "<color=#e8d9bb>퍼어엉!</color>",
  ui_story_5014_50141502_29_dialog_content = "엄마, 이쪽이야! 빨리!",
  ui_story_5014_50141502_30_dialog_content = "<color=#e8d9bb>철컹, 철컹, 철컹...</color>",
  ui_story_5014_50141502_31_dialog_content = "왜, 왜 안 열려? 엄마! 문이 안 열려!",
  ui_story_5014_50141502_32_dialog_content = "문을 못 열겠어!",
  ui_story_5014_50141502_33_dialog_content = "엄마가 문을 잠갔어... 걱정하지 말고 안에 있어...",
  ui_story_5014_50141502_34_dialog_content = "숨어 있어... 괜찮을 거야.",
  ui_story_5014_50141502_35_dialog_content = "발렌시아, 그레텔... 절대 밖으로 나오면 안 돼... 크윽!",
  ui_story_5014_50141502_36_dialog_content = "엄마?",
  ui_story_5014_50141502_37_dialog_content = "엄마, 왜 그래?!",
  ui_story_5014_50141502_38_dialog_content = "엄마... 훌쩍... 문 열어 줘... 제발...",
  ui_story_5014_50141502_39_dialog_content = "잊지 마... 동생을... 꼭... 지켜주렴...",
  ui_story_5014_50141502_40_dialog_content = "......",
  ui_story_5014_50141502_41_dialog_content = "으아아아아아!",
  ui_story_5014_50141502_42_dialog_content = "<color=#e8d9bb>콰콰쾅──!</color>",
  ui_story_5014_50141502_43_dialog_content = "몸에서 엄청난 에너지가 폭발했어!",
  ui_story_5014_50141502_44_dialog_content = "<color=#e8d9bb>경보! 경보!</color>",
  ui_story_5014_50141502_45_dialog_content = "<color=#e8d9bb>불법 접속, 침입...자! 현재... 코어 구역으로... 진입 중!</color>",
  ui_story_5014_50141502_46_dialog_content = "설마 플로리나 쪽인가?",
  ui_story_5014_50141502_47_dialog_content = "집사가 말했어... 반드시... 코어를 지켜야 한다고...",
  ui_story_5014_50141502_48_dialog_content = "<color=#e8d9bb>침입자는... 모든 것을... 파괴할... 것입니다...</color>",
  ui_story_5014_50141502_49_dialog_content = "<color=#e8d9bb>모든 것을... 파괴할... 것입니다!</color>",
  ui_story_5014_50141502_50_dialog_content = "헛소리예요!",
  ui_story_5014_50141502_51_dialog_content = "여긴 애초부터 무너지고 있었어요. 우리 일행은 지금 출구를 찾고 있어요!",
  ui_story_5014_50141502_52_dialog_content = "집사를 위해... 너흴 없애겠어!",
  ui_story_5014_50141502_53_dialog_content = "끼기긱!",
  ui_story_5014_50141601_1_dialog_content = "공격해!",
  ui_story_5014_50141601_2_dialog_content = "끼익──",
  ui_story_5014_50141601_3_dialog_content = "다시, 전부 공격해!",
  ui_story_5014_50141601_4_dialog_content = "끼기긱...",
  ui_story_5014_50141601_5_dialog_content = "집사, 계속해! 뭘 멍하니 있어!",
  ui_story_5014_50141601_6_dialog_content = "<color=#e8d9bb>프로그램 클리어, 프로그램 클리어...</color>",
  ui_story_5014_50141601_7_dialog_content = "저기도 암귀들이 잔뜩 있잖아! 명령해!",
  ui_story_5014_50141601_8_dialog_content = "<color=#e8d9bb>지령, 무차별 대상, 전체 실행!</color>",
  ui_story_5014_50141601_9_dialog_content = "그르르...",
  ui_story_5014_50141601_10_dialog_content = "캬아악!",
  ui_story_5014_50141601_11_dialog_content = "집사한테 암귀를 조종하라고 한 건가요?",
  ui_story_5014_50141601_12_dialog_content = "그레텔이 로봇을 조종할 수 있는 건...\n로봇을 만든 집사가 그레텔의 명령을 듣기 때문이에요.",
  ui_story_5014_50141601_13_dialog_content = "근데 암귀에게 명령할 수 있다는 건...",
  ui_story_5014_50141601_14_dialog_content = "암귀도 모두 집사가 만들었다는 거 아닌가요?",
  ui_story_5014_50141601_15_dialog_content = "집사는 그 점을 부정하고 있어요.",
  ui_story_5014_50141601_16_dialog_content = "거짓말을 한 거겠지...\n「집사는 거짓말을 하지 않는다」는 것도 자매를 속인 거야.",
  ui_story_5014_50141601_17_dialog_content = "어쨌든, 먼저 이 적들부터 처리해야만 해.",
  ui_story_5014_50141601_18_dialog_content = "하지만 끝도 없잖아...",
  ui_story_5014_50141601_19_dialog_content = "그럼 먼저 명령을 내리는...",
  ui_story_5014_50141601_X19_dialog_content = "그레텔을 제압하는 수밖에 없어.",
  ui_story_5014_50141601_20_dialog_content = "<color=#e8d9bb>경고, 고등급 위험 감지... 그레텔, 어서 도망치십시오.</color>",
  ui_story_5014_50141601_21_dialog_content = "자, 잠깐만! 그레텔을 공격하지 마!",
  ui_story_5014_50141601_22_dialog_content = "저 애는 자기가 뭘 하고 있는지 몰라!",
  ui_story_5014_50141601_23_dialog_content = "공격... 공격해... 저, 전부...",
  ui_story_5014_50141601_24_dialog_content = "깨끗이 해치워버려...!",
  ui_story_5014_50141601_25_dialog_content = "<color=#e8d9bb>경고, 최우선 보호 대상이... 위협을 받는 중입니다.</color>",
  ui_story_5014_50141601_26_dialog_content = "이거 곤란한데... 집사는 우리가 그레텔을 해치려고 한다고 판단했어.",
  ui_story_5014_50141601_27_dialog_content = "<color=#e8d9bb>퍼엉! 퍼어엉!</color>",
  ui_story_5014_50141601_28_dialog_content = "가까이 오지 마. 그레텔을 해치게 두진 않을 테니까!",
  ui_story_5014_50141601_29_dialog_content = "오지 말라고!",
  ui_story_5014_50141601_30_dialog_content = "난... 지킬 거야... 더... 더 강해져야... 가족을...",
  ui_story_5014_50141601_31_dialog_content = "언니를...",
  ui_story_5014_50141601_32_dialog_content = "그레텔, 진정해! 언니 말 좀 들어... 감정을 추슬러!",
  ui_story_5014_50141601_33_dialog_content = "발렌시아, 우리가 도와줄게. 내가 도와줄 수 있을지도 몰라!",
  ui_story_5014_50141601_34_dialog_content = "오지 마!",
  ui_story_5014_50141601_35_dialog_content = "동생한테 가까이 오지 말라고!",
  ui_story_5014_50141602_1_dialog_content = "언...니...",
  ui_story_5014_50141602_2_dialog_content = "그레텔... 다행이야... 정신을 차렸구나!",
  ui_story_5014_50141602_3_dialog_content = "움직이면 안 돼... 좀 쉬어...",
  ui_story_5014_50141602_4_dialog_content = "집사, 얼른 그레텔을 검사해 줘!",
  ui_story_5014_50141602_5_dialog_content = "<color=#e8d9bb>알겠습니다, 검사를, 시작합니다...</color>",
  ui_story_5014_50141602_6_dialog_content = "미안해요. 아까 그 상황에서는 어쩔 수 없었어요...",
  ui_story_5014_50141602_7_dialog_content = "다치진 않았나요?",
  ui_story_5014_50141602_8_dialog_content = "난 괜찮아... 그래도 동생은 너흴 싫어하니까... 가까이 오지 마...",
  ui_story_5014_50141602_9_dialog_content = "동생은 쉽게 자극을 받고... 흥분하게 되니까.",
  ui_story_5014_50141602_10_dialog_content = "알겠어요. 이제 진정이 된 것 같네요. 저희도 가까이 가진 않을게요.",
  ui_story_5014_50141602_11_dialog_content = "<color=#e8d9bb>쿠르르릉──!</color>",
  ui_story_5014_50141602_12_dialog_content = "발렌시아, 또 지진이에요. 이대로는 좋지 않아요...",
  ui_story_5014_50141602_13_dialog_content = "아빠의 유언장을 읽을 테니까... 시간이 더 필요해.",
  ui_story_5014_50141602_14_dialog_content = "알겠어요. 서두르지 않아도 돼요. 천천히 읽어도 돼요...",
  ui_story_5014_50141602_15_dialog_content = "거기서 기다리고 있어. 우리한테 가까이 오지도 말고, 다른 데 가지도 마...",
  ui_story_5014_50141602_16_dialog_content = "집사, 로봇한테 저들을 감시하게 해... 우린 안전한 곳으로 가자.",
  ui_story_5014_50141602_17_dialog_content = "<color=#e8d9bb>알겠습니다.</color>",
  ui_story_5014_50141602_18_dialog_content = "발렌시아.",
  ui_story_5014_50141602_19_dialog_content = "네가 이 편지를 읽을 때면, 아빠는 아마 이 세상에 없을지도 모르겠구나.",
  ui_story_5014_50141602_20_dialog_content = "내가 어떻게 세상을 떠날지는 알 수 없겠지.\n하지만 어떤 방식이든 내가 원하는 것은 아닐 거다.",
  ui_story_5014_50141602_21_dialog_content = "왜냐면 난 진심으로 너희와 계속 함께 있고 싶으니 말이다.",
  ui_story_5014_50141602_22_dialog_content = "그러나 불행히도 이 세계, 그리고 운명은 우릴 위해 만들어진 건 아니란다.",
  ui_story_5014_50141602_23_dialog_content = "한때 나와 네 엄마는 많은 좌절을 겪었고, 심지어 희망을 잃은 적도 있었지.",
  ui_story_5014_50141602_24_dialog_content = "하지만 너희가 찾아온 덕분에 모든 것이 변했단다.",
  ui_story_5014_50141602_25_dialog_content = "네 웃는 얼굴을 볼 때마다, 나는 더 굳은 신념을 얻을 수 있었다.",
  ui_story_5014_50141602_26_dialog_content = "너희들에게 반드시 더 나은 삶을 주겠다는 신념 말이다.",
  ui_story_5014_50141602_27_dialog_content = "어쩌면 네가 벌써 이 「집」을 떠나,\n광활하고 진실한 대지를 밟고 있을지도 모르겠구나.",
  ui_story_5014_50141602_28_dialog_content = "아니면 강인한 마음으로 그곳을 지키며, 여동생과 어머니를 보살피고 있을지도 모르지.",
  ui_story_5014_50141602_29_dialog_content = "어느 쪽이든 모두 잘했다. 발렌시아, 넌 나의 영원한 자랑이란다.",
  ui_story_5014_50141602_30_dialog_content = "만약 네가 정말 그곳을 떠났다면, 나는 안심도 되지만, 조금 걱정도 되는구나.",
  ui_story_5014_50141602_31_dialog_content = "너흰 산과 강, 호수와 바다를 보며, 사시사철 변하는 초원을 밟고,\n태양은 너희의 머리 위를 지나쳐 오르고 저물겠지.",
  ui_story_5014_50141602_32_dialog_content = "넌 동생과 엄마의 손을 잡고, 새로운 집을 짓고,\n새 옷을 만들고, 밥 짓는 연기 냄새를 맡게 되겠지.",
  ui_story_5014_50141602_33_dialog_content = "밤과 낮에는 고개를 들어 진짜 하늘을 얼마든지 보고 있겠지.",
  ui_story_5014_50141602_34_dialog_content = "하지만 어둠의 일면도 보게 될 거란다.",
  ui_story_5014_50141602_35_dialog_content = "뼛속까지 파고드는 추위, 소스라치는 바람,\n상상조차 할 수 없는 무서운 적과도 만나게 될 거다.",
  ui_story_5014_50141602_36_dialog_content = "하지만 그것들은 널 쓰러트릴 수 없단다, 발렌시아.",
  ui_story_5014_50141602_37_dialog_content = "이 편지를 읽을 때면, 너는 이미 어엿한 어른이 되었을 테니까.",
  ui_story_5014_50141602_38_dialog_content = "일루미나의 동포들은 반드시 어려움과 위험을 이겨내고,\n너흴 찾아서 받아줄 거다.",
  ui_story_5014_50141602_39_dialog_content = "그리고 넌 우리의 대가족을 만나게 될 거란다.",
  ui_story_5014_50141602_40_dialog_content = "어쩌면 너도 나와 네 엄마처럼 온갖 어려움을 겪고 나서...",
  ui_story_5014_50141602_41_dialog_content = "항상 자신의 곁을 지켜줄, 새로운 거처가 되어줄 사람을 찾을지도 모르겠구나.",
  ui_story_5014_50141602_42_dialog_content = "아, 그걸 생각하니 아빠도 왠지 조금 질투가 난다...",
  ui_story_5014_50141602_43_dialog_content = "그때 네 곁을 지켜줄 사람은 과연 어떤 사람일까. 아빠도 만나보고 싶구나.",
  ui_story_5014_50141602_44_dialog_content = "그런 아름다운 미래가 현실이 된다면, 나는 어떤 대가든 치를 수 있단다.",
  ui_story_5014_50141602_45_dialog_content = "다만 유감스럽게도, 지금 우리의 삶은 타인의 제한을 받고 있다...",
  ui_story_5014_50141602_46_dialog_content = "아니, 그건 사람보다 훨씬 복잡한... 고대의 인공지능이다.",
  ui_story_5014_50141602_47_dialog_content = "만약, 그때도 뜻을 이루지 못하고... 그 미래들을 현실로 이루지 못했다면,\n너는 이제부터 내가 말하는 것을 반드시 기억해 두길 바란다.",
  ui_story_5014_50141602_48_dialog_content = "이곳은 언젠가 반드시 괴멸할 때가 온다. 집사도 그건 막을 수 없어.",
  ui_story_5014_50141602_49_dialog_content = "모든 것이 무너지고 부서지기 시작할 때,\n나는 네가 곁에 있는 사람의 손을 잡고 함께 맞섰으면 좋겠구나.",
  ui_story_5014_50141602_50_dialog_content = "그때가 되면 이 도시는 더는 너희들의 집이 아니게 될 거란다.\n너와 가까운 소중한 사람이 있는 곳이야말로...",
  ui_story_5014_50141602_51_dialog_content = "「...진짜 집이 될 테니까.」",
  ui_story_5014_50141602_52_dialog_content = "아빠...",
  ui_story_5014_50141602_53_dialog_content = "그레텔, 난 저 사람들을 다시 믿어보고 싶어...",
  ui_story_5014_50141602_54_dialog_content = "...그레텔? 집사? 어디 갔어?",
  ui_story_5014_50141602_55_dialog_content = "시오반 씨...",
  ui_story_5014_50141602_56_dialog_content = "다행이에요. 드디어 나왔군요.",
  ui_story_5014_50141602_57_dialog_content = "그레텔이 이곳을 떠난 걸 느꼈어. 난 그래서 너희가...",
  ui_story_5014_50141602_58_dialog_content = "그레텔은 집사랑 어디론가 가버렸어... 나한테 아무 말도 안 했어.",
  ui_story_5014_50141602_59_dialog_content = "<color=#e8d9bb>콰아앙──</color>",
  ui_story_5014_50141602_60_dialog_content = "<color=#e8d9bb>치직── 치직──</color>",
  ui_story_5014_50141602_61_dialog_content = "...하늘 좀 봐!",
  ui_story_5014_50141602_62_dialog_content = "시작됐어요... 지하도시가 무너지기 시작한 거예요.",
  ui_story_5014_50141602_63_dialog_content = "아빠가 「이곳은 언젠가 반드시 괴멸할 때가 온다」고 했어... 저 하늘은...",
  ui_story_5014_50141602_64_dialog_content = "저건 고대인이 만든 모니터일 거예요. 그리고 이 지하도시의 지붕이겠죠.",
  ui_story_5014_50141602_65_dialog_content = "이제 저것들도 곧 떨어질 거예요. 여기 있는 건물들처럼...",
  ui_story_5014_50141602_66_dialog_content = "붕괴되고 부서져서... 영원히 지하에 묻히겠죠.",
  ui_story_5014_50141602_67_dialog_content = "하지만 당신 아버지는 당신과 그레텔이 지하에서 생을 끝내길 원치 않았어요...",
  ui_story_5014_50141602_68_dialog_content = "그러니까 계속 출구를 찾고, 코어를 복구하려고 하고,\n바깥세상에 메시지를 계속 보냈던 거예요.",
  ui_story_5014_50141602_69_dialog_content = "하지만 저 집사는 계속 그걸 막았죠.",
  ui_story_5014_50141602_70_dialog_content = "당신 아버지는 집사에게 들키지 않기 위해서...\n이런 번거로운 방법을 택할 수밖에 없었어요.",
  ui_story_5014_50141602_71_dialog_content = "심지어 당신들에게 직접 전할 수조차 없었죠.",
  ui_story_5014_50141602_72_dialog_content = "발렌시아, 그레텔을 데리고 저희와 함께 떠나요.",
  ui_story_5014_50141602_73_dialog_content = "하지만 그레텔은... 집사랑 같이 가는 걸 선택했어.",
  ui_story_5014_50141602_74_dialog_content = "나한테 한 마디도... 안 하고...",
  ui_story_5014_50141602_75_dialog_content = "어쩌면 그 집사가 그레텔을 속였을 수도 있어.\n동생에겐 지금 당신이 필요해... 발렌시아.",
  ui_story_5014_50141602_76_dialog_content = "발렌시아, 당신은 언니잖아요.\n지난 몇 년 동안 혼자서 동생을 돌보느라 정말 힘들었을 거예요.",
  ui_story_5014_50141602_77_dialog_content = "하지만 그건 당신이 감당해야 할 책임이에요...\n동생에게 무엇이 옳고 그른지를 제대로 가르쳐 줘야 해요.",
  ui_story_5014_50141602_78_dialog_content = "맞아. 당신에겐 그걸 가르칠 책임이 있어.\n그 책임을 집사에게 맡겨둬선 안 돼.",
  ui_story_5014_50141602_79_dialog_content = "난...",
  ui_story_5014_50141602_80_dialog_content = "당신이 계속 노력해 온 것도 알고 있어요...",
  ui_story_5014_50141602_81_dialog_content = "가르친다는 건 결코 쉬운 일이 아니에요.\n경험이 없다면 더 힘들 수밖에 없어요.",
  ui_story_5014_50141602_82_dialog_content = "하지만 지금은 모든 힘을 다해 동생을 설득하고 이끌어 줘야만 해요.",
  ui_story_5014_50141602_83_dialog_content = "동생이 마음을 닫고, 눈앞의 상황을 보지도 않고,\n주변의 말을 듣지 않게 놔둬선 안 돼요.",
  ui_story_5014_50141602_84_dialog_content = "당신도 그렇게 생각하죠?",
  ui_story_5014_50141602_85_dialog_content = "응... 그 말이 맞아.",
  ui_story_5014_50141602_86_dialog_content = "그럼 지금부터 같이 찾으러 가요.\n위험에 처하진 않았을지 걱정이 되니까요.",
  ui_story_5014_50141602_87_dialog_content = "응, 어떻게 해야 할지 이제 알겠어...",
  ui_story_5014_50141602_88_dialog_content = "아빠가 주신 탐지기라면... 동생의 위치를 알 수 있을 거야.",
  ui_story_5014_50141701_1_dialog_content = "지진 때문에 탐지기의 신호에 조금 문제가 있지만...",
  ui_story_5014_50141701_2_dialog_content = "조정해 볼게. 기다려 봐.",
  ui_story_5014_50141701_3_dialog_content = "조정할 방법이 있나요? 도움이 필요하진 않나요?",
  ui_story_5014_50141701_4_dialog_content = "괜찮아... 고칠 수 있어, 시간을 좀 줘.",
  ui_story_5014_50141701_5_dialog_content = "저쪽에 가서 신호를 찾아볼게. 다들 여기서 기다려.",
  ui_story_5014_50141701_6_dialog_content = "우리도 같이 가는 게...",
  ui_story_5014_50141701_7_dialog_content = "내가 도망갈까 걱정하는 거야? 괜찮아, 그러진 않을 테니까.",
  ui_story_5014_50141701_8_dialog_content = "하지만...",
  ui_story_5014_50141701_9_dialog_content = "카렌 양, 그냥 두세요.",
  ui_story_5014_50141701_10_dialog_content = "발렌시아, 그럼 서둘러 주세요. 저흰 여기서 기다리고 있을게요.",
  ui_story_5014_50141701_11_dialog_content = "알겠어.",
  ui_story_5014_50141701_12_dialog_content = "시오반 씨, 정말 보내도 괜찮겠어?",
  ui_story_5014_50141701_13_dialog_content = "신호를 찾는 데 혼자 갈 이유가 있나?",
  ui_story_5014_50141701_14_dialog_content = "신뢰는 양방향으로 이루어져야 해요...\n어쩌면 혼자 마음을 정리하고 싶은 건지도 몰라요.",
  ui_story_5014_50141701_15_dialog_content = "아니면 우릴 시험하고 싶을 수도 있죠.",
  ui_story_5014_50141701_16_dialog_content = "아이의 사고방식은 간단해요. 전 의심하고 싶지 않아요.",
  ui_story_5014_50141701_17_dialog_content = "게다가... 여긴 아이테르가 있으니까, 위치추적기도 가지고 있는 셈이잖아요.",
  ui_story_5014_50141701_18_dialog_content = "응, 엄청 멀리 가지 않는 한, 느낄 수 있어.",
  ui_story_5014_50141701_19_dialog_content = "지금은 아직 그렇게 멀리는 안 갔어...",
  ui_story_5014_50141701_20_dialog_content = "음, 만약 발렌시아가 들으면 우리가 교활하다고 생각하진 않을까?",
  ui_story_5014_50141701_21_dialog_content = "겨우 신용을 얻었는데, 또 그걸 반복하긴...",
  ui_story_5014_50141701_22_dialog_content = "크흠, 그 얘기는 그만하자...",
  ui_story_5014_50141701_23_dialog_content = "휴, 저 자매를 설득하는 게 이렇게 힘들 줄은 몰랐어.\n이게 다 시모스 씨가 말을 남긴 방식이 너무 복잡해서 그런 거라고.",
  ui_story_5014_50141701_24_dialog_content = "시오반 씨, 아까 시모스가 「집사에게 들키지 않으려」 한다고 했었지?",
  ui_story_5014_50141701_25_dialog_content = "맞아요. 분산과 다중 암호화를 통해 보안을 지키고 있었던 거예요.",
  ui_story_5014_50141701_26_dialog_content = "그러면 일부를 집사가 입수하거나 파괴하더라도 나머지는 남게 되니까요.",
  ui_story_5014_50141701_27_dialog_content = "시모스 씨는 다양한 암호화 방법을 썼고, 암호 키도 바꿨어.",
  ui_story_5014_50141701_28_dialog_content = "클라우드도 비밀 서체로 메시지를 남겼었고.",
  ui_story_5014_50141701_29_dialog_content = "전부 집사가 읽는 걸 피하기 위해서였겠지.",
  ui_story_5014_50141701_30_dialog_content = "맞아요.",
  ui_story_5014_50141701_31_dialog_content = "사실 우린 다른 관점에서 이 문제를 이해해볼 수 있어요.",
  ui_story_5014_50141701_32_dialog_content = "부모의 입장에선 아이들이 이 모든 것을 받아들일 준비가 되어 있는지 알 수 없어요.",
  ui_story_5014_50141701_33_dialog_content = "앞으로 어떤 사람을 만나게 될지도 알 수 없죠.",
  ui_story_5014_50141701_34_dialog_content = "아무리 좋고 나쁨을 구분하는 방법을 가르친다 해도...",
  ui_story_5014_50141701_35_dialog_content = "선한 사람과 악한 사람을 반드시 구별할 수 있도록 만들진 못할 거예요.",
  ui_story_5014_50141701_36_dialog_content = "선한 사람이든 악한 사람이든 거짓말을 할 수 있으니까요.",
  ui_story_5014_50141701_37_dialog_content = "의심하는 태도와 다양한 시각으로 정보를 수집해야만,\n냉정하고 뚜렷한 생각을 가질 수 있어요.",
  ui_story_5014_50141701_38_dialog_content = "시모스 씨는 분명 그렇게 자매를 키워왔을 거예요.",
  ui_story_5014_50141701_39_dialog_content = "하지만 그레텔은 기계가 거짓말을 한다는 의심을 못 하는 것 같았어.",
  ui_story_5014_50141701_40_dialog_content = "시모스 씨 부부가 돌아가셨을 때, 그레텔은 아직 너무 어렸을 테니까요...",
  ui_story_5014_50141701_41_dialog_content = "시오반 선생님, 혹시 아이가 있으신가요?",
  ui_story_5014_50141701_42_dialog_content = "푸웁! 콜록콜록...",
  ui_story_5014_50141701_43_dialog_content = "미, 미안, 갑자기 사레가 들려서... 갑자기 왜 그런 걸 물어봐?",
  ui_story_5014_50141701_44_dialog_content = "아, 미, 미안... 난 그냥 시오반 선생님 말씀이 일리가 있다고 생각해서...",
  ui_story_5014_50141701_45_dialog_content = "부모의 마음을 너무 잘 아시길래...",
  ui_story_5014_50141701_46_dialog_content = "물론 아이는 없어요. 다만 여러 가지 경험을 했었죠...\n전 지금까지 전우 다섯 명의 유언을 들었어요.",
  ui_story_5014_50141701_47_dialog_content = "그들의 유언은 모두 연구 자료를 잘 활용해 달라거나,\n가족을 부탁한다는 내용이었어요.",
  ui_story_5014_50141701_48_dialog_content = "그중에는 자신의 희생을 가족에게 알리고 싶지 않은 사람도 있었고...",
  ui_story_5014_50141701_49_dialog_content = "어떤 사람은 가족들에게 자신을 잊어달라고까지 말하기도 했어요...",
  ui_story_5014_50141701_50_dialog_content = "시오반 선생님...",
  ui_story_5014_50141701_51_dialog_content = "모두 현실인걸요. 어쩌면 여러분도 앞으로 알게 될지도 몰라요...",
  ui_story_5014_50141701_52_dialog_content = "부디 여러분에겐 그런 일이 영원히 닥치지 않길 바라지만,\n탐험의 길은 위험으로 가득 차 있어요.",
  ui_story_5014_50141701_53_dialog_content = "부디 조심해 주세요.",
  ui_story_5014_50141701_54_dialog_content = "네, 명심할게요.",
  ui_story_5014_50141701_55_dialog_content = "<size=33>가족이라...</size>",
  ui_story_5014_50141701_56_dialog_content = "PlayerName, 괜찮아?",
  ui_story_5014_50141701_57_dialog_content = "응... 그냥 옛날 생각이 났을 뿐이야.",
  ui_story_5014_50141701_58_dialog_content = "이 지하도시에서 발렌시아와 그레텔을 꼭 데리고 나가자.",
  ui_story_5014_50141701_59_dialog_content = "그리고 바깥세상을 보여주는 거야...",
  ui_story_5014_50141701_60_dialog_content = "네, 그래요...",
  ui_story_5014_50141701_61_dialog_content = "그럼 잡담은 이 정도로 하죠.\n바이스, 플로리나에게 연락해 보세요.",
  ui_story_5014_50141701_62_dialog_content = "뭔가 새로운 소식이 있는지 말이에요.",
  ui_story_5014_50141701_63_dialog_content = "알겠어요.",
  ui_story_5014_50141701_64_dialog_content = "시오반 씨, 동생이 어디 있는지 찾았어.",
  ui_story_5014_50141701_65_dialog_content = "지금 도시 심층부로 가고 있어...\n분명히 집사가 데리고 가고 있을 거야.",
  ui_story_5014_50141701_66_dialog_content = "도시 심층부라... 플로리나 쪽도 지금 심층부 입구를 찾고 있어요.",
  ui_story_5014_50141701_67_dialog_content = "이쪽도 소식이 왔어요!",
  ui_story_5014_50141701_68_dialog_content = "플로리나가 입구와 통로를 찾았대요.",
  ui_story_5014_50141701_69_dialog_content = "방금 전에 로봇과 암귀를 처치하고 좌표를 보내줬어요.",
  ui_story_5014_50141701_70_dialog_content = "발렌시아, 우린 플로리나 쪽으로 가서 그쪽과 합류할 거예요. 괜찮나요?",
  ui_story_5014_50141701_71_dialog_content = "응... 집사가 로봇을 시켜서 그 사람들을 공격할까 걱정이야.",
  ui_story_5014_50141701_72_dialog_content = "내가 있으면 로봇이 공격하지 않을 거야...\n그럼 그 사람들도 지킬 수 있어.",
  ui_story_5014_50141701_73_dialog_content = "그래요, 고마워요. 발렌시아.",
  ui_story_5014_50141701_74_dialog_content = "아니, 이건 내가 해야 할 일이야... 나도 책임을 다해야지... 어서 가자...",
  ui_story_5014_50141701_75_dialog_content = "좋아, 내가 앞장설게!",
  ui_story_5014_50141701_76_dialog_content = "목적지는 이 앞이야. 거의 다 왔어.",
  ui_story_5014_50141701_77_dialog_content = "플로리나가 마지막으로 보낸 위치 좌표는 여기야.",
  ui_story_5014_50141701_78_dialog_content = "여기가 제어 시스템과 에너지 코어로 가는 길이야?",
  ui_story_5014_50141701_79_dialog_content = "확실해요. 이 밑에는 분명히 지하도시를 벗어나는 방법과...",
  ui_story_5014_50141701_80_dialog_content = "당신이 꿈꾸던 과학 기술이 숨겨져 있겠지?",
  ui_story_5014_50141701_81_dialog_content = "맞아요.",
  ui_story_5014_50141701_82_dialog_content = "시오반 씨.",
  ui_story_5014_50141701_83_dialog_content = "왜 그러죠? 발렌시아.",
  ui_story_5014_50141701_84_dialog_content = "사실 난... 아빠한테 있어서 좋은 학생은 아니었어.",
  ui_story_5014_50141701_85_dialog_content = "그게 무슨 말이죠...?",
  ui_story_5014_50141701_86_dialog_content = "난 아빠가 가르쳐준 기술을... 제대로 배우지 못했거든.",
  ui_story_5014_50141701_87_dialog_content = "그 자료들은 가져가도 좋아.",
  ui_story_5014_50141701_88_dialog_content = "일루미나로 가져가서 연구해.",
  ui_story_5014_50141701_89_dialog_content = "음... 알겠어요.",
  ui_story_5014_50141701_90_dialog_content = "하지만 그레텔은... 그 애가 무슨 말을 하든, 어떤 행동을 하든...",
  ui_story_5014_50141701_91_dialog_content = "너무 마음에 담아 두지 않았으면 좋겠어.",
  ui_story_5014_50141701_92_dialog_content = "동생이 했던 일과 행동은... 내가 대신 사과할게.",
  ui_story_5014_50141701_93_dialog_content = "그리고 반드시 내가 동생을 설득할게.",
  ui_story_5014_50141701_94_dialog_content = "일루미나인으로서 당신에게 약속할게요.",
  ui_story_5014_50141701_95_dialog_content = "우리 모두는 당신 아버지가 원했던 대로, 손을 잡고...",
  ui_story_5014_50141701_96_dialog_content = "함께 난관을 극복하고 이 지하도시에서 나갈 거예요.",
  ui_story_5014_50141701_97_dialog_content = "<color=#e8d9bb>콰르릉...!</color>",
  ui_story_5014_50141701_98_dialog_content = "또 지진인가...",
  ui_story_5014_50141701_99_dialog_content = "아니야... 이번엔 뭔가 달라!",
  ui_story_5014_50141701_100_dialog_content = "발밑을 조심해!",
  ui_story_5014_50141701_101_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5014_50141701_102_dialog_content = "...너...너는?",
  ui_story_5014_50141701_103_dialog_content = "<color=#e8d9bb>안녕하십니까. 저는 이 지하 피난소의 관리자입니다.</color>",
  ui_story_5014_50141701_104_dialog_content = "<color=#e8d9bb>집사라고 부르면 됩니다.</color>"
}
